function Game3.lotteryMatchingDigits(win, otId)
  win = (tonumber(win) or 0) % 65536
  otId = (tonumber(otId) or 0) % 65536
  local n = 0
  for _ = 1, 5 do
    if (win % 10) ~= (otId % 10) then break end
    win = math.floor(win / 10)
    otId = math.floor(otId / 10)
    n = n + 1
  end
  return n
end

function Game3:pickLotteryCornerTicket()
  local win = self:varGet(Gen3Script.VAR_RESULT)
  self:setScriptVar(0x8004, 0)
  local best, where, mon = 0, nil, nil
  local function consider(candidate, loc)
    if not candidate or (candidate.species or 0) == 0 or candidate.isEgg then
      return
    end
    local n = Game3.lotteryMatchingDigits(win, candidate.otId or 0)
    if n > best and n > 1 then
      best, where, mon = n, loc, candidate
    end
  end
  local party = self.party or {}
  for i = 1, #party do consider(party[i], 0) end
  self:ensurePc()
  for b = 1, Game3.BOX_COUNT do
    local box = self.pc[b]
    if type(box) == "table" then
      for s = 1, Game3.BOX_SIZE do consider(box[s], 1) end
    end
  end
  if best > 1 and mon then
    local rank = best - 1
    self:setScriptVar(0x8004, rank)
    self:setScriptVar(0x8005, Game3.LOTTERY_PRIZES[rank] or 0)
    self:setScriptVar(0x8006, where)
    self:setStringVar(1, mon.name or self:speciesName(mon.species))
  end
end

function Game3:gabbyAndTyGetLastQuote()
  local d = self:ensureGabbyAndTy()
  if (d.quote or Game3.EC_EMPTY_WORD) == Game3.EC_EMPTY_WORD then
    return 0
  end
  self:setStringVar(1, Game3.ecWordText(d.quote))
  d.quote = Game3.EC_EMPTY_WORD
  return 1
end

-- !valB_0 (not damaged) → 1; balls → 2; heal → 3; faint → 4; else 0.
-- 0 is valid (damaged, no extra trivia).
function Game3:gabbyAndTyGetLastBattleTrivia()
  local d = self:ensureGabbyAndTy()
  if (d.valB_0 or 0) == 0 then return 1 end
  if (d.valB_3 or 0) ~= 0 then return 2 end
  if (d.valB_2 or 0) ~= 0 then return 3 end
  if (d.valB_1 or 0) ~= 0 then return 4 end
  return 0
end

-- tv.c switch has no case 0: first fight still calls this after
-- BeforeInterview increments 0→1, so case 1 is Route 111 pair 1.
function Game3:getGabbyAndTyLocalIds()
  local pair = Game3.GABBY_TY_LOCAL_IDS[self:gabbyAndTyGetBattleNum()]
  if not pair then return end
  self:setScriptVar(0x8004, pair.gabby)
  self:setScriptVar(0x8005, pair.ty)
end

function Game3:stepEasyChat(f)
  local n = #(f.labels or {})
  if n < 1 then n = 1 end
  if Input:wasPressed("down") then
    local nxt = (f.cursor or 0) + 1
    if nxt >= n then f.cursor = 0 else f.cursor = nxt end
  elseif Input:wasPressed("up") then
    local prev = (f.cursor or 0) - 1
    if prev < 0 then f.cursor = n - 1 else f.cursor = prev end
  elseif Input:wasPressed("a") then
    local pack = f.packs and f.packs[(f.cursor or 0) + 1]
    if pack then f.words[(f.slot or 0) + 1] = pack end
    local last = (f.slots or 2) - 1
    if (f.slot or 0) < last then
      self:openEasyChatSlot(f, (f.slot or 0) + 1)
    else
      self:finishEasyChat(true)
    end
  elseif Input:wasPressed("b") then
    if (f.slot or 0) == 0 then
      self:finishEasyChat(false)
    else
      self:openEasyChatSlot(f, (f.slot or 0) - 1)
    end
  end
end

function Game3.stripEos(s)
  if type(s) ~= "string" then return "" end
  return (s:gsub("%$", ""):gsub("{POKEBLOCK}", "POKeBLOCK"))
end

function Game3.bardLyricString(lyrics)
  if type(lyrics) ~= "table" then return "" end
  local a = Game3.ecWordText(lyrics[1])
  local b = Game3.ecWordText(lyrics[2])
  local c = Game3.ecWordText(lyrics[3])
  local d = Game3.ecWordText(lyrics[4])
  local e = Game3.ecWordText(lyrics[5])
  local f = Game3.ecWordText(lyrics[6])
  return (a .. " " .. b .. " " .. c .. "\n" .. d .. " " .. e .. " " .. f)
    :gsub(" +", " "):gsub(" \n", "\n")
end

function Game3:getGameStat(id)
  id = tonumber(id) or 0
  if id == Game3.NUM_GAME_STATS then id = 0 end
  self.gameStats = self.gameStats or {}
  return self.gameStats[id] or 0
end

function Game3:ensureMauvilleMan()
  local man = self.mauvilleMan
  if type(man) == "table" and man.id ~= nil then return man end
  return self:setupMauvilleOldMan()
end

function Game3:setupMauvilleOldMan(skipGfx)
  local digit = math.floor(self:playerTrainerIdOnesDigit() / 2)
  if digit == Game3.MAUVILLE_MAN_HIPSTER then
    self.mauvilleMan = { id = Game3.MAUVILLE_MAN_HIPSTER, alreadySpoken = 0 }
  elseif digit == Game3.MAUVILLE_MAN_TRADER then
    local items, names = {}, {}
    for i = 1, 4 do
      items[i] = Game3.TRADER_DECORATIONS[i]
      names[i] = Game3.TRADER_OWNERS[i]
    end
    self.mauvilleMan = {
      id = Game3.MAUVILLE_MAN_TRADER, alreadyTraded = 0,
      items = items, names = names,
    }
  elseif digit == Game3.MAUVILLE_MAN_STORYTELLER then
    self.mauvilleMan = {
      id = Game3.MAUVILLE_MAN_STORYTELLER, alreadyRecorded = 0,
      gameStatIDs = { 0, 0, 0, 0 },
      statValues = { 0, 0, 0, 0 },
      trainerNames = { "", "", "", "" },
    }
  elseif digit == Game3.MAUVILLE_MAN_GIDDY then
    self.mauvilleMan = { id = Game3.MAUVILLE_MAN_GIDDY, taleCounter = 0 }
  else
    local lyrics = {}
    for i = 1, 6 do lyrics[i] = Game3.DEFAULT_BARD_LYRICS[i] end
    self.mauvilleMan = {
      id = Game3.MAUVILLE_MAN_BARD, hasChangedSong = 0,
      songLyrics = lyrics, temporaryLyrics = nil,
    }
  end
  if not skipGfx then self:setMauvilleOldManGfx() end
  return self.mauvilleMan
end

function Game3:setMauvilleOldManGfx()
  local man = self:ensureMauvilleMan()
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0, Game3.GFX_BARD + (man.id or 0))
end

function Game3:getCurrentMauvilleMan()
  return self:ensureMauvilleMan().id or 0
end

function Game3:hasBardSongBeenChanged()
  local man = self:ensureMauvilleMan()
  return (man.hasChangedSong or 0) ~= 0 and 1 or 0
end

function Game3:saveBardSongLyrics()
  local man = self:ensureMauvilleMan()
  local src = man.temporaryLyrics or man.songLyrics
  local lyrics = {}
  for i = 1, 6 do lyrics[i] = src and src[i] or 0 end
  man.songLyrics = lyrics
  man.hasChangedSong = 1
  man.playerName = self:playerName()
end

function Game3:playBardSong()
  local man = self:ensureMauvilleMan()
  local useTemp = (self:varGet(0x8004) or 0) ~= 0
  local lyrics = man.songLyrics
  if useTemp and man.temporaryLyrics then lyrics = man.temporaryLyrics end
  self:beginScriptWait()
  self.field = {
    kind = "bard_song",
    text = Game3.bardLyricString(lyrics),
  }
end

function Game3:getHipsterSpokenFlag()
  local man = self:ensureMauvilleMan()
  return (man.alreadySpoken or 0) ~= 0 and 1 or 0
end

function Game3:setHipsterSpokenFlag()
  self:ensureMauvilleMan().alreadySpoken = 1
end

function Game3:trendySayingUnlocked(i)
  local u = self.trendyUnlocked
  return type(u) == "table" and u[i] and true or false
end

function Game3:unlockTrendySaying(i)
  i = tonumber(i) or 0
  if i < 1 or i > Game3.TRENDY_SAYING_COUNT then return end
  self.trendyUnlocked = self.trendyUnlocked or {}
  self.trendyUnlocked[i] = true
end

function Game3:countTrendyUnlocked()
  local n = 0
  for i = 1, Game3.TRENDY_SAYING_COUNT do
    if self:trendySayingUnlocked(i) then n = n + 1 end
  end
  return n
end

-- new_game.c calls sub_80EB8EC once so one trendy word is already on.
function Game3:unlockRandomTrendySaying()
  local left = Game3.TRENDY_SAYING_COUNT - self:countTrendyUnlocked()
  if left < 1 then return 0xFFFF end
  local pick = (self:rand(left) or 1) - 1
  for i = 1, Game3.TRENDY_SAYING_COUNT do
    if not self:trendySayingUnlocked(i) then
      if pick == 0 then
        self:unlockTrendySaying(i)
        return Game3.ecPack(Game3.EC_GROUP_TRENDY_SAYING, i - 1)
      end
      pick = pick - 1
    end
  end
  return 0xFFFF
end

function Game3:hipsterTeachWord()
  local word = self:unlockRandomTrendySaying()
  if word == 0xFFFF then return 0 end
  self:setStringVar(1, Game3.ecWordText(word))
  return 1
end

function Game3:giddyShouldTellAnotherTale()
  local man = self:ensureMauvilleMan()
  if (man.taleCounter or 0) == 10 then
    man.taleCounter = 0
    return 0
  end
  return 1
end

function Game3:ecGroupSize(group)
  local list = Game3.EC_WORDS[group]
  if type(list) == "table" then return #list end
  return 0
end

function Game3:giddyShuffleQuestions()
  local q = {}
  for i = 1, 8 do q[i] = i end
  for i = 1, 8 do
    local r = self:rand(i) or 1
    q[i], q[r] = q[r], q[i]
  end
  return q
end

function Game3:generateGiddyLine()
  local man = self:ensureMauvilleMan()
  if (man.taleCounter or 0) == 0 then
    man.questionList = self:giddyShuffleQuestions()
    man.questionNum = 1
    local groups = {
      Game3.EC_GROUP_LIFESTYLE, Game3.EC_GROUP_HOBBIES,
      Game3.EC_GROUP_PEOPLE, Game3.EC_GROUP_SPEECH,
      Game3.EC_GROUP_ACTIONS, Game3.EC_GROUP_ADJECTIVES,
    }
    local words = {}
    for i = 1, 10 do
      local r = (self:rand(10) or 1) - 1
      if r < 3 then
        words[i] = 0xFFFF
      else
        local g = groups[((self:rand(#groups) or 1) - 1) % #groups + 1]
        words[i] = self:ecRandomWord(g)
      end
    end
    man.randomWords = words
  end
  local idx = (man.taleCounter or 0) + 1
  local word = man.randomWords and man.randomWords[idx]
  if word and word ~= 0xFFFF then
    local adj = Game3.GIDDY_ADJECTIVES[(self:rand(8) or 1)]
    self:setStringVar(4, Game3.ecWordText(word) .. " is" .. (adj or " so pretty!")
      .. "\nDon't you agree?")
  else
    local qn = man.questionNum or 1
    local qi = man.questionList and man.questionList[qn] or qn
    man.questionNum = qn + 1
    self:setStringVar(4, Game3.GIDDY_QUESTIONS[qi] or Game3.GIDDY_QUESTIONS[1])
  end
  if ((self:rand(10) or 1) - 1) == 0 then
    man.taleCounter = 10
  else
    man.taleCounter = (man.taleCounter or 0) + 1
  end
  return 1
end

function Game3:storyByStat(stat)
  local list = Game3.STORYTELLER_STORIES
  for i = 1, #list do
    if list[i].stat == stat then return list[i] end
  end
  return list[#list]
end

function Game3:storytellerFreeSlot()
  local man = self:ensureMauvilleMan()
  local ids = man.gameStatIDs or {}
  for i = 1, 4 do
    if (ids[i] or 0) == 0 then return i - 1 end
  end
  return 4
end

function Game3:storytellerAlreadyRecorded()
  local man = self:ensureMauvilleMan()
  return (man.alreadyRecorded or 0) ~= 0 and 1 or 0
end

function Game3:storytellerRecord(slot, stat)
  local man = self:ensureMauvilleMan()
  man.gameStatIDs = man.gameStatIDs or { 0, 0, 0, 0 }
  man.statValues = man.statValues or { 0, 0, 0, 0 }
  man.trainerNames = man.trainerNames or { "", "", "", "" }
  local i = slot + 1
  man.gameStatIDs[i] = stat
  man.statValues[i] = self:getGameStat(stat)
  man.trainerNames[i] = self:playerName()
  man.alreadyRecorded = 1
  local story = self:storyByStat(stat)
  self:setStringVar(1, tostring(self:getGameStat(stat)))
  self:setStringVar(2, Game3.stripEos(story.action))
end

function Game3:storytellerInitializeRandomStat()
  local used = {}
  local man = self:ensureMauvilleMan()
  for i = 1, 4 do used[man.gameStatIDs and man.gameStatIDs[i] or 0] = true end
  local order = {}
  for i = 1, #Game3.STORYTELLER_STORIES do order[i] = i end
  for i = 1, #order do
    local a = self:rand(#order) or 1
    local b = self:rand(#order) or 1
    order[a], order[b] = order[b], order[a]
  end
  for i = 1, #order do
    local story = Game3.STORYTELLER_STORIES[order[i]]
    if not used[story.stat] and self:getGameStat(story.stat) >= story.min then
      self:storytellerRecord(self:storytellerFreeSlot(), story.stat)
      return 1
    end
  end
  return 0
end

function Game3:storytellerDisplayStory()
  local man = self:ensureMauvilleMan()
  local slot = (self.storytellerSel or 0) + 1
  local stat = man.gameStatIDs and man.gameStatIDs[slot] or 0
  local story = self:storyByStat(stat)
  self:setStringVar(1, tostring(man.statValues and man.statValues[slot] or 0))
  self:setStringVar(2, Game3.stripEos(story.action))
  self:setStringVar(3, man.trainerNames and man.trainerNames[slot] or "")
  local text = self:expandScriptText(Game3.stripEos(story.text))
  if self._scriptSays then
    self:sayScript(text)
  else
    self.field = { kind = "talk", text = text }
  end
end

function Game3:storytellerUpdateStat()
  local man = self:ensureMauvilleMan()
  local slot = self.storytellerSel or 0
  local i = slot + 1
  local stat = man.gameStatIDs and man.gameStatIDs[i] or 0
  if self:getGameStat(stat) > (man.statValues and man.statValues[i] or 0) then
    self:storytellerRecord(slot, stat)
    return 1
  end
  return 0
end

function Game3:openMauvilleMenu(labels, onPick)
  self:beginScriptWait()
  self.field = {
    kind = "mauville_menu",
    labels = labels,
    cursor = 0,
    onPick = onPick,
  }
end

function Game3:storytellerStoryListMenu()
  local man = self:ensureMauvilleMan()
  local labels = {}
  for i = 1, 4 do
    local stat = man.gameStatIDs and man.gameStatIDs[i] or 0
    if stat == 0 then break end
    labels[#labels + 1] = Game3.stripEos(self:storyByStat(stat).title)
  end
  labels[#labels + 1] = "CANCEL"
  self:openMauvilleMenu(labels, "pickStorytellerStory")
end

function Game3:pickStorytellerStory(index)
  local n = self:storytellerFreeSlot()
  if index >= n then
    self:setScriptVar(Gen3Script.VAR_RESULT, 0)
    return
  end
  self.storytellerSel = index
  self:setScriptVar(Gen3Script.VAR_RESULT, 1)
end

function Game3:getTraderTradedFlag()
  local man = self:ensureMauvilleMan()
  return (man.alreadyTraded or 0) ~= 0 and 1 or 0
end

function Game3:doesPlayerHaveNoDecorations()
  local bag = self.decorations
  if type(bag) ~= "table" then return 1 end
  for _, n in pairs(bag) do
    if (tonumber(n) or 0) > 0 then return 0 end
  end
  return 1
end

function Game3:isDecorationFull()
  return 0
end

-- decoration_inventory.c AddDecoration. RESULT TRUE/FALSE.
function Game3:addDecoration(id)
  id = tonumber(id) or 0
  if id < 1 then return false end
  if self:isDecorationFull() ~= 0 then return false end
  self.decorations = self.decorations or {}
  self.decorations[id] = (tonumber(self.decorations[id]) or 0) + 1
  return true
end

function Game3:decorationName(id)
  id = tonumber(id) or 0
  return Game3.DECOR_NAMES[id] or ("DECOR %d"):format(id)
end

function Game3:decorationPrice(id)
  id = tonumber(id) or 0
  return Game3.DECOR_PRICES[id] or 0
end

-- field_specials.c gUnknown_083F83C0. B is MULTI_B_PRESSED 0x7F, not CANCEL index 7.
function Game3:glassWorkshopLabels()
  return {
    self:itemName(Game3.ITEM_BLUE_FLUTE),
    self:itemName(Game3.ITEM_YELLOW_FLUTE),
    self:itemName(Game3.ITEM_RED_FLUTE),
    self:itemName(Game3.ITEM_WHITE_FLUTE),
    self:itemName(Game3.ITEM_BLACK_FLUTE),
    self:decorationName(Game3.DECOR_PRETTY_CHAIR),
    self:decorationName(Game3.DECOR_PRETTY_DESK),
    "CANCEL",
  }
end

function Game3:showGlassWorkshopMenu()
  self:openMauvilleMenu(self:glassWorkshopLabels(), "pickGlassWorkshop")
  if self.field then self.field.bPressed = Game3.MULTI_B_PRESSED end
end

function Game3:pickGlassWorkshop(index)
  index = tonumber(index) or Game3.MULTI_B_PRESSED
  self:setScriptVar(Gen3Script.VAR_RESULT, index)
end

-- pokemon_3.c GetMoveTutorMoves / sub_8040574. SPECIES2 egg → 0.
-- Level-up moves at or below current level that the mon does not know.
-- Cap MAX_MOVE_TUTOR_MOVES 20. Duplicates in the learnset are skipped.
function Game3:tutorLearnsetMoveId(entry)
  if type(entry) == "number" then return entry end
  if type(entry) ~= "table" then return 0 end
  local m = entry.move
  if type(m) == "number" then return m end
  if type(m) == "table" then return tonumber(m.id) or 0 end
  return tonumber(entry.id) or 0
end

function Game3:getMoveTutorMoves(mon)
  if not mon or mon.isEgg then return {} end
  local row = self:speciesRow(mon.species)
  local learn = row and row.learnset or {}
  local level = mon.level or 1
  local out = {}
  local cap = Game3.MAX_MOVE_TUTOR_MOVES
  for i = 1, #learn do
    if #out >= cap then break end
    local e = learn[i]
    if e and (e.level or 1) <= level then
      local id = self:tutorLearnsetMoveId(e)
      if id > 0 and not self:knowsMove(mon, id) then
        local seen = false
        for j = 1, #out do
          if out[j] == id then seen = true; break end
        end
        if not seen then out[#out + 1] = id end
      end
    end
  end
  return out
end

function Game3:selectMoveTutorMon()
  self:beginScriptWait()
  self.field = { kind = "move_tutor_mon", cursor = 0, scripted = true }
end

function Game3:pickMoveTutorMon(index)
  index = tonumber(index) or 0
  self.field = nil
  if index == Game3.PARTY_MENU_CANCEL then
    self:setScriptVar(0x8004, Game3.PARTY_MENU_CANCEL)
    self:setScriptVar(0x8005, 0)
    self:endScriptWait()
    return
  end
  local mon = self.party and self.party[index + 1]
  self:setScriptVar(0x8004, index)
  self:setScriptVar(0x8005, #(self:getMoveTutorMoves(mon)))
  self:endScriptWait()
end

function Game3:tutorMon()
  local idx = (self.scriptVars and self.scriptVars[0x8004]) or 0
  return self.party and self.party[idx + 1]
end

-- pokemon_1.c GiveMoveToMon. "ok" / "known" are both != 0xFFFF on hardware.
function Game3:giveMoveToMon(mon, moveId)
  if not mon then return "fail" end
  if self:knowsMove(mon, moveId) then return "known" end
  local moves = mon.moves or {}
  if #moves >= 4 then return "full" end
  moves[#moves + 1] = self:copyMove(moveId)
  mon.moves = moves
  return "ok"
end

function Game3:finishTutorTeach(ok)
  self.tutorWait = nil
  self._tutorMoves = nil
  self._tutorPick = nil
  self.learnMove = nil
  self:setScriptVar(0x8004, ok and 1 or 0)
  self.field = nil
  self:endScriptWait()
end

function Game3:displayMoveTutorMenu()
  if not self:scriptWaiting() then self:beginScriptWait() end
  local moves = self:getMoveTutorMoves(self:tutorMon())
  self._tutorMoves = moves
  local labels = {}
  for i = 1, #moves do
    labels[i] = self:learnMoveName(moves[i])
  end
  labels[#labels + 1] = "EXIT"
  self.field = { kind = "move_tutor_list", labels = labels, cursor = 0 }
end

function Game3:pickMoveTutorList(index)
  index = tonumber(index) or 0
  local moves = self._tutorMoves or {}
  if index < 0 or index >= #moves then
    self:openTutorGiveUp()
    return
  end
  self._tutorPick = index
  local name = self:learnMoveName(moves[index + 1])
  self.field = {
    kind = "tutor_confirm",
    text = ("Teach %s?"):format(name),
    cursor = 0,
  }
end

function Game3:openTutorGiveUp()
  self.field = {
    kind = "tutor_giveup",
    text = "Give up trying to teach a new move?",
    cursor = 0,
  }
end

function Game3:answerTutorGiveUp(yes)
  if yes then
    self:finishTutorTeach(false)
  else
    self:displayMoveTutorMenu()
  end
end

function Game3:answerTutorConfirm(yes)
  if not yes then
    self:displayMoveTutorMenu()
    return
  end
  local moves = self._tutorMoves or {}
  local id = moves[(self._tutorPick or 0) + 1]
  local mon = self:tutorMon()
  local status = self:giveMoveToMon(mon, id)
  if status == "ok" or status == "known" then
    self:finishTutorTeach(true)
    return
  end
  self.tutorWait = true
  self.learnMove = { mon = mon, move = id, name = self:learnMoveName(id) }
  self:openLearnForget()
end

-- Lilycove Move Deleter. SelectMove has no waitstate in the script;
-- the ROM pauses because CB2 swaps to the summary screen, so we must
-- beginScriptWait. B / 5th slot writes 0x8005 = 4. HMs are allowed.
function Game3:countPokemonMoves()
  local mon = self:selectedPartyMon()
  local n = #(mon and mon.moves or {})
  self:setScriptVar(Gen3Script.VAR_RESULT, n)
  return n
end

function Game3:getPokemonNicknameAndMoveName()
  local mon = self:selectedPartyMon()
  local slot = (self.scriptVars and self.scriptVars[0x8005]) or 0
  local move = mon and mon.moves and mon.moves[slot + 1]
  self:setStringVar(1, (mon and mon.name) or "")
  local name = ""
  if move then
    name = move.name or self:learnMoveName(move.id)
  end
  self:setStringVar(2, name or "")
end

function Game3:deleteMonMove()
  local mon = self:selectedPartyMon()
  if not (mon and type(mon.moves) == "table") then return end
  local slot = (self.scriptVars and self.scriptVars[0x8005]) or 0
  local i = slot + 1
  if i < 1 or i > #mon.moves then return end
  table.remove(mon.moves, i)
end

function Game3:selectMove()
  self:beginScriptWait()
  local mon = self:selectedPartyMon()
  local moves = mon and mon.moves or {}
  local labels = {}
  for i = 1, #moves do
    local m = moves[i]
    labels[i] = (m and m.name) or self:learnMoveName(m and m.id)
  end
  labels[#labels + 1] = "CANCEL"
  self.field = { kind = "move_deleter", labels = labels, cursor = 0 }
end

function Game3:pickMoveDeleter(index)
  index = tonumber(index) or 0
  local mon = self:selectedPartyMon()
  local n = #(mon and mon.moves or {})
  local slot = Game3.MOVE_DELETER_CANCEL
  if index >= 0 and index < n then slot = index end
  self:setScriptVar(0x8005, slot)
  self.field = nil
  self:endScriptWait()
end

function Game3:traderMenuGetDecoration()
  local man = self:ensureMauvilleMan()
  local labels = {}
  local ids = man.items or Game3.TRADER_DECORATIONS
  for i = 1, 4 do
    if (ids[i] or 0) ~= 0 then
      labels[#labels + 1] = self:decorationName(ids[i])
    end
  end
  labels[#labels + 1] = "CANCEL"
  self:openMauvilleMenu(labels, "pickTraderGet")
end

function Game3:pickTraderGet(index)
  local man = self:ensureMauvilleMan()
  local ids = man.items or {}
  local n = 0
  for i = 1, 4 do
    if (ids[i] or 0) ~= 0 then n = n + 1 end
  end
  if index >= n then
    self:setScriptVar(0x8004, 0)
    return
  end
  self:setScriptVar(0x8005, index)
  self:setScriptVar(0x8004, ids[index + 1] or 0)
  self:setStringVar(1, (man.names and man.names[index + 1]) or "")
end

function Game3:traderMenuGiveDecoration()
  local labels, ids = {}, {}
  local bag = self.decorations or {}
  for id, n in pairs(bag) do
    if (tonumber(n) or 0) > 0 then
      ids[#ids + 1] = tonumber(id)
      labels[#labels + 1] = self:decorationName(id)
    end
  end
  labels[#labels + 1] = "CANCEL"
  self._traderGiveIds = ids
  self:openMauvilleMenu(labels, "pickTraderGive")
end

function Game3:pickTraderGive(index)
  local ids = self._traderGiveIds or {}
  self._traderGiveIds = nil
  if index >= #ids then
    self:setScriptVar(0x8006, 0)
    return
  end
  local give = ids[index + 1]
  local get = self:varGet(0x8004)
  self:setScriptVar(0x8006, give)
  self:setStringVar(3, self:decorationName(get))
  self:setStringVar(2, self:decorationName(give))
end

function Game3:traderDoDecorationTrade()
  local man = self:ensureMauvilleMan()
  local getId = self:varGet(0x8004)
  local giveId = self:varGet(0x8006)
  local slot = (self:varGet(0x8005) or 0) + 1
  self.decorations = self.decorations or {}
  local have = tonumber(self.decorations[giveId]) or 0
  if have > 0 then self.decorations[giveId] = have - 1 end
  self.decorations[getId] = (tonumber(self.decorations[getId]) or 0) + 1
  man.names = man.names or {}
  man.items = man.items or {}
  man.names[slot] = self:playerName()
  man.items[slot] = giveId
  man.alreadyTraded = 1
end

function Game3:pickMauvilleMenu(index)
  local f = self.field
  local name = f and f.onPick
  self.field = nil
  if type(name) == "string" and self[name] then self[name](self, index, f) end
  if self.field then return end
  self:endScriptWait()
end

function Game3:berryGetTreeData()
  local tree = self:berryTreeInfo(self:scriptBerryTreeId())
  tree.sparkle = nil
  self:setScriptVar(0x8004, tree.stage or 0)
  self:setScriptVar(0x8005, tree.watered or 0)
  self:setScriptVar(0x8006, tree.yield or 0)
  if (tree.berry or 0) > 0 then
    self:setStringVar(1, self:berryName(tree.berry))
  end
end

function Game3:chooseBerryFromBag()
  -- item_menu.c ITEMMENULOCATION_BERRY / ChooseBerry: only the berry
  -- pocket, A writes VAR_ITEM_ID, B writes 0. waitstate holds until then.
  self.field = {
    kind = "bag",
    pocket = Game3.POCKET_BERRIES,
    cursor = 0,
    pickBerry = true,
  }
  -- S_BerryTree fades TO black before this special. The bag callback is
  -- FadeScreen(FADE_FROM_BLACK). A held TO_BLACK (alpha can still be 0 on
  -- the same tick as fadescreen) left a 240×160 black plate after plant.
  self:fadeInFromBlack()
  self:beginScriptWait()
end

function Game3:finishBerryPick(id)
  self:setScriptVar(Game3.VAR_ITEM_ID, tonumber(id) or 0)
  self.field = nil
  self:fadeInFromBlack()
  self:endScriptWait()
end

function Game3:pickBerryTree()
  local id = self:scriptBerryTreeId()
  local tree = self:berryTreeInfo(id)
  if (tree.stage or 0) ~= Game3.BERRY_STAGE_BERRIES or (tree.berry or 0) < 1 then
    self:setScriptVar(0x8004, 0)
    return
  end
  local n = tree.yield or Game3.berryMinYield(tree.berry)
  local ok = self:addItem(Game3.berryTypeToItem(tree.berry), n)
  self:setScriptVar(0x8004, ok and 1 or 0)
end

function Game3:removeBerryTree()
  self:plantBerryTree(self:scriptBerryTreeId(), 0, 0, false)
end

function Game3:waterBerryTree()
  local tree = self:berryTreeInfo(self:scriptBerryTreeId())
  local stage = tree.stage or 0
  if stage >= Game3.BERRY_STAGE_PLANTED and stage <= Game3.BERRY_STAGE_FLOWERING then
    tree.watered = math.min(4, (tree.watered or 0) + 1)
    return true
  end
  return false
end

function Game3:normalizeBerryTree(tree)
  if type(tree) ~= "table" or (tree.berry or 0) < 1 then return tree end
  if tree.minutes == nil and tree.sparkle == nil
      and (tree.stage or 0) == Game3.BERRY_STAGE_BERRIES then
    tree.sparkle = true
    tree.minutes = Game3.berryStageMinutes(tree.berry) * 4
  elseif tree.minutes == nil then
    tree.minutes = Game3.berryStageMinutes(tree.berry)
  end
  return tree
end

function Game3:growBerryTree(tree)
  if type(tree) ~= "table" or tree.sparkle then return false end
  local stage = tree.stage or 0
  if stage == Game3.BERRY_STAGE_NO_BERRY then return false end
  if stage == Game3.BERRY_STAGE_FLOWERING then
    tree.yield = self:calcBerryYield(tree)
  end
  if stage >= Game3.BERRY_STAGE_PLANTED
      and stage <= Game3.BERRY_STAGE_FLOWERING then
    tree.stage = stage + 1
    return true
  end
  if stage == Game3.BERRY_STAGE_BERRIES then
    tree.watered = 0
    tree.yield = 0
    tree.stage = Game3.BERRY_STAGE_SPROUTED
    tree.regrowth = (tree.regrowth or 0) + 1
    if tree.regrowth >= Game3.BERRY_REGROW_LIMIT then
      tree.berry = 0
      tree.stage = 0
      tree.minutes = 0
    end
    return true
  end
  return false
end

function Game3:advanceBerryTree(tree, minutesPassed)
  if type(tree) ~= "table" or (tree.berry or 0) < 1 then return end
  self:normalizeBerryTree(tree)
  if tree.sparkle or (tree.stage or 0) == 0 then return end
  minutesPassed = tonumber(minutesPassed) or 0
  if minutesPassed < 1 then return end
  local dur = Game3.berryStageMinutes(tree.berry)
  if minutesPassed >= dur * 71 then
    tree.berry = 0
    tree.stage = 0
    tree.yield = 0
    tree.watered = 0
    tree.minutes = 0
    return
  end
  local time = minutesPassed
  local left = tree.minutes or dur
  while time > 0 do
    if left > time then
      tree.minutes = left - time
      return
    end
    time = time - left
    left = dur
    if not self:growBerryTree(tree) then
      tree.minutes = left
      return
    end
    if (tree.berry or 0) < 1 then
      tree.minutes = 0
      return
    end
    if tree.stage == Game3.BERRY_STAGE_BERRIES then
      left = dur * 4
    end
  end
  tree.minutes = left
end

function Game3:tickBerryTrees(dt)
  if type(self.berryTrees) ~= "table" then return end
  -- Field dt is seconds. ROM BerryTreeTimeUpdate is minutes of RTC.
  local acc = (self.berryMinuteAcc or 0) + (dt or 0)
  local minutes = math.floor(acc / 60)
  self.berryMinuteAcc = acc - minutes * 60
  if minutes < 1 then return end
  for _, tree in pairs(self.berryTrees) do
    self:advanceBerryTree(tree, minutes)
  end
  self:refreshBerryTreeSprites()
end

function Game3:runBerrySpecial(id)
  if id == Game3.SPECIAL_GET_BERRY_TREE_DATA then
    self:berryGetTreeData()
  elseif id == Game3.SPECIAL_BERRY_BAG_MENU then
    self:chooseBerryFromBag()
  elseif id == Game3.SPECIAL_PLANT_BERRY_TREE then
    local item = self:varGet(Game3.VAR_ITEM_ID)
    self:plantBerryTree(
      self:scriptBerryTreeId(),
      Game3.itemToBerryType(item),
      Game3.BERRY_STAGE_PLANTED, true)
    if (tonumber(item) or 0) > 0 then self:takeItem(item, 1) end
    self:berryGetTreeData()
    self:refreshBerryTreeSprites()
  elseif id == Game3.SPECIAL_PICK_BERRY_TREE then
    self:pickBerryTree()
  elseif id == Game3.SPECIAL_REMOVE_BERRY_TREE then
    self:removeBerryTree()
    self:refreshBerryTreeSprites()
  elseif id == Game3.SPECIAL_WATER_BERRY_TREE then
    self:waterBerryTree()
  elseif id == Game3.SPECIAL_PLAYER_HAS_BERRIES then
    local has = #self:bagSlotsIn(Game3.POCKET_BERRIES) > 0
    local n = has and 1 or 0
    self:setScriptVar(Gen3Script.VAR_RESULT, n)
    return n
  end
end

function Game3:ballCount()
  local n = self:itemCount(Game3.ITEM_POKE_BALL)
  if n > 0 then return n end
  return self.balls or 0
end

function Game3:spendPokeBall()
  if self:takeItem(Game3.ITEM_POKE_BALL, 1) then return true end
  if (self.balls or 0) > 0 then
    self.balls = self.balls - 1
    return true
  end
  return false
end

function Game3:healAmount(id)
  return Game3.HEAL_AMOUNT[id]
end

function Game3:statusHeal(id)
  return Game3.STATUS_HEAL[id]
end

function Game3.isBlueYellowRedFlute(id)
  return id == Game3.ITEM_BLUE_FLUTE
      or id == Game3.ITEM_YELLOW_FLUTE
      or id == Game3.ITEM_RED_FLUTE
end

function Game3.isBall(id)
  id = tonumber(id) or 0
  return id >= Game3.ITEM_MASTER_BALL and id <= Game3.LAST_BALL
end

-- ItemUseOutOfBattle_Medicine and ItemUseInBattle_Medicine both open
-- the party (pokemon_menu.c ITEM_USE_SINGLE_MON / battle_party_menu.c).
function Game3.needsBattleParty(id)
  id = tonumber(id)
  if Game3.HEAL_AMOUNT[id] ~= nil
      or Game3.STATUS_HEAL[id] ~= nil
      or Game3.REVIVE_FRACTION[id] ~= nil then
    return true
  end
  return Game3.PP_HEAL[id] ~= nil
end

function Game3.needsFieldParty(id)
  id = tonumber(id)
  if Game3.needsBattleParty(id) then return true end
  if Game3.VITAMIN_STAT[id] or id == Game3.ITEM_RARE_CANDY then return true end
  if Game3.PP_HEAL[id] or Game3.PP_UP[id] then return true end
  if Game3.EVO_STONE[id] then return true end
  return false
end

function Game3.needsMovePick(id)
  id = tonumber(id)
  local pp = Game3.PP_HEAL[id]
  if pp and pp.one then return true end
  return Game3.PP_UP[id] ~= nil
end

-- pokemon_2.c CalculatePPWithBonus: base + floor(base * 20 * ppUps / 100).
function Game3:moveBasePp(move)
  if type(move) ~= "table" then return 0 end
  local spec = self.data and self.data.moves and self.data.moves.byId
    and self.data.moves.byId[move.id]
  return tonumber(spec and spec.pp) or tonumber(move.maxPp) or tonumber(move.pp) or 0
end

function Game3:moveMaxPp(move)
  local base = self:moveBasePp(move)
  local ups = math.min(3, math.max(0, tonumber(move and move.ppUps) or 0))
  return base + math.floor(base * 20 * ups / 100)
end

-- pokemon_3.c GetEvolutionTargetSpecies type 2/3: EVO_ITEM + matching param.
-- Everstone HOLD_EFFECT_PREVENT_EVOLVE blocks type 2 (use), not type 3 (scan).
function Game3:itemEvolutionTarget(mon, item, scan)
  if not mon or mon.isEgg then return nil end
  item = tonumber(item)
  if not item then return nil end
  if not scan then
    local hold = self:holdEffectOf(mon)
    if hold == Game3.HOLD_EFFECT_PREVENT_EVOLVE then return nil end
  end
  local list = self:evolutionsFor(mon.species)
  if type(list) ~= "table" then return nil end
  for i = 1, #list do
    local e = list[i]
    if e and e.method == Game3.EVO_ITEM and (e.param or 0) == item and e.target then
      return e.target
    end
  end
end

-- party_menu.c IsMedicineIneffective: HP vitamin on Shedinja.
function Game3:isMedicineIneffective(mon, id)
  local spec = Game3.VITAMIN_STAT[tonumber(id)]
  return spec ~= nil and spec.key == "hpEv"
      and mon and mon.species == Game3.SPECIES_SHEDINJA
end

function Game3.ballBonus(id)
  if id == Game3.ITEM_MASTER_BALL then return 255 end
  if id == Game3.ITEM_ULTRA_BALL then return 2 end
  if id == Game3.ITEM_GREAT_BALL then return 1.5 end
  if id == Game3.ITEM_SAFARI_BALL then return 1.5 end
  return Game3.POKE_BALL_BONUS
end

-- pokeruby atkEF_handleballthrow: multipliers are tenths (10 = 1x).
function Game3:catchBallBonus(id, mon)
  id = tonumber(id)
  if id == Game3.ITEM_NET_BALL then
    if Game3.hasType(mon, Game3.TYPE_WATER) or Game3.hasType(mon, Game3.TYPE_BUG) then
      return 3
    end
    return 1
  end
  if id == Game3.ITEM_DIVE_BALL then
    if (self.map and self.map.mapType) == Game3.MAP_TYPE_UNDERWATER then
      return 3.5
    end
    return 1
  end
  if id == Game3.ITEM_NEST_BALL then
    local level = (mon and mon.level) or 1
    if level <= 39 then
      local tenths = 40 - level
      if tenths < 10 then tenths = 10 end
      return tenths / 10
    end
    return 1
  end
  if id == Game3.ITEM_REPEAT_BALL then
    if mon and self:hasCaught(mon.species) then return 3 end
    return 1
  end
  if id == Game3.ITEM_TIMER_BALL then
    local tenths = ((self.battle and self.battle.turns) or 0) + 10
    if tenths > 40 then tenths = 40 end
    return tenths / 10
  end
  return Game3.ballBonus(id)
end

function Game3:itemTarget(id)
  local frac = Game3.REVIVE_FRACTION[id]
  local amount = self:healAmount(id)
  local clears = self:statusHeal(id)
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if not mon then
    elseif frac then
      if (mon.hp or 0) <= 0 then return mon end
    elseif (mon.hp or 0) > 0 then
      local hurt = amount and (mon.hp or 0) < (mon.maxHp or 0)
      local sick = false
      if clears == true then
        sick = mon.status ~= nil or (mon.confuseTurns or 0) > 0
      elseif clears == "confuse" then
        sick = (mon.confuseTurns or 0) > 0
      elseif clears == "love" then
        sick = mon.infatuatedBy ~= nil
      elseif clears and mon.status == clears then
        sick = true
      end
      if hurt or sick then return mon end
    end
  end
end

function Game3:useItemOnMon(mon, id, moveIndex)
  if not mon then
    return false, "It won't have any effect."
  end
  -- pokemon_menu.c sub_808B0C0: IS_EGG → SE_FAILURE, no effect.
  if mon.isEgg then
    return false, "It won't have any effect."
  end
  id = tonumber(id)
  -- Vitamins, Rare Candy, PP, and stones run before the fainted-HP
  -- guard (pokemon_item_effect.c case 3/4/5). Revive still needs HP 0.
  local vitamin = Game3.VITAMIN_STAT[id]
  if vitamin then
    if self:isMedicineIneffective(mon, id) then
      return false, "It won't have any effect."
    end
    local key = vitamin.key
    local cur = mon[key] or 0
    local total = self:monEvCount(mon)
    if cur >= Game3.VITAMIN_EV_CAP or total >= Game3.MAX_TOTAL_EVS then
      return false, "It won't have any effect."
    end
    local add = Game3.VITAMIN_EV
    if cur + add > Game3.VITAMIN_EV_CAP then
      add = Game3.VITAMIN_EV_CAP - cur
    end
    if total + add > Game3.MAX_TOTAL_EVS then
      add = Game3.MAX_TOTAL_EVS - total
    end
    if add < 1 then
      return false, "It won't have any effect."
    end
    if not self:takeItem(id, 1) then
      return false, "You have none left!"
    end
    mon[key] = cur + add
    self:recalcStats(mon)
    self:applyItemFriendship(mon, id)
    local name = mon.name or "POKeMON"
    return true, ("%s's %s was\nraised."):format(name, vitamin.name)
  end
  if id == Game3.ITEM_RARE_CANDY then
    if (mon.level or 1) >= Game3.MAX_LEVEL then
      return false, "It won't have any effect."
    end
    if not self:takeItem(id, 1) then
      return false, "You have none left!"
    end
    local before = {
      mon.maxHp or 0, mon.atk or 0, mon.def or 0,
      mon.spa or 0, mon.spd or 0, mon.spe or 0,
    }
    local growth = mon.growth or Game3.GROWTH_MEDIUM_SLOW
    mon.level = (mon.level or 1) + 1
    mon.exp = Game3.expAtLevel(growth, mon.level)
    self:recalcStats(mon)
    self:applyItemFriendship(mon, id)
    local after = {
      mon.maxHp or 0, mon.atk or 0, mon.def or 0,
      mon.spa or 0, mon.spd or 0, mon.spe or 0,
    }
    local labels = { "HP", "ATTACK", "DEFENSE", "SP. ATK", "SP. DEF", "SPEED" }
    local growths = {}
    for i = 1, 6 do
      growths[i] = {
        name = labels[i],
        delta = (after[i] or 0) - (before[i] or 0),
        value = after[i] or 0,
      }
    end
    self.candyGrowth = growths
    local learned = self:tryLearnLevelMoves(mon)
    self:tryEvolve(mon)
    local name = mon.name or "POKeMON"
    local texts = {
      ("%s was elevated to\nLv. %d."):format(name, mon.level),
    }
    for i = 1, #learned do texts[#texts + 1] = learned[i] end
    return true, table.concat(texts, " ")
  end
  if Game3.EVO_STONE[id] then
    local target = self:itemEvolutionTarget(mon, id)
    if not target then
      return false, "It won't have any effect."
    end
    if not self:takeItem(id, 1) then
      return false, "You have none left!"
    end
    self.pendingEvo = self.pendingEvo or {}
    self.pendingEvo[#self.pendingEvo + 1] = {
      mon = mon,
      from = mon.species,
      fromName = mon.name,
      target = target,
    }
    return true
  end
  if Game3.PP_UP[id] then
    if moveIndex == nil then
      return false, nil, "pick_move"
    end
    local move = (mon.moves or {})[tonumber(moveIndex) or 0]
    if not move then
      return false, "It won't have any effect."
    end
    local ups = tonumber(move.ppUps) or 0
    local maxNow = self:moveMaxPp(move)
    -- PP Up: ppUps < 3 and CalculatePPWithBonus > 4 (Sketch fails).
    -- PP Max: ppUps < 3 only.
    local to = Game3.PP_UP[id]
    if ups >= 3 or (to < 3 and maxNow <= 4) then
      return false, "It won't have any effect."
    end
    if not self:takeItem(id, 1) then
      return false, "You have none left!"
    end
    move.ppUps = to < 3 and (ups + 1) or 3
    local maxAfter = self:moveMaxPp(move)
    move.pp = (move.pp or 0) + (maxAfter - maxNow)
    move.maxPp = maxAfter
    self:applyItemFriendship(mon, id)
    return true, ("%s's PP increased."):format(move.name or "MOVE")
  end
  local ppHeal = Game3.PP_HEAL[id]
  if ppHeal then
    if ppHeal.one and moveIndex == nil then
      return false, nil, "pick_move"
    end
    local moves = mon.moves or {}
    local first = ppHeal.one and (tonumber(moveIndex) or 0) or 1
    local last = ppHeal.one and first or #moves
    local hit = false
    for i = first, last do
      local move = moves[i]
      if move then
        local maxPp = self:moveMaxPp(move)
        local cur = move.pp or 0
        if cur < maxPp then
          if not hit then
            if not self:takeItem(id, 1) then
              return false, "You have none left!"
            end
            hit = true
          end
          if (ppHeal.amount or 0) >= 127 then
            move.pp = maxPp
          else
            move.pp = math.min(maxPp, cur + (ppHeal.amount or 0))
          end
        end
      end
    end
    if not hit then
      return false, "It won't have any effect."
    end
    return true, "PP was restored."
  end
  local frac = Game3.REVIVE_FRACTION[id]
  if frac then
    if (mon.hp or 0) > 0 then
      return false, "It won't have any effect."
    end
    if not self:takeItem(id, 1) then
      return false, "You have none left!"
    end
    local maxHp = mon.maxHp or 1
    local hp = math.floor(maxHp * frac)
    if frac >= 1 then hp = maxHp end
    if hp < 1 then hp = 1 end
    mon.hp = hp
    self:applyItemFriendship(mon, id)
    return true, ("%s was revived!"):format(mon.name or "POKeMON")
  end
  if (mon.hp or 0) <= 0 then
    return false, "It won't have any effect."
  end
  local amount = self:healAmount(id)
  local clears = self:statusHeal(id)
  local willHeal = amount and (mon.hp or 0) < (mon.maxHp or 0)
  local willCure = false
  if clears == true then
    willCure = mon.status ~= nil or (mon.confuseTurns or 0) > 0
  elseif clears == "confuse" then
    willCure = (mon.confuseTurns or 0) > 0
  elseif clears == "love" then
    willCure = mon.infatuatedBy ~= nil
  elseif clears and mon.status == clears then
    willCure = true
  end
  if not willHeal and not willCure then
    return false, "It won't have any effect."
  end
  if Game3.isBlueYellowRedFlute(id) then
    if self:itemCount(id) < 1 then
      return false, "You have none left!"
    end
  elseif not self:takeItem(id, 1) then
    return false, "You have none left!"
  end
  local texts = {}
  if willHeal then
    local heal = amount >= 999 and (mon.maxHp or amount) or amount
    mon.hp = math.min(mon.maxHp or heal, (mon.hp or 0) + heal)
    texts[#texts + 1] = ("%s recovered HP!"):format(mon.name or "POKeMON")
  end
  if willCure then
    local name = mon.name or "POKeMON"
    if clears == "confuse" then
      mon.confuseTurns = nil
      texts[#texts + 1] = ("%s snapped out of its confusion."):format(name)
    elseif clears == "love" then
      mon.infatuatedBy = nil
      texts[#texts + 1] = ("%s got over its infatuation."):format(name)
    else
      mon.status = nil
      mon.sleepTurns = nil
      if clears == true then mon.confuseTurns = nil end
      if id == Game3.ITEM_BLUE_FLUTE then
        texts[#texts + 1] = ("%s woke up."):format(name)
      else
        texts[#texts + 1] = ("%s's status returned to normal!"):format(name)
      end
    end
  end
  self:applyItemFriendship(mon, id)
  return true, table.concat(texts, " ")
end

function Game3:dadsAdvice()
  -- gOtherText_DadsAdvice. \l is a third line in FONT3.
  return ("DAD's advice...\n%s, there's a time and place for\neverything!"):format(
    self:playerName())
end

function Game3:useFieldItem(id)
  id = tonumber(id)
  if Game3.isBall(id) then
    return false, "Use this in battle."
  end
  -- item_menu.c: type 1 (medicine / candy / PP / stone) with no party.
  if Game3.needsFieldParty(id) and #(self.party or {}) < 1 then
    return false, "There is no\nPOKéMON."
  end
  if Game3.isTmHm(id) then
    return self:bootTmHm(id)
  end
  if Game3.rodKind(id) ~= nil then
    return self:useRod(id)
  end
  if id == Game3.ITEM_MACH_BIKE or id == Game3.ITEM_ACRO_BIKE then
    return self:useBike(id)
  end
  if id == Game3.ITEM_WAILMER_PAIL then
    return self:useWailmerPail()
  end
  if id == Game3.ITEM_ITEMFINDER then
    return self:useItemfinder()
  end
  if Game3.REPEL_STEPS[id] then
    return self:useRepel(id)
  end
  if id == Game3.ITEM_WHITE_FLUTE or id == Game3.ITEM_BLACK_FLUTE then
    return self:useBlackWhiteFlute(id)
  end
  if id == Game3.ITEM_ESCAPE_ROPE then
    return self:useEscapeRope()
  end
  if id == Game3.ITEM_COIN_CASE then
    return true, ("Your COINS:\n%d"):format(self:getCoins())
  end
  if id == Game3.ITEM_POKEBLOCK_CASE then
    return self:openPokeblockCase()
  end
  if Game3.isMailItem(id) then
    return self:readBagMail(id)
  end
  if id == Game3.ITEM_SACRED_ASH then
    local fromBag = self.field and self.field.kind == "bag"
    local _, msg = self:useSacredAsh()
    self.field = {
      kind = "talk",
      text = msg or "It won't have any effect.",
      thenBag = fromBag or nil,
    }
    return true
  end
  -- item_menu.c BAG_POCKET_BERRIES: plant if facing empty soil, else
  -- the berry's own fieldUseFunc (medicine / CannotUse).
  if self:itemPocket(id) == Game3.POCKET_BERRIES then
    local planted, plantMsg = self:plantBerryFromBag(id)
    if planted then
      local fromBag = self.field and self.field.kind == "bag"
      self.field = {
        kind = "talk",
        text = plantMsg,
        thenBag = fromBag or nil,
      }
      return true
    end
  end
  -- ItemUseOutOfBattle_Medicine / RareCandy / PPRecovery / PPUp /
  -- EvolutionStone: fade to the party, then the matching callback.
  if Game3.needsFieldParty(id) then
    return self:openPartyUse(id)
  end
  return false, self:dadsAdvice()
end

-- ItemUseOutOfBattle_SacredAsh: ITEM_USE_ALL_MONS, revive every fainted
-- mon to full HP, consume once if any hit. No friendship bytes.
function Game3:useSacredAsh()
  local id = Game3.ITEM_SACRED_ASH
  if self:itemCount(id) < 1 then
    return false, "You have none left!"
  end
  local party = self.party or {}
  local hit = 0
  local lastName
  for i = 1, #party do
    local mon = party[i]
    if mon and not mon.isEgg and (mon.hp or 0) <= 0 then
      mon.hp = mon.maxHp or 1
      hit = hit + 1
      lastName = mon.name or "POKeMON"
    end
  end
  if hit < 1 then
    return false, "It won't have any effect."
  end
  self:takeItem(id, 1)
  if hit == 1 then
    return true, ("%s was revived!"):format(lastName)
  end
  return true, "The fainted POKeMON were revived!"
end

function Game3:facingUnplantedSoil()
  local npc = self:facingNpc()
  if not npc or not Game3.isBerryTreeGfx(npc.graphicsId) then return nil end
  local tree = self:berryTreeInfo(npc.trainerRange)
  if (tree.stage or 0) ~= Game3.BERRY_STAGE_NO_BERRY then return nil end
  return npc
end

-- ItemUseOutOfBattle_Berry then S_PlantBerryTreeFromBag.
function Game3:plantBerryFromBag(id)
  local npc = self:facingUnplantedSoil()
  if not npc then return false end
  local berry = Game3.itemToBerryType(id)
  if berry < 1 then return false end
  if not self:takeItem(id, 1) then
    return false, "You have none left!"
  end
  self._scriptNpc = npc
  self:plantBerryTree(npc.trainerRange, berry, Game3.BERRY_STAGE_PLANTED, true)
  self:incrementGameStat(Game3.GAME_STAT_PLANTED_BERRIES)
  self:refreshBerryTreeSprites()
  local name = self:berryName(berry)
  return true, ("%s planted one %s BERRY in\nthe soft, loamy soil."):format(
    self:playerName(), name)
end

function Game3:bootTmHm(item)
  local moveId = self:tmhmMove(item)
  local slot = self:copyMove(moveId)
  local name = (slot and slot.name) or "MOVE"
  local boot = item >= Game3.ITEM_HM_CUT and "Booted up an HM." or "Booted up a TM."
  local from = (self.field and self.field.kind == "bag") and "bag" or "field"
  self.field = {
    kind = "talk",
    text = boot,
    queue = {
      boot,
      ("It contained\n%s.\nTeach %s\nto a POKéMON?"):format(name, name),
    },
    qi = 1,
    thenTmAsk = true,
    tmItem = item,
    from = from,
    thenBag = from == "bag" or nil,
  }
  return true
end

function Game3:openTmYesNo()
  local f = self.field
  self.field = {
    kind = "tm_yesno",
    text = (f and f.text) or "Teach the move to a POKéMON?",
    cursor = 0,
    tmItem = f and f.tmItem,
    from = f and f.from,
    thenBag = f and f.thenBag,
  }
  return true
end

function Game3:answerTmYesNo(yes)
  local f = self.field
  local item = f and f.tmItem
  local from = f and f.from
  if yes and item then
    return self:openPartyTeach(item, from)
  end
  if from == "bag" then
    return self:openBag()
  end
  self:closeField()
  return true
end

function Game3:readBagMail(id)
  local fromBag = self.field and self.field.kind == "bag"
  self.field = {
    kind = "mail_read",
    item = id,
    thenBag = fromBag or nil,
  }
  return true
end

function Game3:openPokeblockCase()
  local blocks = self:ensurePokeblocks()
  local labels = {}
  for i = 1, Game3.POKEBLOCK_MAX do
    local b = blocks[i]
    if b and (b.color or 0) ~= 0 then
      labels[#labels + 1] = self:pokeblockName(b)
    end
  end
  if #labels < 1 then labels[1] = "The CASE is empty." end
  labels[#labels + 1] = "CANCEL"
  local fromBag = self.field and self.field.kind == "bag"
  self.field = {
    kind = "pokeblock_case",
    labels = labels,
    cursor = 0,
    thenBag = fromBag or nil,
  }
  return true
end

function Game3:battleBagList(pocket)
  pocket = tonumber(pocket)
  if not pocket then
    local b = self.battle
    pocket = (b and b.bagPocket) or self.lastBagPocket or self:firstFilledPocket()
  end
  return self:bagSlotsIn(pocket)
end

function Game3:spendBall(id)
  id = id or Game3.ITEM_POKE_BALL
  if id == Game3.ITEM_SAFARI_BALL then
    local n = self.safariBalls or 0
    if n < 1 then return false end
    self.safariBalls = n - 1
    return true
  end
  if id == Game3.ITEM_POKE_BALL then return self:spendPokeBall() end
  return self:takeItem(id, 1)
end

function Game3:buyMartItem(id, kind, qty)
  qty = math.floor(tonumber(qty) or 1)
  if qty < 1 then qty = 1 end
  if not id then return false, "There's nothing to buy." end
  if kind == "decor" then
    local price = self:decorationPrice(id) * qty
    if (self.money or 0) < price then
      return false, "You don't have enough money."
    end
    for _ = 1, qty do
      if not self:addDecoration(id) then
        return false, "No more room!"
      end
    end
    self.money = (self.money or 0) - price
    self:playSe(Game3.SE_SHOP)
    return true, ("Got %s!"):format(self:decorationName(id))
  end
  local unit = self:itemPrice(id)
  local price = unit * qty
  if (self.money or 0) < price then
    return false, "You don't have enough money."
  end
  self.money = (self.money or 0) - price
  self:addItem(id, qty)
  self:playSe(Game3.SE_SHOP)
  if qty > 1 then
    return true, ("Got %s x%d!"):format(self:itemName(id), qty)
  end
  return true, ("Got %s!"):format(self:itemName(id))
end

function Game3:canSellItem(id)
  id = tonumber(id) or 0
  if id < 1 then return false end
  local pocket = self:itemPocket(id)
  if pocket == Game3.POCKET_KEY or pocket == Game3.POCKET_TMHM then
    return false
  end
  return (self:itemPrice(id) or 0) > 0
end

function Game3:martSellSlots()
  local bag = self.bag or {}
  local list = {}
  for i = 1, #bag do
    local slot = bag[i]
    if slot and self:canSellItem(slot.id) then
      list[#list + 1] = slot
    end
  end
  return list
end

function Game3:sellMartItem(id, qty)
  qty = math.floor(tonumber(qty) or 1)
  if qty < 1 then qty = 1 end
  if not self:canSellItem(id) then
    return false, "I can't buy that."
  end
  local unit = math.floor((self:itemPrice(id) or 0) / 2)
  if not self:takeItem(id, qty) then
    return false, "You don't have that."
  end
  local got = unit * qty
  self.money = (self.money or 0) + got
  self:playSe(Game3.SE_SHOP)
  return true, ("Received $%d."):format(got)
end

function Game3:pickupItem(npc)
  local id = npc and npc.itemId
  if not id or id < 1 then return false end
  local n = npc.itemCount or 1
  self:addItem(id, n)
  self:playObtainFanfare(id)
  if npc.flagId and npc.flagId ~= 0 then
    self.flags = self.flags or {}
    self.flags[npc.flagId] = true
  end
  npc.hidden = true
  npc.defeated = true
  local name = self:itemName(id)
  if n > 1 then
    self.field = { kind = "talk", text = ("Found %s x%d!"):format(name, n) }
  else
    self.field = { kind = "talk", text = ("Found %s!"):format(name) }
  end
  return true
end

function Game3.isStarterSpecies(id)
  return id == Game3.SPECIES_TREECKO
    or id == Game3.SPECIES_TORCHIC
    or id == Game3.SPECIES_MUDKIP
end

function Game3:hasStarter()
  if self.flags and self.flags[Game3.FLAG_SYS_POKEMON_GET] then return true end
  return #(self.party or {}) > 0
end

function Game3:isFemale()
  return (self.gender or 0) == Game3.GENDER_FEMALE
end

function Game3:playerName()
  if type(self.customName) == "string" and self.customName ~= "" then
    return self.customName
  end
  return self:isFemale() and "MAY" or "BRENDAN"
end

function Game3:rivalName()
  return self:isFemale() and "BRENDAN" or "MAY"
end

function Game3:rivalGraphicsId()
  return self:isFemale() and Game3.GFX_RIVAL_BRENDAN or Game3.GFX_RIVAL_MAY
end

function Game3:playerGraphicsId()
  local female = self:isFemale()
  if self.diving or self:isUnderwater() then
    return female and Game3.GFX_MAY_UNDERWATER or Game3.GFX_BRENDAN_UNDERWATER
  end
  if self.surfing then
    return female and Game3.GFX_MAY_SURFING or Game3.GFX_BRENDAN_SURFING
  end
  if self.bike == "acro" then
    return female and Game3.GFX_MAY_ACRO_BIKE or Game3.GFX_BRENDAN_ACRO_BIKE
  end
  if self.bike == "mach" then
    return female and Game3.GFX_MAY_MACH_BIKE or Game3.GFX_BRENDAN_MACH_BIKE
  end
  if self.wateringLeft then
    if female then
      local byId = self.data and self.data.sprites and self.data.sprites.byId
      if byId and byId[Game3.GFX_MAY_WATERING] then
        return Game3.GFX_MAY_WATERING
      end
    end
    return Game3.GFX_BRENDAN_WATERING
  end
  if female then
    local byId = self.data and self.data.sprites and self.data.sprites.byId
    if byId and byId[Game3.GFX_MAY] then return Game3.GFX_MAY end
    return Game3.GFX_RIVAL_MAY
  end
  return Game3.GFX_BRENDAN
end

function Game3:resolveGraphicsId(gid)
  gid = gid or 0
  if gid >= Game3.GFX_VAR_0 and gid <= Game3.GFX_VAR_F then
    local resolved = self:varGet(Game3.VAR_OBJ_GFX_ID_0 + (gid - Game3.GFX_VAR_0))
    if resolved ~= 0 then return resolved end
    if gid == Game3.GFX_VAR_0 then return self:rivalGraphicsId() end
  end
  return gid
end

function Game3.isRivalGfx(gid)
  return gid == Game3.GFX_RIVAL_BRENDAN or gid == Game3.GFX_RIVAL_MAY
    or gid == Game3.GFX_VAR_0
end

function Game3.starterIndex(species)
  species = tonumber(species)
  for i = 1, #Game3.STARTERS do
    if Game3.STARTERS[i] == species then return i - 1 end
  end
end

function Game3.starterSpecies(index)
  index = math.floor(tonumber(index) or 0)
  if index < 0 or index > 2 then index = 0 end
  return Game3.STARTERS[index + 1]
end

-- pokeruby IsStarterInParty: SPECIES2 (eggs are SPECIES_EGG) equals
-- GetStarterPokemon(VAR_STARTER_MON).
function Game3:isStarterInParty()
  local want = Game3.starterSpecies(self:varGet(Game3.VAR_STARTER_MON))
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and not mon.isEgg and mon.species == want then return true end
  end
  return false
end

function Game3.rivalStarterSpecies(species)
  local i = Game3.starterIndex(species)
  if not i then return Game3.SPECIES_TORCHIC end
  return Game3.STARTERS[(i + 1) % 3 + 1]
end

function Game3:resetMapFlagList()
  local cached = self.data and self.data.constants and self.data.constants.resetMapFlags
  if type(cached) == "table" and #cached > 0 then return cached end
  return Game3.NEW_GAME_HIDE_FLAGS
end

function Game3:applyNewGameHideFlags()
  self.flags = self.flags or {}
  local list = self:resetMapFlagList()
  for i = 1, #list do
    self.flags[list[i]] = true
  end
  return true
end

function Game3:applyGender(gender)
  self.gender = gender == Game3.GENDER_FEMALE
    and Game3.GENDER_FEMALE or Game3.GENDER_MALE
  self.flags = self.flags or {}
  local male = {
    Game3.FLAG_HIDE_MAY_MOM_DOWNSTAIRS,
    Game3.FLAG_HIDE_MOVING_TRUCK_MAY,
    Game3.FLAG_HIDE_BRENDAN_MOM,
    Game3.FLAG_HIDE_BRENDAN_UPSTAIRS,
  }
  local female = {
    Game3.FLAG_HIDE_BRENDAN_MOM_DOWNSTAIRS,
    Game3.FLAG_HIDE_MOVING_TRUCK_BRENDAN,
    Game3.FLAG_HIDE_MAY_MOM,
    Game3.FLAG_HIDE_MAY_UPSTAIRS,
  }
  for i = 1, #male do self.flags[male[i]] = nil end
  for i = 1, #female do self.flags[female[i]] = nil end
  local set = self:isFemale() and female or male
  for i = 1, #set do self.flags[set[i]] = true end
end

function Game3:openGenderMenu()
  self.field = { kind = "gender", cursor = 0 }
  return true
end

function Game3:chooseGender(gender)
  self:applyGender(gender)
  if self.map then
    self:runMapScript("onTransition")
    self:resetNpcs(self.map)
    self:tryMapFrameScript()
  end
  self.field = nil
  return true
end

function Game3:isRivalNpc(npc)
  if not npc then return false end
  return Game3.isRivalGfx(self:resolveGraphicsId(npc.graphicsId))
end

function Game3:isLabRival(npc)
  return npc and (npc.flagId or 0) == Game3.FLAG_HIDE_RIVAL_BIRCH_LAB
end

function Game3:isRoute103Rival(npc)
  return npc and (npc.flagId or 0) == Game3.FLAG_HIDE_RIVAL_ROUTE103
end

function Game3:hasDefeatedRoute103Rival()
  return self.flags and self.flags[Game3.FLAG_DEFEATED_RIVAL_ROUTE103] == true
end

function Game3:playerStarterSpecies()
  local party = self.party or {}
  for i = 1, #party do
    local s = party[i] and party[i].species
    if Game3.isStarterSpecies(s) then return s end
  end
end

function Game3:rivalTrainerId()
  local idx = Game3.starterIndex(self:playerStarterSpecies()) or 1
  if self:isFemale() then
    local ids = {
      [0] = Game3.TRAINER_BRENDAN_4,
      [1] = Game3.TRAINER_BRENDAN_7,
      [2] = Game3.TRAINER_BRENDAN_1,
    }
    return ids[idx]
  end
  local ids = {
    [0] = Game3.TRAINER_MAY_4,
    [1] = Game3.TRAINER_MAY_7,
    [2] = Game3.TRAINER_MAY_1,
  }
  return ids[idx]
end

function Game3:rivalParty()
  local id = self:rivalTrainerId()
  local pack = self.data and self.data.trainers
  local tr = pack and pack.byId and pack.byId[id]
  if tr and type(tr.party) == "table" and #tr.party > 0 then
    return tr.party, tr
  end
  local species = self.rivalSpecies
    or Game3.rivalStarterSpecies(self:playerStarterSpecies())
  return { { level = Game3.STARTER_LEVEL, species = species } }, nil
end

function Game3:startRivalBattle(npc)
  if not self:hasStarter() then
    self.field = {
      kind = "talk",
      text = ("%s: You don't have a POKeMON yet!"):format(self:rivalName()),
    }
    return true
  end
  if self:hasDefeatedRoute103Rival() then
    self.field = {
      kind = "talk",
      text = ("%s: Where should I go next?"):format(self:rivalName()),
    }
    return true
  end
  local party, tr = self:rivalParty()
  npc = npc or {}
  npc.party = party
  npc.trainerName = (tr and tr.name) or self:rivalName()
  npc.trainerClass = "RIVAL"
  npc.flagId = npc.flagId or Game3.FLAG_HIDE_RIVAL_ROUTE103
  if not self:startTrainerBattle(npc) then return false end
  self.battle.rivalRoute103 = true
  self.battle.text = ("%s would like to battle!"):format(self:rivalName())
  return true
end

function Game3:finishRoute103Rival(npc)
  self.flags = self.flags or {}
  self.scriptVars = self.scriptVars or {}
  self.flags[Game3.FLAG_HIDE_RIVAL_ROUTE103] = true
  self.flags[Game3.FLAG_DEFEATED_RIVAL_ROUTE103] = true
  self.flags[Game3.FLAG_HIDE_RIVAL_BIRCH_LAB] = nil
  self.flags[Game3.FLAG_HIDE_RIVAL_OLDALE_TOWN] = nil
  self.scriptVars[Game3.VAR_BIRCH_LAB_STATE] = 4
  self.scriptVars[Game3.VAR_ROUTE103_STATE] = 1
  self.scriptVars[Game3.VAR_OLDALE_STATE] = 1
  if npc then npc.hidden = true; npc.defeated = true end
  if self.battle then
    self.battle.afterText = ("%s: Let's go back to PROF. BIRCH's lab!"):format(
      self:rivalName())
  end
end

function Game3:talkRival(npc)
  if not self:isRivalNpc(npc) then return false end
  if self:isRoute103Rival(npc) then
    return self:startRivalBattle(npc)
  end
  if not self:isLabRival(npc) then return false end
  local species = self.rivalSpecies
  if not species then
    local lead = self.party and self.party[1]
    species = Game3.rivalStarterSpecies(lead and lead.species)
    self.rivalSpecies = species
  end
  local name = self:rivalName()
  if not self.rivalTookStarter then
    self.rivalTookStarter = true
    self:addItem(Game3.ITEM_POKE_BALL, 5)
    self.field = {
      kind = "talk",
      text = ("%s: I'll take this %s!"):format(name, self:speciesName(species)),
    }
    return true
  end
  self.field = {
    kind = "talk",
    text = ("%s: Where should I go next?"):format(name),
  }
  return true
end

function Game3:isStarterGiver(npc)
  if not npc then return false end
  local gid = npc.graphicsId or 0
  return gid == Game3.GFX_BIRCHS_BAG or gid == Game3.GFX_BIRCH
end

function Game3:giveMon(species, level, item)
  species = tonumber(species)
  if not species or species < 1 then return false end
  local mon = self:makeMon(species, level or Game3.STARTER_LEVEL)
  local held = tonumber(item) or 0
  if held ~= 0 then mon.item = held end
  if not self:addToParty(mon) then
    if Game3.isStarterSpecies(species) then return false end
    if not self:sendToPc(mon) then return false end
    return true, mon
  end
  if Game3.isStarterSpecies(species) then
    self.flags = self.flags or {}
    self.flags[Game3.FLAG_SYS_POKEMON_GET] = true
    self.flags[Game3.FLAG_RESCUED_BIRCH] = true
    self.flags[Game3.FLAG_HIDE_BIRCH_STARTERS_BAG] = true
    self.rivalSpecies = Game3.rivalStarterSpecies(species)
    self.scriptVars = self.scriptVars or {}
    self.scriptVars[Game3.VAR_STARTER_MON] = Game3.starterIndex(species)
  end
  return true, mon
end

function Game3:giveStarter(species, npc)
  if self:hasStarter() then return false, "You already have a POKeMON." end
  local ok, mon = self:giveMon(species, Game3.STARTER_LEVEL)
  if not ok then return false, "The party is full." end
  if npc and (npc.graphicsId or 0) == Game3.GFX_BIRCHS_BAG then
    npc.hidden = true
    self.pendingChase = true
    self.scriptVars = self.scriptVars or {}
    self.scriptVars[Game3.VAR_BIRCH_LAB_STATE] = 2
    self.scriptVars[Game3.VAR_ROUTE101_STATE] = 3
  else
    self:revealBirchLab()
  end
  return true, ("Got %s!"):format((mon and mon.name) or self:speciesName(species))
end

function Game3:openStarterMenu(npc)
  self.field = {
    kind = "starter",
    cursor = 1,
    npc = npc,
  }
  return true
end

function Game3:openMartList(list, kind)
  if type(list) ~= "table" or #list < 1 then
    list = { Game3.ITEM_POKE_BALL }
    kind = nil
  end
  self.field = {
    kind = "mart",
    martKind = kind,
    items = list,
    cursor = 0,
    mode = "root",
    note = ("$%d"):format(self.money or 0),
  }
  self:hideMoneyBox()
  return true
end

function Game3:openMart(npc)
  return self:openMartList(npc and npc.mart)
end

function Game3.trainerPay(b)
  if not b then return 0 end
  local n = #(b.trainerParty or {})
  if n < 1 then n = 1 end
  local level = (b.enemy and b.enemy.level) or 5
  return 16 * level * n
end

function Game3:markHealPoint()
  if not (self.map and self.map.id) then return false end
  self.lastHeal = {
    mapId = self.map.id,
    x = self.playerX or 0,
    y = self.playerY or 0,
  }
  return true
end

function Game3:startMap()
  local pack = (self.data or {}).maps or {}
  return pack.maps and pack.maps[pack.start]
end

function Game3:warpToHeal()
  self:repairStaleBedroomHeal()
  local dest, x, y
  local heal = self.lastHeal
  if heal and heal.mapId then
    dest = self:lookupMapById(heal.mapId)
    x, y = heal.x or 0, heal.y or 0
    -- Heal locations are towns / cities / the bedroom. special 0 on
    -- Route 101 used to stamp the starter bag tile as lastHeal.
    if dest and dest.mapType == Game3.MAP_TYPE_ROUTE then
      dest = nil
    end
  end
  -- Early-game blackout (no Center yet, or bedroom lookup failed at
  -- setrespawn) must land in the player's room, not the start map
  -- (truck / Route 101).
  if not dest then
    dest = self:playerBedroomMap()
    if dest then
      x, y = Game3.HEAL_BEDROOM_X, Game3.HEAL_BEDROOM_Y
      if not Game3.walkable(dest, x, y) then
        local spawn = dest.spawn or {}
        x, y = spawn.x or x, spawn.y or y
      end
    end
  end
  if not dest then
    dest = self:startMap()
    if dest and Game3.isTruckMap(dest) then
      dest = self:littlerootTownMap() or dest
    end
    local spawn = dest and dest.spawn or {}
    x, y = spawn.x or 0, spawn.y or 0
  end
  if not dest then return false end
  self.surfing = nil
  self.climbing = nil
  self.diving = nil
  self.bike = nil
  self:enterMap(dest, x or 0, y or 0, false)
  return true
end

-- post_battle_event_funcs.c GameClear. Credits / HoF cinema is skipped:
-- heal, FLAG_SYS_GAME_CLEAR, first HoF time, Champion ribbons, record
-- the party (Task_Hof_InitTeamSaveData), bedroom heal, warp home. Do
-- not beginScriptWait; waitstate is already a no-op.
function Game3:hofPlayTimeStat()
  local sec = math.floor(tonumber(self.playSeconds) or 0)
  if sec < 0 then sec = 0 end
  local h = math.floor(sec / 3600)
  local m = math.floor((sec % 3600) / 60)
  local s = sec % 60
  return h * 65536 + m * 256 + s
end

function Game3:gameClear()
  self:healParty()
  self.flags = self.flags or {}
  if self.flags[Game3.FLAG_SYS_GAME_CLEAR] then
    self.hasHallOfFameRecords = true
  else
    self.hasHallOfFameRecords = false
    self.flags[Game3.FLAG_SYS_GAME_CLEAR] = true
  end
  if self:getGameStat(Game3.GAME_STAT_FIRST_HOF_PLAY_TIME) == 0 then
    self.gameStats = self.gameStats or {}
    self.gameStats[Game3.GAME_STAT_FIRST_HOF_PLAY_TIME] = self:hofPlayTimeStat()
  end
  self:setBedroomHeal()
  local ribbonGet = false
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and (mon.species or 0) ~= 0
        and not mon.isEgg and not mon.championRibbon then
      mon.championRibbon = true
      ribbonGet = true
    end
  end
  if ribbonGet then
    self:incrementGameStat(Game3.GAME_STAT_RECEIVED_RIBBONS)
    self.flags[Game3.FLAG_SYS_RIBBON_GET] = true
  end
  self:recordHallOfFameTeam()
  self:writeSave()
  return self:warpToHeal()
end

-- pokeruby sub_8053678: Dig / Escape Rope land on warp4.
function Game3:warpToEscape()
  local w = self.escapeWarp
  local dest
  if w then
    dest = self:lookupMapById(w.mapId)
    if not dest then dest = self:lookupMap(w.mapGroup, w.mapNum) end
  end
  if not dest then return self:warpToHeal() end
  self.surfing = nil
  self.climbing = nil
  self.diving = nil
  self.bike = nil
  self:enterMap(dest, w.x or 0, w.y or 0, true)
  return true
end

function Game3:resetEliteFour()
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_DEFEATED_ELITE_4_SIDNEY] = nil
  self.flags[Game3.FLAG_DEFEATED_ELITE_4_PHOEBE] = nil
  self.flags[Game3.FLAG_DEFEATED_ELITE_4_GLACIA] = nil
  self.flags[Game3.FLAG_DEFEATED_ELITE_4_DRAKE] = nil
  self:setScriptVar(Game3.VAR_ELITE_4_STATE, 0)
end

function Game3:tryReadyRivalForGoGoggles()
  if self.flags and self.flags[Game3.FLAG_RECEIVED_GO_GOGGLES] then return end
  if not (self.flags and self.flags[Game3.FLAG_DEFEATED_LAVARIDGE_GYM]) then
    return
  end
  self.flags[Game3.FLAG_HIDE_RIVAL_LAVARIDGE_1] = nil
  self:setScriptVar(Game3.VAR_LAVARIDGE_RIVAL_STATE, 2)
end

function Game3:setHideFlag(flag, hidden)
  self.flags = self.flags or {}
  if hidden then
    self.flags[flag] = true
  else
    self.flags[flag] = nil
  end
end

function Game3:moveMrBrineyToHouse()
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_DEWFORD_TOWN, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_DEWFORD, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE109, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_ROUTE109, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_ROUTE104, false)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE104_HOUSE, false)
  self:setHideFlag(Game3.FLAG_HIDE_PEEKO_BRINEY_HOUSE, false)
end

function Game3:moveMrBrineyToDewford()
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE109, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_ROUTE109, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE104, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_ROUTE104, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE104_HOUSE, true)
  self:setHideFlag(Game3.FLAG_HIDE_PEEKO_BRINEY_HOUSE, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_DEWFORD_TOWN, false)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_DEWFORD, false)
end

function Game3:moveMrBrineyToRoute109()
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE104, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_ROUTE104, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE104_HOUSE, true)
  self:setHideFlag(Game3.FLAG_HIDE_PEEKO_BRINEY_HOUSE, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_DEWFORD_TOWN, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_DEWFORD, true)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_ROUTE109, false)
  self:setHideFlag(Game3.FLAG_HIDE_MR_BRINEY_BOAT_ROUTE109, false)
end

function Game3:resetMrBriney()
  local loc = self:varGet(Game3.VAR_BRINEY_LOCATION)
  if loc == 1 then
    self:moveMrBrineyToHouse()
  elseif loc == 2 then
    self:moveMrBrineyToDewford()
  elseif loc == 3 then
    self:moveMrBrineyToRoute109()
  end
end

function Game3:runWhiteOutScript()
  self:resetEliteFour()
  self:tryReadyRivalForGoGoggles()
  self:resetMrBriney()
end

function Game3:resetStateAfterWhiteOut()
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_CYCLING_ROAD] = nil
  self.flags[Game3.FLAG_SYS_USE_STRENGTH] = nil
  self.flags[Game3.FLAG_SYS_USE_FLASH] = nil
  self:resetSSTidalFlag()
  self:exitSafariMode()
end

function Game3:blackout()
  local chase = self.battle and self.battle.chase
  local scripted = chase and self.scriptWait
  self:recordBattleEnd(Game3.B_OUTCOME_LOST)
  self:healParty()
  self.phase = "play"
  self.battle = nil
  if scripted then
    self:endScriptWait()
    return
  end
  if chase then
    self:finishBirchChase()
    return
  end
  -- overworld.c DoWhiteOut: EventScript_WhiteOut then money/2 then heal
  -- then Overworld_ResetStateAfterWhiteOut then last-heal warp.
  self:runWhiteOutScript()
  self.money = math.floor((tonumber(self.money) or 0) / 2)
  self:resetStateAfterWhiteOut()
  -- overworld.c sub_805308C: history then RoamerMoveToOtherLocationSet
  -- (UpdateRoamerHPStatus already jumped once on battle end).
  self._skipRoamerMove = true
  self:updateLocationHistoryForRoamer()
  self:roamerMoveToOtherLocationSet()
  self:warpToHeal()
  self._skipRoamerMove = nil
end

function Game3:startWildBattle(species, level)
  local enemy = self:makeMon(species, level)
  self:markSeen(species)
  local player = self:firstHealthy()
  if not player then return false end
  self:clearPoisonStepCounter()
  self:recalcStats(player)
  player.hp = math.min(player.hp or player.maxHp, player.maxHp)
  player.stages = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
  player.focusEnergy = nil
  player.mudSport = nil
  player.waterSport = nil
  player.rage = nil
  player.leechSeed = nil
  player.leechSeedSlot = nil
  player.leechSeedFrom = nil
  player.foresight = nil
  if type(player.moves) ~= "table" or #player.moves < 1 then
    player.moves = self:movesFor(player.species, player.level)
  end
  self.walkCooldown = 0
  self.phase = "battle"
  self.battle = {
    kind = "intro",
    cursor = 0,
    fightCursor = 0,
    partyCursor = 0,
    player = player,
    enemy = enemy,
    text = ("Wild %s appeared!"):format(enemy.name),
    enterBoth = true,
    switchInDone = false,
    turns = 0,
    introT = 0,
    animT = 0,
  }
  self:playBattleMusic("wild")
  if self:inSafariMode() then
    local rate = enemy.catchRate or 45
    self.battle.safari = true
    self.battle.safariCatchFactor = math.floor(rate * 100 / 1275)
    self.battle.safariFleeRate = 3
    self.battle.safariGoNearCounter = 0
    self.battle.safariPkblThrowCounter = 0
  end
  self:resetBattleResults()
  self:applyOverworldBattleWeather()
  self:markSentIn(player)
  return true
end

function Game3:setWildBattle(species, level, item)
  self.scriptedWild = {
    species = tonumber(species) or 0,
    level = tonumber(level) or 1,
    item = tonumber(item) or 0,
  }
end

function Game3:doWildBattle(opts)
  local spec = self.scriptedWild
  if not spec then return false end
  self:beginScriptWait()
  if not self:startWildBattle(spec.species, spec.level) then
    self:endScriptWait()
    return false
  end
  local item = spec.item or 0
  if item ~= 0 then self.battle.enemy.item = item end
  self.battle.scriptedWild = true
  opts = opts or {}
  -- BATTLE_TYPE_LEGENDARY skips wild held-item rolls (already ITEM_NONE
  -- here). CanRunFromBattle does not check it; RUN still works.
  if opts.legendary then self.battle.legendary = true end
  if opts.kyogreGroudon then self.battle.kyogreGroudon = true end
  if opts.regi then self.battle.regi = true end
  self:incrementGameStat(Game3.GAME_STAT_TOTAL_BATTLES)
  self:incrementGameStat(Game3.GAME_STAT_WILD_BATTLES)
  return true
end

-- battle_setup.c ScrSpecial_StartGroudonKyogreBattle. Same callback as
-- dowildbattle (CB2_EndScriptedWildBattle). Must beginScriptWait.
function Game3:startGroudonKyogreBattle()
  return self:doWildBattle({ legendary = true, kyogreGroudon = true })
end

function Game3:startRayquazaBattle()
  return self:doWildBattle({ legendary = true })
end

function Game3:startRegiBattle()
  return self:doWildBattle({ legendary = true, regi = true })
end

function Game3:startSouthernIslandBattle()
  return self:doWildBattle({ legendary = true })
end

-- overworld.c sub_8054D4C: returning to the field runs ON_RESUME
-- (New Mauville Voltorb FLAG_SYS_CTRL_OBJ_DELETE / removeobject).
function Game3:runOnResumeFromBattle()
  local pause = self._scriptPause
  local ret = self._scriptReturn
  local loaded = self._scriptLoaded
  local cmp = self._scriptCmp
  self:runMapScript("onResume")
  self._scriptPause = pause
  self._scriptReturn = ret
  self._scriptLoaded = loaded
  self._scriptCmp = cmp
end

function Game3:endBattle()
  self:randomlyGivePartyPokerus()
  self:partySpreadPokerus()
  local chase = self.battle and self.battle.chase
  local after = self.battle and self.battle.afterText
  local scripted = self.scriptWait
  local pending = self.pendingEvo
  local safari = self.battle and self.battle.safari
  local outcome = self.battleOutcome
  self:restorePartySpeciesTypes()
  self.phase = "play"
  self.battle = nil
  self:playMapMusic()
  -- battle_main.c TryEvolvePokemon: only after B_OUTCOME_WON, and only
  -- for mons that leveled in that fight. Mid-battle KO of the first of
  -- two trainer mons must not evolve. The field script (RoxanneDefeated
  -- / gotobeatenscript) waits until finishPostBattleScenes after the
  -- evo and learn-move prompts; returning here used to drop the badge.
  if outcome == Game3.B_OUTCOME_WON and pending and #pending > 0 then
    self.pendingEvo = pending
    self:startPendingEvolve()
    return
  end
  self.pendingEvo = nil
  self:runOnResumeFromBattle()
  if scripted then
    self:endScriptWait()
    if safari then self:afterSafariBattle(outcome) end
    return
  end
  if chase then
    self:finishBirchChase()
  elseif type(after) == "string" and after ~= "" then
    self.field = { kind = "talk", text = after }
  elseif safari then
    self:afterSafariBattle(outcome)
  end
end

-- pokeruby sPickupItems: (item, cumulative chance) pairs.  RS ignores
-- level.  The ROM stores King's Rock's threshold as 1, so roll 99 walks
-- off the table; 100 makes that 1% slot work.
Game3.PICKUP_ITEMS = {
  22, 30,
  23, 40,
  2, 50,
  68, 60,
  19, 70,
  24, 80,
  110, 90,
  64, 95,
  69, 99,
  187, 100,
}

function Game3.rollPickupItem(_level, roll)
  if roll == nil then roll = _level end
  roll = tonumber(roll) or 0
  if roll < 0 then roll = 0 elseif roll > 99 then roll = 99 end
  local pairs = Game3.PICKUP_ITEMS
  for i = 1, #pairs, 2 do
    if pairs[i + 1] > roll then
      return pairs[i]
    end
  end
  return pairs[#pairs - 1]
end

function Game3:tryPickup()
  -- pokeruby atkE5_pickup: empty hold slot, not the BAG. Silent.
  local texts = {}
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and (mon.species or 0) > 0 and not mon.isEgg
        and self:hasAbility(mon, Game3.ABILITY_PICKUP)
        and (tonumber(mon.item) or 0) == 0 then
      if self:rand(10) == 1 then
        local id = Game3.rollPickupItem(mon.level or 1, self:rand(100) - 1)
        if id and id > 0 then
          mon.item = id
        end
      end
    end
  end
  return texts
end

function Game3:finishBattle()
  local b = self.battle
  if not b or b.pickupDone then
    self:endBattle()
    return
  end
  b.pickupDone = true
  local lines = self:tryPickup()
  if #lines > 0 then
    b.kind = "text"
    b.queue = lines
    b.qi = 1
    b.text = lines[1]
    return
  end
  self:endBattle()
end

function Game3:dismissIntro()
  local b = self.battle
  if not b then return end
  local lines = {}
  local function addEnter(mon, foe)
    if not mon or not foe then return end
    local extra = self:activateEnter(mon, foe)
    for i = 1, #extra do lines[#lines + 1] = extra[i] end
  end
  if not b.switchInDone then
    b.switchInDone = true
    if b.owWeatherLine then
      lines[#lines + 1] = b.owWeatherLine
      b.owWeatherLine = nil
    end
    addEnter(b.enemy, b.player or b.player2)
    addEnter(b.enemy2, b.player2 or b.player)
    if b.enterBoth then
      addEnter(b.player, b.enemy or b.enemy2)
      addEnter(b.player2, b.enemy2 or b.enemy)
    end
    b.enterBoth = nil
  end
  if #lines > 0 then
    b.queue = lines
    b.qi = 1
    b.kind = "text"
    b.text = lines[1]
  else
    b.kind = "menu"
    b.text = nil
  end
  self:tryWallyTutorialAction()
end

function Game3:recalcStats(mon)
  local row = self:speciesRow(mon.species) or {}
  local level = mon.level or 1
  local ivs = mon.ivs or Game3.zeroIvs()
  local pid = mon.pid or 0
  local oldMax = mon.maxHp or 0
  mon.maxHp = Game3.statHP(row.hp or 45, level, ivs.hp, mon.hpEv)
  mon.atk = Game3.statOther(row.atk or 49, level, ivs.atk,
    Game3.natureMul(pid, Game3.STAT_ATK), mon.atkEv)
  mon.def = Game3.statOther(row.def or 49, level, ivs.def,
    Game3.natureMul(pid, Game3.STAT_DEF), mon.defEv)
  mon.spe = Game3.statOther(row.spe or 45, level, ivs.spe,
    Game3.natureMul(pid, Game3.STAT_SPE), mon.speEv)
  mon.spa = Game3.statOther(row.spa or 65, level, ivs.spa,
    Game3.natureMul(pid, Game3.STAT_SPA), mon.spaEv)
  mon.spd = Game3.statOther(row.spd or 65, level, ivs.spd,
    Game3.natureMul(pid, Game3.STAT_SPD), mon.spdEv)
  local delta = (mon.maxHp or 0) - oldMax
  local hp = (mon.hp or 0) + delta
  if (mon.hp or 0) <= 0 then
    mon.hp = 0
  else
    mon.hp = math.max(1, hp)
    if mon.hp > mon.maxHp then mon.hp = mon.maxHp end
  end
end

function Game3.isHmMove(id)
  return Game3.HM_MOVES[tonumber(id) or 0] == true
end

function Game3:knowsMove(mon, id)
  local moves = mon and mon.moves or {}
  for i = 1, #moves do
    if moves[i] and moves[i].id == id then return true end
  end
  return false
end

function Game3:partyKnowsMove(id)
  local party = self.party or {}
  for i = 1, #party do
    if self:knowsMove(party[i], id) then return true end
  end
  return false
end

-- ScrCmd_checkpartymove: RESULT is the 0-based slot, or PARTY_SIZE (6)
-- if nobody knows it. Empty species breaks the loop. Eggs are skipped.
-- A hit also writes VAR_0x8004 = that mon's species. Slot 0 is valid.
function Game3:checkPartyMove(move)
  move = tonumber(move) or 0
  local party = self.party or {}
  for i = 0, Game3.PARTY_SIZE - 1 do
    local mon = party[i + 1]
    local species = tonumber(mon and mon.species) or 0
    if species == 0 then break end
    if not mon.isEgg and self:knowsMove(mon, move) then
      self:setScriptVar(0x8004, species)
      return i
    end
  end
  return Game3.PARTY_SIZE
end

function Game3:hasBadge(n)
  n = tonumber(n) or 0
  if n < 1 or n > 8 then return false end
  return self.flags and self.flags[Game3.FLAG_BADGE01_GET + n - 1] == true
end

function Game3:facingCell()
  local dx, dy = Game3.deltaFromFacing(self.facing or "south")
  return (self.playerX or 0) + dx, (self.playerY or 0) + dy
end

function Game3:npcInFront()
  local x, y = self:facingCell()
  return self:npcAt(self.map, x, y)
end

function Game3:cutGrassAround(cx, cy)
  local n = 0
  for dy = -1, 1 do
    for dx = -1, 1 do
      local x, y = cx + dx, cy + dy
      if Game3.isLandGrass(self:behaviorAt(self.map, x, y)) then
        self:writeMetatile(x, y, 0)
        n = n + 1
      end
    end
  end
  return n > 0
end

function Game3:useCut()
  if not self:partyKnowsMove(Game3.MOVE_CUT) then
    return false, "No one in your party knows CUT."
  end
  if not self:hasBadge(1) then
    return false, "You need the STONE BADGE to use CUT."
  end
  local npc = self:npcInFront()
  if npc and npc.graphicsId == Game3.GFX_CUTTABLE_TREE then
    self:removeObject(npc.localId)
    return true, "Used CUT!"
  end
  local x, y = self:facingCell()
  if self:cutGrassAround(x, y) then
    return true, "Used CUT!"
  end
  return false, "You can't use that here!"
end

function Game3:useRockSmash()
  if not self:partyKnowsMove(Game3.MOVE_ROCK_SMASH) then
    return false, "No one in your party knows ROCK SMASH."
  end
  if not self:hasBadge(3) then
    return false, "You need the DYNAMO BADGE to use ROCK SMASH."
  end
  local npc = self:npcInFront()
  if npc and npc.graphicsId == Game3.GFX_BREAKABLE_ROCK then
    self:removeObject(npc.localId)
    -- DoRockSmashMovement: removeobject, then Rusturf, then wild.
    if self:tryUpdateRusturfTunnelState() == 0 then
      self:rockSmashWildEncounter()
    end
    return true, "Used ROCK SMASH!"
  end
  return false, "You can't use that here!"
end

function Game3:canStep(map, x, y)
  map = map or self.map
  local b = self:behaviorAt(map, x, y)
  if Game3.isWaterfall(b) then
    return self.surfing and self.climbing and true or false
  end
  if Game3.isSurfable(b) then
    return self.surfing and true or false
  end
  if not Game3.walkable(map, x, y) then return false end
  -- GetCollisionAtCoords returns Z-mismatch (3) on elevation 1 water
  -- before Surf; those tiles are collision 0 so walkable alone lets
  -- Brendan stroll the shallows. Elevation 0/0xF means "any height".
  if not self.surfing then
    local i = self:gridIndex(map, x, y)
    if i and Game3.elevationOf(map.grid[i]) == 1 then
      return false
    end
  end
  return true
end

-- pokeruby GetLedgeJumpDirection: walking into a solid jump metatile
-- facing that way hops two tiles, landing past the ledge.
function Game3.ledgeDelta(behavior)
  local b = behavior or 0
  if b == Game3.MB_JUMP_EAST then return 1, 0 end
  if b == Game3.MB_JUMP_WEST then return -1, 0 end
  if b == Game3.MB_JUMP_NORTH then return 0, -1 end
  if b == Game3.MB_JUMP_SOUTH then return 0, 1 end
  if b == Game3.MB_JUMP_NORTHEAST then return 1, -1 end
  if b == Game3.MB_JUMP_NORTHWEST then return -1, -1 end
  if b == Game3.MB_JUMP_SOUTHEAST then return 1, 1 end
  if b == Game3.MB_JUMP_SOUTHWEST then return -1, 1 end
end

function Game3:tryLedgeHop(map, dx, dy)
  map = map or self.map
  if not map or self.surfing then return false end
  local nx = self.playerX + dx
  local ny = self.playerY + dy
  local jx, jy = Game3.ledgeDelta(self:behaviorAt(map, nx, ny))
  if not jx or jx ~= dx or jy ~= dy then return false end
  local lx = self.playerX + dx * 2
  local ly = self.playerY + dy * 2
  if self:npcAt(map, lx, ly) then return false end
  if not self:canStep(map, lx, ly) then return false end
  local ox, oy = self.playerX, self.playerY
  self.walkFromX, self.walkFromY = ox, oy
  self.playerX, self.playerY = lx, ly
  self:updatePlayerZCoord()
  self.walkDuration = (self:walkPeriod() or Game3.WALK_PERIOD) * 2
  self.walkCooldown = self.walkDuration
  self.hopping = true
  self:clampCamera()
  if self.ignoreWarp and not Game3.warpAt(map, lx, ly) then
    self.ignoreWarp = false
  end
  self:runStepCallback(ox, oy)
  self:tickWalkCounters()
  self:tryCoordEvent(lx, ly)
  return true
end

function Game3:strengthOn()
  return self.flags and self.flags[Game3.FLAG_SYS_USE_STRENGTH] == true
end

function Game3:pushBoulder(npc, dx, dy)
  if not npc then return false end
  local map = self.map
  local nx, ny = npc.x + dx, npc.y + dy
  if not Game3.walkable(map, nx, ny) then return false end
  if self:npcAt(map, nx, ny) then return false end
  if Game3.warpAt(map, nx, ny) then return false end
  npc.fromX, npc.fromY = npc.x, npc.y
  npc.x, npc.y = nx, ny
  npc.walkDuration = Game3.WALK_PERIOD
  npc.cooldown = Game3.WALK_PERIOD
  self:updateNpcZCoord(npc, map)
  return true
end

function Game3:isDarkMap(map)
  if map and map ~= self.map then
    return map.cave and true or false
  end
  return (self.flashLevel or 0) > 0
end

function Game3:setDefaultFlashLevel(map)
  map = map or self.map
  if not map or not map.cave then
    self.flashLevel = 0
  elseif self.flags and self.flags[Game3.FLAG_SYS_USE_FLASH] then
    self.flashLevel = 1
  else
    self.flashLevel = Game3.MAX_FLASH_LEVEL
  end
end

function Game3:setFlashLevel(level)
  level = tonumber(level) or 0
  if level < 0 or level > Game3.MAX_FLASH_LEVEL then
    level = 0
  end
  self.flashLevel = level
  self.flashAnim = nil
end

function Game3:flashRadius()
  local a = self.flashAnim
  if a then return a.cur or 0 end
  local level = self.flashLevel or 0
  if level < 1 then return 0 end
  return Game3.FLASH_RADII[level] or 24
end

-- WIN0 is a 240×160 screen effect. Survey zoom OUT would scale the
-- 24px hole with the world and leave a speck; keep at least FIT.
-- Letterbox canvases stay at 1px/world so 24px is still 24px.
function Game3:flashOverlayScale(s, vw)
  s = tonumber(s) or 1
  if s < 1 then s = 1 end
  vw = tonumber(vw) or Game3.SCREEN_W
  if vw <= Game3.SCREEN_W then return s end
  local fit = 1
  if self.fitScale then fit = tonumber(self:fitScale()) or 1 end
  if fit < 1 then fit = 1 end
  if s < fit then return fit end
  return s
end

-- pokeruby UpdateFlashLevelEffect: every other frame, radius += delta
-- (±1). Stops when cur > dest (so shrinking almost instantly finishes).
function Game3.flashAnimFrames(fromR, destR, step)
  fromR = tonumber(fromR) or 0
  destR = tonumber(destR) or 0
  if fromR == destR then return 0 end
  local delta = tonumber(step) or Game3.FLASH_ANIM_DELTA
  if fromR >= destR then delta = -delta end
  local cur, frames, guard = fromR, 0, 0
  while guard < 400 do
    frames = frames + 2
    cur = cur + delta
    guard = guard + 1
    if cur > destR then break end
  end
  return frames
end

function Game3:animateFlash(level)
  level = tonumber(level) or 0
  if level < 0 or level > Game3.MAX_FLASH_LEVEL then
    level = 0
  end
  local from = Game3.FLASH_RADII[self.flashLevel or 0] or 200
  local dest = Game3.FLASH_RADII[level] or 200
  if from == dest then
    self.flashLevel = level
    return
  end
  local delta = Game3.FLASH_ANIM_DELTA
  if from >= dest then delta = -delta end
  self.flashAnim = {
    cur = from,
    dest = dest,
    destLevel = level,
    delta = delta,
    phase = 0,
  }
  self:beginScriptWait()
end

function Game3:finishFlashAnim()
  local a = self.flashAnim
  if not a then return false end
  self.flashLevel = a.destLevel or 0
  self.flashAnim = nil
  if self:scriptWaiting() then
    return self:endScriptWait()
  end
  return false
end

function Game3:stepFlashAnim()
  local a = self.flashAnim
  if not a then return false end
  if (a.phase or 0) == 0 then
    a.phase = 1
    return true
  end
  a.phase = 0
  a.cur = (a.cur or 0) + (a.delta or 1)
  if a.cur > (a.dest or 0) then
    self:finishFlashAnim()
    return false
  end
  return true
end

function Game3:stepFlashAnimDt(dt)
  if not self.flashAnim then return end
  self.flashAcc = (self.flashAcc or 0) + (dt or 0)
  local add = math.floor(self.flashAcc * 60 + 1e-6)
  self.flashAcc = self.flashAcc - add / 60
  local i = 1
  while i <= add do
    if not self:stepFlashAnim() then break end
    i = i + 1
  end
end

function Game3:driveFlashAnim()
  local n = 0
  while self.flashAnim and n < 500 do
    self:stepFlashAnim()
    n = n + 1
  end
end

function Game3:useSurf()
  if not self:partyKnowsMove(Game3.MOVE_SURF) then
    return false, "No one in your party knows SURF."
  end
  if not self:hasBadge(5) then
    return false, "You need the BALANCE BADGE to use SURF."
  end
  local x, y = self:facingCell()
  if not Game3.isSurfStart(self:behaviorAt(self.map, x, y)) then
    return false, "You can't use that here!"
  end
  self.bike = nil
  self.surfing = true
  local dx, dy = Game3.deltaFromFacing(self.facing or "south")
  if not self:tryWalk(dx, dy) then
    self.surfing = nil
    return false, "You can't use that here!"
  end
  return true, "Used SURF!"
end

function Game3:useStrength()
  if not self:partyKnowsMove(Game3.MOVE_STRENGTH) then
    return false, "No one in your party knows STRENGTH."
  end
  if not self:hasBadge(4) then
    return false, "You need the HEAT BADGE to use STRENGTH."
  end
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_USE_STRENGTH] = true
  return true, "Used STRENGTH!"
end

function Game3:useFlash()
  if not self:partyKnowsMove(Game3.MOVE_FLASH) then
    return false, "No one in your party knows FLASH."
  end
  if not self:hasBadge(2) then
    return false, "You need the KNUCKLE BADGE to use FLASH."
  end
  if (self.flashLevel or 0) ~= Game3.MAX_FLASH_LEVEL then
    return false, "You can't use that here!"
  end
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_USE_FLASH] = true
  self:setFlashLevel(1)
  return true, "Used FLASH!"
end

function Game3:useWaterfall()
  if not self:partyKnowsMove(Game3.MOVE_WATERFALL) then
    return false, "No one in your party knows WATERFALL."
  end
  if not self:hasBadge(8) then
    return false, "You need the RAIN BADGE to use WATERFALL."
  end
  if not self.surfing then
    return false, "You can't use that here!"
  end
  local x, y = self:facingCell()
  if not Game3.isWaterfall(self:behaviorAt(self.map, x, y)) then
    return false, "You can't use that here!"
  end
  self.climbing = true
  local dx, dy = Game3.deltaFromFacing(self.facing or "south")
  if not self:tryWalk(dx, dy) then
    self.climbing = nil
    return false, "You can't use that here!"
  end
  return true, "Used WATERFALL!"
end

function Game3:isUnderwater(map)
  map = map or self.map
  return map and (map.mapType or 0) == Game3.MAP_TYPE_UNDERWATER
end

function Game3:connectionByDir(map, dir)
  map = map or self.map
  for i = 1, #(map and map.connections or {}) do
    local c = map.connections[i]
    if c and c.dir == dir then return c end
  end
end

function Game3:warpDive(dir)
  local c = self:connectionByDir(self.map, dir)
  if c then
    local dest = self:lookupMap(c.mapGroup, c.mapNum)
    if not dest then return false end
    self:enterMap(dest, self.playerX or 0, self.playerY or 0, false)
    return true
  end
  -- overworld.c SetDiveWarp: no connection → RunOnDiveWarpMapScript,
  -- then gFixedDiveWarp (setdivewarp). Dest xy is the stored warp, not
  -- the player's tile (Sootopolis always lands at 9,6 / 29,53).
  self:runMapScript("onDiveWarp")
  local d = self.diveWarp
  if not d then return false end
  return self:scriptWarp(d.mapGroup, d.mapNum,
    d.warpId or Game3.WARP_ID_NONE, d.x or 0, d.y or 0)
end

function Game3:useDive()
  if not self:partyKnowsMove(Game3.MOVE_DIVE) then
    return false, "No one in your party knows DIVE."
  end
  if not self:hasBadge(7) then
    return false, "You need the MIND BADGE to use DIVE."
  end
  if self:isUnderwater() then
    if Game3.isUnableToEmerge(self:behaviorAt(self.map, self.playerX, self.playerY)) then
      return false, "You can't use that here!"
    end
    if not self:warpDive("emerge") then
      return false, "You can't use that here!"
    end
    self.diving = nil
    self.surfing = true
    self.climbing = nil
    return true, "Used DIVE!"
  end
  if not self.surfing then
    return false, "You can't use that here!"
  end
  if not Game3.isDiveable(self:behaviorAt(self.map, self.playerX, self.playerY)) then
    return false, "You can't use that here!"
  end
  if not self:warpDive("dive") then
    return false, "You can't use that here!"
  end
  self.diving = true
  self.surfing = true
  self.climbing = nil
  return true, "Used DIVE!"
end

function Game3.rodKind(id)
  if id == Game3.ITEM_OLD_ROD then return Game3.OLD_ROD end
  if id == Game3.ITEM_GOOD_ROD then return Game3.GOOD_ROD end
  if id == Game3.ITEM_SUPER_ROD then return Game3.SUPER_ROD end
end

function Game3:canFish()
  if not self.map then return false end
  if self:isUnderwater() then return false end
  local x, y = self:facingCell()
  local b = self:behaviorAt(self.map, x, y)
  if Game3.isWaterfall(b) then return false end
  return Game3.isSurfable(b)
end

function Game3:startFishingWild(rod)
  local enc = self:encountersFor()
  local fish = enc and enc.fish
  if not (fish and fish.slots and #fish.slots > 0) then return false end
  if not self:firstHealthy() then return false end
  return self:startWildFrom(fish, Game3.chooseFishSlot(rod, self:gbaRandom() % 100), true)
end

function Game3:fishingTick(f, joyA)
  local step = f.step or 0
  if step == Game3.FISH_WAIT then
    f.frames = (f.frames or 0) + 1
    if f.frames >= 60 then f.step = Game3.FISH_START_ROUND end
    return false
  end
  if step == Game3.FISH_START_ROUND then
    f.step = Game3.FISH_DOTS
    f.frames = 0
    f.numDots = 0
    local randVal = self:gbaRandom() % 10
    local need = randVal + 1
    if (f.roundsPlayed or 0) == 0 then need = randVal + 4 end
    if need >= 10 then need = 10 end
    f.dotsRequired = need
    f.dotsLine = ""
    f.text = ""
    return true
  end
  if step == Game3.FISH_DOTS then
    if joyA then
      if (f.roundsPlayed or 0) ~= 0 then
        f.step = Game3.FISH_GOT_AWAY
      else
        f.step = Game3.FISH_NO_BITE
      end
      return true
    end
    f.frames = (f.frames or 0) + 1
    if f.frames >= 20 then
      f.frames = 0
      if (f.numDots or 0) >= (f.dotsRequired or 1) then
        f.step = step + 1
        if (f.roundsPlayed or 0) ~= 0 then f.step = f.step + 1 end
        f.roundsPlayed = (f.roundsPlayed or 0) + 1
      else
        f.dotsLine = (f.dotsLine or "") .. Game3.FISH_DOT
        f.numDots = (f.numDots or 0) + 1
        f.text = f.dotsLine
      end
    end
    return false
  end
  if step == 5 then
    f.step = 6
    if (not self:hasFishingMons()) or ((self:gbaRandom() % 2) == 1) then
      f.step = Game3.FISH_NO_BITE
    end
    return true
  end
  if step == 6 then
    f.text = Game3.FISH_TEXT_BITE
    f.step = 7
    f.frames = 0
    return false
  end
  if step == 7 then
    f.frames = (f.frames or 0) + 1
    local limit = Game3.FISH_REEL[f.rod or 0] or 36
    if f.frames >= limit then
      f.step = Game3.FISH_GOT_AWAY
    elseif joyA then
      f.step = 8
    end
    return false
  end
  if step == 8 then
    f.step = 9
    local played = f.roundsPlayed or 0
    if played < (f.minRounds or 1) then
      f.step = Game3.FISH_START_ROUND
    elseif played < 2 then
      local extra = Game3.FISH_EXTRA[f.rod or 0]
      extra = extra and extra[played] or 0
      if extra > (self:gbaRandom() % 100) then
        f.step = Game3.FISH_START_ROUND
      end
    end
    return false
  end
  if step == 9 then
    f.text = Game3.FISH_TEXT_HOOK
    f.step = 10
    f.frames = 0
    return false
  end
  if step == 10 then
    if joyA then
      local rod = f.rod or 0
      self.field = nil
      self:startFishingWild(rod)
    end
    return false
  end
  if step == Game3.FISH_NO_BITE then
    f.text = Game3.FISH_TEXT_NIBBLE
    f.step = Game3.FISH_SHOW_RESULT
    return true
  end
  if step == Game3.FISH_GOT_AWAY then
    f.text = Game3.FISH_TEXT_AWAY
    f.step = Game3.FISH_SHOW_RESULT
    return true
  end
  if step == Game3.FISH_SHOW_RESULT then
    f.step = 14
    return false
  end
  if step == 14 then
    f.step = 15
    return false
  end
  if step == 15 then
    if joyA then self:closeField() end
    return false
  end
  return false
end

function Game3:pumpFishing(joyA)
  local f = self.field
  local guard = 0
  while f and f.kind == "fishing" do
    guard = guard + 1
    if guard > 8 then break end
    if not self:fishingTick(f, joyA) then break end
    f = self.field
  end
end

function Game3:stepFishing(dt)
  local f = self.field
  if not (f and f.kind == "fishing") then return end
  local joyA = f.joyA and true or false
  f.joyA = nil
  if not joyA and Input and Input.pressed and Input.wasPressed then
    joyA = Input:wasPressed("a") and true or false
  end
  f.acc = (f.acc or 0) + (dt or 0)
  local add = math.floor(f.acc * 60 + 1e-6)
  f.acc = f.acc - add / 60
  if add < 1 then
    if joyA then add = 1 else return end
  end
  local i = 1
  while i <= add do
    self:pumpFishing(joyA)
    joyA = false
    if not (self.field and self.field.kind == "fishing") then break end
    if self.phase ~= "play" then break end
    i = i + 1
  end
end

function Game3:driveFishingDots()
  self:stepFishing(61 / 60)
  local n = 0
  while self.field and self.field.kind == "fishing"
      and self.field.step == Game3.FISH_DOTS do
    self:stepFishing(20 / 60)
    n = n + 1
    if n > 24 then break end
  end
  if self.field and self.field.kind == "fishing" and self.field.step == 5 then
    self:stepFishing(1 / 60)
  end
end

function Game3:driveFishingA()
  local f = self.field
  if not (f and f.kind == "fishing") then return end
  f.joyA = true
  self:stepFishing(1 / 60)
end

function Game3:driveFishingHook()
  self:driveFishingDots()
  self:driveFishingA()
  self:stepFishing(1 / 60)
  self:stepFishing(1 / 60)
  self:driveFishingA()
end

function Game3:useRod(id)
  local kind = Game3.rodKind(id)
  if kind == nil then
    return false, "You can't use that here!"
  end
  if not self:canFish() then
    return false, "You can't use that here!"
  end
  local span = Game3.FISH_MIN_SPAN[kind] or 1
  local minRounds = (Game3.FISH_MIN_BASE[kind] or 1) + (self:gbaRandom() % span)
  self.field = {
    kind = "fishing",
    rod = kind,
    step = Game3.FISH_WAIT,
    frames = 0,
    acc = 0,
    roundsPlayed = 0,
    minRounds = minRounds,
    numDots = 0,
    dotsRequired = 0,
    dotsLine = "",
    text = "",
  }
  return true
end

-- Overworld_IsBikingAllowed: cycling-road gates are indoor but keep the bike.
function Game3.canBikeOn(map)
  if not map then return false end
  local g, n = tonumber(map.group), tonumber(map.index)
  if g == nil then
    local gs, ns = tostring(map.id or ""):match("^g(%d+)_(%d+)$")
    g, n = tonumber(gs), tonumber(ns)
  end
  if g == Game3.MAP_ROUTE110_CYCLING_NORTH_GROUP
      and (n == Game3.MAP_ROUTE110_CYCLING_SOUTH_NUM
        or n == Game3.MAP_ROUTE110_CYCLING_NORTH_NUM) then
    return true
  end
  local t = map.mapType or 0
  if t == Game3.MAP_TYPE_INDOOR then return false end
  if t == Game3.MAP_TYPE_SECRET_BASE then return false end
  if t == Game3.MAP_TYPE_UNDERWATER then return false end
  if g == Game3.GRANITE_CAVE_GROUP
      and (n == Game3.MAP_SEAFLOOR_CAVERN_ROOM9_NUM
        or n == Game3.MAP_CAVE_OF_ORIGIN_B4F_NUM) then
    return false
  end
  return true
end

function Game3:wantRun()
  if self.bike or self.surfing or self.diving then return false end
  if not (self.flags and self.flags[Game3.FLAG_SYS_B_DASH]) then return false end
  return Input:isDown("b")
end

function Game3:walkPeriod()
  -- ForcedMovement_MuddySlope uses PlayerGoSpeed2 (run) even on a bike.
  if self.slopeSlide then return Game3.RUN_PERIOD end
  if self.bike == "mach" then return Game3.MACH_PERIOD end
  if self.running then return Game3.RUN_PERIOD end
  return Game3.WALK_PERIOD
end

-- pokeruby GetPlayerSpeed: walk 1, run/surf 2, Acro 3, Mach FASTEST 4.
-- This engine has no Mach gears, so Mach is always FASTEST.
function Game3:playerSpeed()
  if self.bike == "mach" then return 4 end
  if self.bike == "acro" then return 3 end
  if self.running or self.surfing then return 2 end
  return 1
end

function Game3:onMuddySlope()
  return self:behaviorAt(self.map, self.playerX, self.playerY) == Game3.MB_MUDDY_SLOPE
end

-- ForcedMovement_MuddySlope: slide south unless movementDirection is
-- NORTH and GetPlayerSpeed() > 3. Climb is Mach at FASTEST holding up,
-- not facing-north-alone (idle Mach still slides).
function Game3:canClimbMuddySlope()
  return self.bike == "mach" and Input:isDown("up")
end

function Game3:tryMuddySlope()
  if not self.map or not self:onMuddySlope() then
    self.slopeFaceLock = nil
    self.slopeSlide = nil
    return false
  end
  if self:canClimbMuddySlope() then
    self.slopeFaceLock = nil
    self.slopeSlide = nil
    return false
  end
  local face = self.facing
  self.slopeFaceLock = true
  self.slopeSlide = true
  local ok = self:tryWalk(0, 1)
  self.slopeSlide = nil
  if ok then
    self.facing = face
  else
    self.slopeFaceLock = nil
  end
  return ok
end

-- field_player_avatar.c sForcedMovementTestFuncs. Ice / Trick House 8
-- slip in movementDirection at PlayerGoSpeed2. Walk pads are Speed1.
-- Slide pads lock facing at Speed2. Currents ride Speed2 in a fixed dir.
-- Waterfall is already climbing; do not push south here.
function Game3.forcedMoveSpec(behavior, facing)
  behavior = tonumber(behavior) or 0
  if behavior == Game3.MB_ICE
      or behavior == Game3.MB_TRICK_HOUSE_PUZZLE_8_FLOOR then
    local dx, dy = Game3.deltaFromFacing(facing)
    return dx, dy, "run", false
  end
  if behavior == Game3.MB_WALK_EAST then return 1, 0, "walk", false end
  if behavior == Game3.MB_WALK_WEST then return -1, 0, "walk", false end
  if behavior == Game3.MB_WALK_NORTH then return 0, -1, "walk", false end
  if behavior == Game3.MB_WALK_SOUTH then return 0, 1, "walk", false end
  if behavior == Game3.MB_SLIDE_EAST then return 1, 0, "run", true end
  if behavior == Game3.MB_SLIDE_WEST then return -1, 0, "run", true end
  if behavior == Game3.MB_SLIDE_NORTH then return 0, -1, "run", true end
  if behavior == Game3.MB_SLIDE_SOUTH then return 0, 1, "run", true end
  if behavior == Game3.MB_EASTWARD_CURRENT then return 1, 0, "run", false end
  if behavior == Game3.MB_WESTWARD_CURRENT then return -1, 0, "run", false end
  if behavior == Game3.MB_NORTHWARD_CURRENT then return 0, -1, "run", false end
  if behavior == Game3.MB_SOUTHWARD_CURRENT then return 0, 1, "run", false end
end

function Game3:tryForcedMovement()
  if not self.map then return false end
  if self:onMuddySlope() then
    return self:tryMuddySlope()
  end
  local b = self:behaviorAt(self.map, self.playerX, self.playerY)
  local dx, dy, speed, faceLock = Game3.forcedMoveSpec(b, self.facing)
  if dx == nil then
    self.slopeFaceLock = nil
    self.slopeSlide = nil
    return false
  end
  local face = self.facing
  if faceLock then self.slopeFaceLock = true end
  if speed == "run" then self.slopeSlide = true end
  local ok = self:tryWalk(dx, dy)
  self.slopeSlide = nil
  if ok then
    if faceLock then self.facing = face end
  else
    self.slopeFaceLock = nil
  end
  return ok
end

function Game3:useBike(id)
  local kind
  if id == Game3.ITEM_MACH_BIKE then
    kind = "mach"
  elseif id == Game3.ITEM_ACRO_BIKE then
    kind = "acro"
  else
    return false, "You can't use that here!"
  end
  local name = kind == "mach" and "MACH BIKE" or "ACRO BIKE"
  if self.surfing or self:isUnderwater() then
    return false, "You can't use that here!"
  end
  if self.bike == kind then
    self.bike = nil
    return true, ("Got off the %s."):format(name)
  end
  if not Game3.canBikeOn(self.map) then
    return false, "You can't use that here!"
  end
  self.bike = kind
  self.running = nil
  return true, ("Got on the %s."):format(name)
end

function Game3.flyDestFor(map)
  if not map then return nil end
  local id = type(map) == "table" and map.id or map
  return Game3.FLY_BY_ID[id]
end

function Game3.canFlyFrom(map)
  if not map then return false end
  local t = map.mapType or 0
  return t == Game3.MAP_TYPE_TOWN
    or t == Game3.MAP_TYPE_CITY
    or t == Game3.MAP_TYPE_ROUTE
    or t == Game3.MAP_TYPE_OCEAN_ROUTE
end

function Game3:repelBlocks(level)
  if (self.repelSteps or 0) < 1 then return false end
  local mon = self:firstHealthy()
  if not mon then return false end
  return (level or 1) <= (mon.level or 1)
end

function Game3:tickWalkCounters()
  self:incrementGameStat(Game3.GAME_STAT_STEPS)
  self:tickRepel()
  self:tickDaycare()
  self:tickEggCycles()
  self:tickHappinessSteps()
  self:tickPoisonSteps()
  self:incrementRematchStepCounter()
  self:safariZoneTakeStep()
  self:ssTidalTakeStep()
end

-- field_poison.c IsMonValidSpecies + STATUS_PRIMARY_POISON.
-- Eggs and empty slots skip. Toxic is stored as STATUS_PSN.
function Game3:isFieldPoisoned(mon)
  if not mon or mon.isEgg then return false end
  if (self:partyMonSpecies2(mon) or 0) == 0 then return false end
  return mon.status == Game3.STATUS_PSN
end

-- field_poison.c DoPoisonFieldEffect. Return 2 if any poisoned mon
-- hit 0 HP this tick (starts gUnknown_081A14B8).
function Game3:doPoisonFieldEffect()
  local party = self.party or {}
  local poisoned = 0
  local fainting = 0
  for i = 1, #party do
    local mon = party[i]
    if self:isFieldPoisoned(mon) then
      poisoned = poisoned + 1
      local hp = mon.hp or 0
      if hp > 0 then hp = hp - 1 end
      mon.hp = hp
      if hp == 0 then fainting = fainting + 1 end
    end
  end
  if fainting > 0 then return 2 end
  if poisoned > 0 then return 1 end
  return 0
end

function Game3:clearPoisonStepCounter()
  self:setScriptVar(Game3.VAR_POISON_STEP_COUNTER, 0)
end

-- field_control_avatar.c UpdatePoisonStepCounter. Secret bases skip.
-- Counter ++ % 4; on 0 run DoPoisonFieldEffect.
function Game3:tickPoisonSteps()
  local map = self.map
  if map and (map.mapType or 0) == Game3.MAP_TYPE_SECRET_BASE then return end
  local n = (self:varGet(Game3.VAR_POISON_STEP_COUNTER) + 1) % 4
  self:setScriptVar(Game3.VAR_POISON_STEP_COUNTER, n)
  if n ~= 0 then return end
  if self:doPoisonFieldEffect() == 2 then
    self:startFieldPoisonWhiteout()
  end
end

function Game3:allValidMonsFainted()
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    local sp = self:partyMonSpecies2(mon)
    if sp ~= 0 and sp ~= Game3.SPECIES_EGG and (mon.hp or 0) > 0 then
      return false
    end
  end
  return true
end

function Game3:monFaintedFromPoison(mon)
  if not self:isFieldPoisoned(mon) then return false end
  return (mon.hp or 0) == 0
end

function Game3:queueFieldTalk(texts, thenWhiteout)
  if type(texts) ~= "table" or #texts < 1 then return end
  if self._scriptSays then
    for i = 1, #texts do self:sayScript(texts[i]) end
    return
  end
  if self.field then return end
  self.field = {
    kind = "talk",
    text = texts[1],
    queue = texts,
    qi = 1,
    thenWhiteout = thenWhiteout or nil,
  }
end

-- field_poison.c ExecuteWhiteOut / Task_WhiteOut: friendship, clear
-- status, "{nick} fainted...". RESULT 1 if every valid mon is down.
function Game3:executeWhiteOut()
  local party = self.party or {}
  local texts = {}
  for i = 1, #party do
    local mon = party[i]
    if self:monFaintedFromPoison(mon) then
      self:adjustFriendship(mon, Game3.FRIENDSHIP_EVENT_FAINT_OUTSIDE_BATTLE)
      mon.status = nil
      self:setStringVar(1, mon.name or "POKeMON")
      texts[#texts + 1] = self:expandScriptText(Game3.TEXT_POKEMON_FAINTED)
    end
  end
  local n = self:allValidMonsFainted() and 1 or 0
  self:setScriptVar(Gen3Script.VAR_RESULT, n)
  self:queueFieldTalk(texts, false)
  return n
end

-- Walk path owns gUnknown_081A14B8: faint texts, then the whiteout
-- line, then DoWhiteOut after A. Script IR still hits specials 199/200.
function Game3:startFieldPoisonWhiteout()
  local n = self:executeWhiteOut()
  if n ~= 1 then return n end
  local line = self:expandScriptText(Game3.TEXT_WHITED_OUT)
  local f = self.field
  if f and f.kind == "talk" then
    local q = f.queue
    if type(q) ~= "table" then
      q = { f.text }
      f.queue = q
      f.qi = 1
    end
    q[#q + 1] = line
    f.thenWhiteout = true
  elseif self._scriptSays then
    self:sayScript(line)
  else
    self.field = { kind = "talk", text = line, thenWhiteout = true }
  end
  return n
end

function Game3:sp0C8WhiteoutMaybe()
  local f = self.field
  if f and f.thenWhiteout then return 0 end
  self:blackout()
  return 0
end

function Game3:tickRepel()
  local n = self.repelSteps or 0
  if n < 1 then return end
  n = n - 1
  if n < 1 then
    self.repelSteps = nil
    if not self.field then
      self.field = { kind = "talk", text = "REPEL's effect wore off!" }
    end
  else
    self.repelSteps = n
  end
end

function Game3:useRepel(id)
  local steps = Game3.REPEL_STEPS[id]
  if not steps then return false, "You can't use that here!" end
  if not self:takeItem(id, 1) then
    return false, "You can't use that here!"
  end
  self.repelSteps = steps
  return true, ("Used the %s."):format(self:itemName(id))
end

-- item_use.c ItemUseOutOfBattle_BlackWhiteFlute. Not consumed. Lasts
-- until the next LoadMap ClearTempFieldEventData.
function Game3:useBlackWhiteFlute(id)
  if id ~= Game3.ITEM_WHITE_FLUTE and id ~= Game3.ITEM_BLACK_FLUTE then
    return false, "It won't have any effect."
  end
  if self:itemCount(id) < 1 then
    return false, "You have none left!"
  end
  self.flags = self.flags or {}
  local name = self:itemName(id)
  if id == Game3.ITEM_WHITE_FLUTE then
    self.flags[Game3.FLAG_SYS_ENC_UP_ITEM] = true
    self.flags[Game3.FLAG_SYS_ENC_DOWN_ITEM] = nil
    return true, ("%s used the %s.\nWild POKéMON will be lured."):format(
      self:playerName(), name)
  end
  self.flags[Game3.FLAG_SYS_ENC_DOWN_ITEM] = true
  self.flags[Game3.FLAG_SYS_ENC_UP_ITEM] = nil
  return true, ("%s used the %s.\nWild POKéMON will be repelled."):format(
    self:playerName(), name)
end

function Game3.canEscapeFrom(map)
  if not map then return false end
  local t = map.mapType or 0
  if t == Game3.MAP_TYPE_UNDERWATER then return false end
  if map.allowEscaping then return true end
  if map.cave then return true end
  return t == Game3.MAP_TYPE_UNDERGROUND
end

function Game3:useEscapeRope()
  if self.surfing or self.diving or self:isUnderwater() then
    return false, "You can't use that here!"
  end
  if not Game3.canEscapeFrom(self.map) then
    return false, "You can't use that here!"
  end
  if not self:takeItem(Game3.ITEM_ESCAPE_ROPE, 1) then
    return false, "You can't use that here!"
  end
  self:warpToEscape()
  return true, "Used the ESCAPE ROPE!"
end

function Game3.canTeleportFrom(map)
  return Game3.canFlyFrom(map)
end

function Game3:useTeleport()
  if not self:partyKnowsMove(Game3.MOVE_TELEPORT) then
    return false, "No one in your party knows TELEPORT."
  end
  if not Game3.canTeleportFrom(self.map) then
    return false, "You can't use that here!"
  end
  self:warpToHeal()
  return true, "Used TELEPORT!"
end

function Game3:useDig()
  if not self:partyKnowsMove(Game3.MOVE_DIG) then
    return false, "No one in your party knows DIG."
  end
  if self.surfing or self.diving or self:isUnderwater() then
    return false, "You can't use that here!"
  end
  if not Game3.canEscapeFrom(self.map) then
    return false, "You can't use that here!"
  end
  self:warpToEscape()
  return true, "Used DIG!"
end

function Game3:usePartyFieldMove(mon)
  if not mon then return false, "No POKeMON." end
  if self:knowsMove(mon, Game3.MOVE_TELEPORT)
      and Game3.canTeleportFrom(self.map) then
    return self:useTeleport()
  end
  if self:knowsMove(mon, Game3.MOVE_DIG) and Game3.canEscapeFrom(self.map)
      and not (self.surfing or self.diving or self:isUnderwater()) then
    return self:useDig()
  end
  if self:knowsMove(mon, Game3.MOVE_SWEET_SCENT) then
    return self:useSweetScent()
  end
  if self:knowsMove(mon, Game3.MOVE_SECRET_POWER) then
    return self:useSecretPower()
  end
  if self:knowsMove(mon, Game3.MOVE_TELEPORT)
      or self:knowsMove(mon, Game3.MOVE_DIG) then
    return false, "You can't use that here!"
  end
  return false, "No moves to use here."
end

function Game3:hasPartyFieldMove(mon)
  local list = Game3.PARTY_FIELD_MOVES
  for i = 1, #list do
    if self:knowsMove(mon, list[i].id) then return true end
  end
  return false
end

function Game3:partyFieldMoves(mon)
  local moves = {}
  local list = Game3.PARTY_FIELD_MOVES
  for i = 1, #list do
    local row = list[i]
    if self:knowsMove(mon, row.id) then
      moves[#moves + 1] = row.name
    end
  end
  return moves
end

function Game3:partyActions(mon)
  local actions = { "SUMMARY", "SWITCH" }
  if mon and not mon.isEgg then
    actions[#actions + 1] = "ITEM"
  end
  local moves = self:partyFieldMoves(mon)
  for i = 1, #moves do
    actions[#actions + 1] = moves[i]
  end
  actions[#actions + 1] = "CANCEL"
  return actions
end

function Game3:partyItemActions(mon)
  local actions = { "GIVE" }
  if mon and mon.item then actions[#actions + 1] = "TAKE" end
  actions[#actions + 1] = "CANCEL"
  return actions
end

function Game3:canGiveHeld(id)
  id = tonumber(id) or 0
  if id < 1 then return false end
  local pocket = self:itemPocket(id)
  if pocket == Game3.POCKET_KEY or pocket == Game3.POCKET_TMHM then
    return false
  end
  return true
end

function Game3:giveHeldItem(monIndex, itemId)
  local mon = (self.party or {})[monIndex]
  if not mon or mon.isEgg then
    return false, "It won't have any effect."
  end
  if not self:canGiveHeld(itemId) then
    return false, "This can't be given."
  end
  if not self:takeItem(itemId, 1) then
    return false, "You have none left!"
  end
  local old = mon.item
  mon.item = itemId
  if old then self:addItem(old, 1) end
  return true, ("%s was given the %s to hold."):format(
    mon.name or "POKeMON", self:itemName(itemId))
end

function Game3:takeHeldItem(monIndex)
  local mon = (self.party or {})[monIndex]
  local id = mon and mon.item
  if not id then
    return false, ("%s isn't holding anything."):format(
      (mon and mon.name) or "POKeMON")
  end
  self:addItem(id, 1)
  mon.item = nil
  return true, ("Received the %s from %s."):format(
    self:itemName(id), mon.name or "POKeMON")
end

function Game3:tickHeldItem(mon)
  if not mon or (mon.hp or 0) <= 0 then return {} end
  local id = mon.item
  if not id then return {} end
  local texts = {}
  local amount = self:healAmount(id)
  local clears = self:statusHeal(id)
  local used = false
  if amount and (mon.hp or 0) * 2 <= (mon.maxHp or 0) then
    local heal = math.min(amount, (mon.maxHp or 0) - (mon.hp or 0))
    if heal > 0 then
      mon.hp = (mon.hp or 0) + heal
      texts[#texts + 1] = ("The %s restored %s's HP!"):format(
        self:itemName(id), mon.name or "POKeMON")
      used = true
    end
  end
  if not used and clears and mon.status then
    if clears == true or mon.status == clears then
      mon.status = nil
      mon.sleepTurns = nil
      texts[#texts + 1] = ("%s's %s cured its status!"):format(
        mon.name or "POKeMON", self:itemName(id))
      used = true
    end
  end
  if used then mon.item = nil end
  return texts
end

function Game3:openBagForGive(monIndex)
  self:openBag()
  self.field.giveTo = monIndex
  return true
end

function Game3:usePartyFieldMoveNamed(mon, name)
  if name == "CUT" then return self:useCut() end
  if name == "FLASH" then return self:useFlash() end
  if name == "ROCK SMASH" then return self:useRockSmash() end
  if name == "STRENGTH" then return self:useStrength() end
  if name == "SURF" then return self:useSurf() end
  if name == "FLY" then return self:useFly() end
  if name == "DIVE" then return self:useDive() end
  if name == "WATERFALL" then return self:useWaterfall() end
  if name == "TELEPORT" then return self:useTeleport() end
  if name == "DIG" then return self:useDig() end
  if name == "SECRET POWER" then return self:useSecretPower() end
  if name == "SWEET SCENT" then return self:useSweetScent() end
  return self:usePartyFieldMove(mon)
end

function Game3:swapParty(a, b)
  local party = self.party or {}
  a, b = tonumber(a), tonumber(b)
  if not a or not b or a == b then return false end
  if not party[a] or not party[b] then return false end
  party[a], party[b] = party[b], party[a]
  return true
end

function Game3:useSweetScent()
  if not self:partyKnowsMove(Game3.MOVE_SWEET_SCENT) then
    return false, "No one in your party knows SWEET SCENT."
  end
  if self:trySweetScentEncounter() then
    return true, "Used SWEET SCENT!"
  end
  return true, "Looks like there's nothing here."
end

function Game3.isSecretBaseSpot(behavior)
  local b = behavior or 0
  return b >= Game3.MB_SECRET_BASE_SPOT_MIN
    and b <= Game3.MB_SECRET_BASE_SPOT_MAX
end

function Game3.makeSecretBaseMap()
  local w, h = 7, 6
  local grid = {}
  local behavior = {}
  for y = 0, h - 1 do
    for x = 0, w - 1 do
      local wall = x == 0 or y == 0 or x == w - 1 or y == h - 1
      grid[#grid + 1] = wall and 1024 or 0
    end
  end
  local pc = 1 * w + 3 + 1
  grid[pc] = 1024
  behavior[pc] = Game3.MB_SECRET_BASE_PC
  return {
    id = Game3.SECRET_BASE_MAP_ID,
    name = "SECRET BASE",
    mapType = Game3.MAP_TYPE_SECRET_BASE,
    width = w,
    height = h,
    grid = grid,
    behavior = behavior,
    spawn = { x = 3, y = 4 },
    warps = { { x = 3, y = 5, warpId = 0, mapGroup = 0, mapNum = 0 } },
  }
end

function Game3:secretBaseMap()
  if type(self._secretBaseMap) ~= "table" then
    self._secretBaseMap = Game3.makeSecretBaseMap()
  end
  return self._secretBaseMap
end

function Game3:secretBaseSpot(map, x, y)
  map = map or self.map
  if not map then return nil end
  local bg = Game3.bgAt(map, x, y)
  if bg and bg.kind == Game3.BG_SECRET_BASE then
    return {
      id = tonumber(bg.secretBaseId) or 0,
      mapId = map.id,
      x = x,
      y = y,
    }
  end
  if Game3.isSecretBaseSpot(self:behaviorAt(map, x, y)) then
    return { id = 0, mapId = map.id, x = x, y = y }
  end
  return nil
end

function Game3:ownsSecretBaseAt(spot)
  local sb = self.secretBase
  if type(sb) ~= "table" or type(spot) ~= "table" then return false end
  return sb.mapId == spot.mapId and sb.x == spot.x and sb.y == spot.y
end

function Game3:isOwnedSecretBaseTile(map, x, y)
  local sb = self.secretBase
  if type(sb) ~= "table" or not map then return false end
  return map.id == sb.mapId and x == sb.x and y == sb.y
end

function Game3:setCurrentSecretBaseVar()
  local id = 0
  if type(self.secretBase) == "table" then
    id = tonumber(self.secretBase.id) or 0
  end
  self:setScriptVar(Game3.VAR_CURRENT_SECRET_BASE, id)
end

function Game3:snapshotSecretBase()
  local sb = self.secretBase
  if type(sb) ~= "table" then return nil end
  return {
    id = sb.id or 0,
    mapId = sb.mapId,
    x = sb.x or 0,
    y = sb.y or 0,
    outX = sb.outX or 0,
    outY = sb.outY or 0,
  }
end

function Game3:loadSecretBase(data)
  if type(data) ~= "table" then
    self.secretBase = nil
    self:setCurrentSecretBaseVar()
    return
  end
  self.secretBase = {
    id = tonumber(data.id) or 0,
    mapId = data.mapId,
    x = tonumber(data.x) or 0,
    y = tonumber(data.y) or 0,
    outX = tonumber(data.outX) or 0,
    outY = tonumber(data.outY) or 0,
  }
  self:setCurrentSecretBaseVar()
end

function Game3:createSecretBase(spot)
  if type(spot) ~= "table" then return false end
  self.secretBase = {
    id = tonumber(spot.id) or 0,
    mapId = spot.mapId or (self.map and self.map.id),
    x = spot.x or 0,
    y = spot.y or 0,
    outX = self.playerX or 0,
    outY = self.playerY or 0,
  }
  self:setCurrentSecretBaseVar()
  return true
end

function Game3:enterSecretBase()
  if type(self.secretBase) ~= "table" then return false end
  if self.map and self.map.id ~= Game3.SECRET_BASE_MAP_ID then
    self.secretBase.outX = self.playerX or 0
    self.secretBase.outY = self.playerY or 0
    if self.map.id then self.secretBase.mapId = self.map.id end
  end
  local dest = self:secretBaseMap()
  local spawn = dest.spawn or { x = 3, y = 4 }
  self:enterMap(dest, spawn.x, spawn.y, false)
  return true
end

function Game3:exitSecretBase()
  local sb = self.secretBase
  if type(sb) ~= "table" or not sb.mapId then return false end
  local dest = self:lookupMapById(sb.mapId)
  if not dest then return false end
  self:enterMap(dest, sb.outX or sb.x or 0, sb.outY or sb.y or 0, true)
  return true
end

function Game3:hasSecretBase()
  return type(self.secretBase) == "table" and self.secretBase.mapId ~= nil
end

function Game3:useSecretPower()
  if not self:partyKnowsMove(Game3.MOVE_SECRET_POWER) then
    return false, "No one in your party knows SECRET POWER."
  end
  local x, y = self:facingCell()
  local spot = self:secretBaseSpot(self.map, x, y)
  if not spot then
    return false, "You can't use that here!"
  end
  if self:ownsSecretBaseAt(spot) then
    self:enterSecretBase()
    return true, "Used SECRET POWER!"
  end
  if self:hasSecretBase() then
    self.field = {
      kind = "secret_base_move",
      cursor = 0,
      spot = spot,
      text = "Move your SECRET BASE here?",
    }
    return true, "Used SECRET POWER!"
  end
  self:createSecretBase(spot)
  self:enterSecretBase()
  return true, "Used SECRET POWER!"
end

function Game3:ensureDaycare()
  if type(self.daycare) ~= "table" then self.daycare = {} end
end

function Game3:daycareCount()
  self:ensureDaycare()
  local n = 0
  for i = 1, Game3.DAYCARE_SLOTS do
    if self.daycare[i] and self.daycare[i].mon then n = n + 1 end
  end
  return n
end

function Game3:daycareState()
  if (self.daycarePending or 0) ~= 0 then return 1 end
  local n = self:daycareCount()
  if n < 1 then return 0 end
  return n + 1
end

function Game3:snapshotDaycare()
  self:ensureDaycare()
  local out = {}
  for i = 1, Game3.DAYCARE_SLOTS do
    local row = self.daycare[i]
    if row and row.mon then
      local mail
      if type(row.mail) == "table" then
        mail = {
          itemId = tonumber(row.mail.itemId) or 0,
          otName = row.mail.otName or "",
          nick = row.mail.nick or "",
        }
      end
      out[i] = {
        mon = self:snapshotMon(row.mon),
        steps = row.steps or 0,
        mail = mail,
      }
    end
  end
  return out
end

function Game3:loadDaycare(data)
  self.daycare = {}
  if type(data) ~= "table" then return end
  for i = 1, Game3.DAYCARE_SLOTS do
    local row = data[i]
    if row and row.mon then
      local mon = self:restoreMon(row.mon)
      if mon then
        local mail
        if type(row.mail) == "table" then
          mail = {
            itemId = tonumber(row.mail.itemId) or 0,
            otName = row.mail.otName or "",
            nick = row.mail.nick or "",
          }
        end
        self.daycare[i] = {
          mon = mon, steps = tonumber(row.steps) or 0, mail = mail,
        }
      end
    end
  end
end

function Game3:tickDaycare()
  self:ensureDaycare()
  for i = 1, Game3.DAYCARE_SLOTS do
    local row = self.daycare[i]
    if row and row.mon then
      row.steps = (row.steps or 0) + 1
    end
  end
  self:maybePendingEgg()
end

function Game3:compactDaycare()
  self:ensureDaycare()
  if not (self.daycare[1] and self.daycare[1].mon)
      and self.daycare[2] and self.daycare[2].mon then
    self.daycare[1] = self.daycare[2]
    self.daycare[2] = nil
  end
end

function Game3:applyDaycareExp(mon, steps)
  if not mon then return 0 end
  local from = mon.level or 1
  if from >= Game3.DAYCARE_MAX_LEVEL then return 0 end
  local growth = mon.growth or Game3.GROWTH_MEDIUM_SLOW
  mon.exp = (mon.exp or Game3.expAtLevel(growth, from)) + (steps or 0)
  while (mon.level or 1) < Game3.DAYCARE_MAX_LEVEL do
    local need = Game3.expAtLevel(growth, (mon.level or 1) + 1)
    if (mon.exp or 0) < need then break end
    mon.level = (mon.level or 1) + 1
    self:recalcStats(mon)
    self:tryLearnLevelMoves(mon)
  end
  return (mon.level or 1) - from
end

function Game3:daycarePreview(slot)
  self:ensureDaycare()
  local row = self.daycare[slot]
  if not (row and row.mon) then return nil end
  local mon = self:cloneMon(row.mon)
  local from = mon.level or 1
  local gained = self:applyDaycareExp(mon, row.steps or 0)
  return {
    slot = slot,
    name = mon.name or "POKeMON",
    fromLevel = from,
    toLevel = mon.level or from,
    gained = gained,
    cost = Game3.DAYCARE_BASE_COST + Game3.DAYCARE_BASE_COST * gained,
  }
end

function Game3:daycareCost(slot)
  local preview = self:daycarePreview(slot)
  return preview and preview.cost or 0
end

function Game3:daycareLevelsGained(slot)
  local preview = self:daycarePreview(slot)
  return preview and preview.gained or 0
end

function Game3:takeMailFromMon(mon)
  if not mon then return nil end
  local mail = mon.mail
  local item = tonumber(mon.item) or 0
  if type(mail) == "table" and (tonumber(mail.itemId) or 0) ~= Game3.ITEM_NONE then
    mon.mail = nil
    if Game3.isMailItem(item) then mon.item = Game3.ITEM_NONE end
    return {
      itemId = tonumber(mail.itemId) or 0,
      otName = self:playerName(),
      nick = mon.name or "",
    }
  end
  if Game3.isMailItem(item) then
    mon.item = Game3.ITEM_NONE
    return {
      itemId = item,
      otName = self:playerName(),
      nick = mon.name or "",
    }
  end
  return nil
end

function Game3:giveMailToMon(mon, mail)
  if not (mon and type(mail) == "table") then return end
  local itemId = tonumber(mail.itemId) or 0
  if itemId == Game3.ITEM_NONE then return end
  mon.mail = {
    itemId = itemId,
    otName = mail.otName or "",
    nick = mail.nick or "",
  }
  mon.item = itemId
end

function Game3:getDaycareMonNicknames()
  self:ensureDaycare()
  local a = self.daycare[1] and self.daycare[1].mon
  if a then
    self:setStringVar(1, a.name or self:speciesName(a.species) or "")
    self:setStringVar(3, a.otName or self:playerName())
  end
  local b = self.daycare[2] and self.daycare[2].mon
  if b then
    self:setStringVar(2, b.name or self:speciesName(b.species) or "")
  end
end

function Game3:getSelectedDaycareMonNickname()
  local mon = self:selectedPartyMon()
  if not mon then
    self:setStringVar(1, "")
    return 0
  end
  self:setStringVar(1, mon.name or self:speciesName(mon.species) or "")
  return tonumber(mon.species) or 0
end

-- egg_hatch.c DaycareMonReceivedMail_: mail itemId != NONE, then TRUE if
-- the current nick or player name differs from the stored mail names.
function Game3:daycareMonReceivedMail()
  local slot = (self:varGet(0x8004) or 0) + 1
  self:ensureDaycare()
  local row = self.daycare[slot]
  if not (row and type(row.mail) == "table") then return 0 end
  if (tonumber(row.mail.itemId) or 0) == Game3.ITEM_NONE then return 0 end
  local mon = row.mon
  local nick = (mon and (mon.name or "")) or ""
  local mailNick = row.mail.nick or ""
  local mailOt = row.mail.otName or ""
  if nick ~= mailNick or self:playerName() ~= mailOt then
    self:setStringVar(1, nick)
    self:setStringVar(2, mailOt)
    self:setStringVar(3, mailNick)
    return 1
  end
  return 0
end

function Game3:depositToDaycare(index)
  self:ensureDaycare()
  if self:daycareCount() >= Game3.DAYCARE_SLOTS then
    return false, "The DAY CARE is full."
  end
  local ok, msg = self:canDeposit(index)
  if not ok then return false, msg end
  local mon = self.party[index]
  local slot
  for i = 1, Game3.DAYCARE_SLOTS do
    if not (self.daycare[i] and self.daycare[i].mon) then
      slot = i
      break
    end
  end
  if not slot then return false, "The DAY CARE is full." end
  local mail = self:takeMailFromMon(mon)
  self.daycare[slot] = { mon = self:cloneMon(mon), steps = 0, mail = mail }
  table.remove(self.party, index)
  return true, ("I'll raise your %s."):format(mon.name or "POKeMON")
end

function Game3:takeFromDaycare(slot)
  self:ensureDaycare()
  slot = tonumber(slot) or 1
  local row = self.daycare[slot]
  if not (row and row.mon) then
    return false, "There's no POKeMON here."
  end
  if #(self.party or {}) >= Game3.PARTY_MAX then
    return false, "Your party's full!"
  end
  local preview = self:daycarePreview(slot)
  local cost = preview and preview.cost or Game3.DAYCARE_BASE_COST
  if (self.money or 0) < cost then
    return false, "You don't have enough money."
  end
  local mon = row.mon
  self:applyDaycareExp(mon, row.steps or 0)
  self:giveMailToMon(mon, row.mail)
  self.money = (self.money or 0) - cost
  self.daycare[slot] = nil
  self:compactDaycare()
  self:addToParty(mon)
  return true, ("Here's your %s back! You paid $%d."):format(
    mon.name or "POKeMON", cost)
end

function Game3:openDaycare()
  local n = self:daycareCount()
  local canLeave = n < Game3.DAYCARE_SLOTS and #(self.party or {}) >= 2
  local canTake = n >= 1
  if canLeave and not canTake then
    self.field = { kind = "daycare_send", cursor = 0 }
    return true
  end
  if canTake and not canLeave then
    self.field = { kind = "daycare_take", cursor = 0 }
    return true
  end
  if canLeave and canTake then
    self.field = { kind = "daycare", cursor = 0 }
    return true
  end
  self.field = { kind = "talk", text = "You don't have enough POKeMON." }
  return true
end

function Game3:daycareTakeRows()
  local list = {}
  for i = 1, Game3.DAYCARE_SLOTS do
    local row = self:daycarePreview(i)
    if row then list[#list + 1] = row end
  end
  return list
end

function Game3:genderRatioFor(species)
  local row = self:speciesRow(species) or {}
  if type(row.genderRatio) == "number" then return row.genderRatio end
  if species == Game3.SPECIES_DITTO then return 0xFF end
  if species == 280 or species == 281 or species == 282 then return 31 end
  return 127
end

function Game3:monGender(mon)
  if not mon then return Game3.MON_GENDERLESS end
  local ratio = self:genderRatioFor(mon.species)
  if ratio == 0xFF then return Game3.MON_GENDERLESS end
  if ratio == 0xFE then return Game3.MON_FEMALE end
  if ratio == 0x00 then return Game3.MON_MALE end
  if ratio > ((mon.pid or 0) % 256) then return Game3.MON_FEMALE end
  return Game3.MON_MALE
end

function Game3:eggGroupsFor(species)
  local row = self:speciesRow(species) or {}
  local a, b = row.eggGroup1, row.eggGroup2
  if type(a) == "number" then return a, type(b) == "number" and b or a end
  if species == Game3.SPECIES_DITTO then
    return Game3.EGG_GROUP_DITTO, Game3.EGG_GROUP_DITTO
  end
  if species == 280 or species == 281 or species == 282 then return 5, 5 end
  if species == 290 or species == 291 or species == 292 then return 3, 3 end
  return Game3.EGG_GROUP_NONE, Game3.EGG_GROUP_NONE
end

function Game3:eggCyclesFor(species)
  local row = self:speciesRow(species) or {}
  if type(row.eggCycles) == "number" and row.eggCycles > 0 then
    return row.eggCycles
  end
  return 20
end

function Game3:daycareCompatibility()
  self:ensureDaycare()
  local a = self.daycare[1] and self.daycare[1].mon
  local b = self.daycare[2] and self.daycare[2].mon
  if not (a and b) then return 0 end
  local a1, a2 = self:eggGroupsFor(a.species)
  local b1, b2 = self:eggGroupsFor(b.species)
  if a1 == Game3.EGG_GROUP_UNDISCOVERED or b1 == Game3.EGG_GROUP_UNDISCOVERED then
    return 0
  end
  if a1 == Game3.EGG_GROUP_DITTO and b1 == Game3.EGG_GROUP_DITTO then
    return 0
  end
  local sameOt = (a.otId or 0) == (b.otId or 0)
  if a1 == Game3.EGG_GROUP_DITTO or b1 == Game3.EGG_GROUP_DITTO then
    return sameOt and 20 or 50
  end
  local ga, gb = self:monGender(a), self:monGender(b)
  if ga == gb or ga == Game3.MON_GENDERLESS or gb == Game3.MON_GENDERLESS then
    return 0
  end
  local overlap = a1 == b1 or a1 == b2 or a2 == b1 or a2 == b2
  if not overlap then return 0 end
  if a.species == b.species then
    return sameOt and 50 or 70
  end
  return sameOt and 20 or 50
end

function Game3:daycareCompatText()
  local score = self:daycareCompatibility()
  return Game3.DAYCARE_COMPAT_TEXT[score] or Game3.DAYCARE_COMPAT_TEXT[0]
end

function Game3:clearPendingEgg()
  self.daycarePending = nil
  if self.flags then self.flags[Game3.FLAG_PENDING_DAYCARE_EGG] = nil end
end

function Game3:maybePendingEgg()
  if (self.daycarePending or 0) ~= 0 then return end
  if self:daycareCount() < 2 then return end
  local row = self.daycare[2]
  if not (row and row.mon) then return end
  if ((row.steps or 0) % 256) ~= 255 then return end
  local score = self:daycareCompatibility()
  local roll = self:rand(65536) - 1
  if score > math.floor(roll * 100 / 65535) then
    self.daycarePending = self:rand(65534)
    self.flags = self.flags or {}
    self.flags[Game3.FLAG_PENDING_DAYCARE_EGG] = true
  end
end

function Game3:prevoOf(species)
  species = tonumber(species)
  if not species then return nil end
  local function scan(from, list)
    if type(list) ~= "table" then return nil end
    for i = 1, #list do
      if list[i] and list[i].target == species then return from end
    end
  end
  for from, list in pairs(Game3.FALLBACK_EVOS) do
    local hit = scan(from, list)
    if hit then return hit end
  end
  local pack = self.data.pokemon and self.data.pokemon.byIndex
  if type(pack) == "table" then
    for from, row in pairs(pack) do
      local hit = scan(from, row and row.evolutions)
      if hit then return hit end
    end
  end
end

function Game3:eggMotherSpecies()
  self:ensureDaycare()
  local a = self.daycare[1] and self.daycare[1].mon
  local b = self.daycare[2] and self.daycare[2].mon
  if not (a and b) then return nil end
  if a.species == Game3.SPECIES_DITTO then return b.species end
  if b.species == Game3.SPECIES_DITTO then return a.species end
  if self:monGender(a) == Game3.MON_FEMALE then return a.species end
  return b.species
end

function Game3:eggSpeciesFrom(species, pid)
  species = tonumber(species) or 0
  for _ = 1, 5 do
    local pre = self:prevoOf(species)
    if not pre then break end
    species = pre
  end
  if species == 360 then species = 202 end
  if species == 298 then species = 183 end
  pid = pid or 0
  if species == 29 and math.floor(pid / 32768) % 2 == 1 then species = 32 end
  if species == 314 and math.floor(pid / 32768) % 2 == 1 then species = 313 end
  return species
end

function Game3:inheritDaycareIvs(egg)
  self:ensureDaycare()
  local a = self.daycare[1] and self.daycare[1].mon
  local b = self.daycare[2] and self.daycare[2].mon
  if not (egg and a and b) then return end
  local keys = { "hp", "atk", "def", "spa", "spd", "spe" }
  for _ = 1, 3 do
    if #keys < 1 then break end
    local key = table.remove(keys, self:rand(#keys))
    local parent = self:rand(2) == 1 and a or b
    egg.ivs = egg.ivs or Game3.zeroIvs()
    egg.ivs[key] = (parent.ivs and parent.ivs[key]) or 0
  end
end

-- contest_util.c ScriptGiveEgg: CreateEgg(species, TRUE) then GiveMonToPlayer.
-- Do not remap Wynaut 360 through eggSpeciesFrom (that's daycare parents).
function Game3:giveEgg(species)
  species = tonumber(species)
  if not species or species < 1 then return 2 end
  local cycles = self:eggCyclesFor(species)
  local egg = self:makeMon(species, Game3.EGG_HATCH_LEVEL)
  egg.isEgg = true
  egg.name = "EGG"
  egg.hatchLeft = cycles
  egg.friendship = cycles
  egg.metLevel = 0
  egg.metLocation = Game3.EGG_MET_HOT_SPRINGS
  if self:addToParty(egg) then return 0 end
  if self:sendToPc(egg) then return 1 end
  return 2
end

function Game3:giveDaycareEgg()
  local pid = self.daycarePending or 0
  if pid == 0 then return false, "There's no EGG." end
  if #(self.party or {}) >= Game3.PARTY_MAX then
    return false, "Your party's full!"
  end
  local species = self:eggSpeciesFrom(self:eggMotherSpecies(), pid)
  if not species or species < 1 then return false, "There's no EGG." end
  local egg = self:makeMon(species, Game3.EGG_HATCH_LEVEL)
  egg.pid = pid
  egg.isEgg = true
  egg.name = "EGG"
  egg.hatchLeft = self:eggCyclesFor(species)
  self:inheritDaycareIvs(egg)
  self:setAbility(egg)
  self:recalcStats(egg)
  egg.hp = egg.maxHp
  self.party = self.party or {}
  self.party[#self.party + 1] = egg
  self:clearPendingEgg()
  return true, "Take good care of it."
end

function Game3:rejectDaycareEgg()
  self:clearPendingEgg()
  return true, "We'll keep it, then."
end

function Game3:hatchEgg(mon)
  if not (mon and mon.isEgg) then return false end
  -- AddHatchedMonToParty / CreatedHatchedMon. Stat 13 is incremented
  -- by the TakeStep caller, not here.
  mon.isEgg = nil
  mon.hatchLeft = nil
  mon.name = self:speciesName(mon.species)
  mon.friendship = Game3.HATCH_FRIENDSHIP
  mon.metLevel = 0
  mon.ball = Game3.ITEM_POKE_BALL
  self:setAbility(mon)
  self:recalcStats(mon)
  mon.hp = mon.maxHp
  self:markCaught(mon.species)
  return true
end

function Game3:scriptHatchMon()
  local idx = ((self.scriptVars and self.scriptVars[0x8004]) or 0) + 1
  return self:hatchEgg(self.party and self.party[idx])
end

-- egg_hatch.c EggHatch: LockPlayerFieldControls, AddHatchedMonToParty
-- inside the cinema, then the hatch line / nickname YES/NO.
function Game3:eggHatch()
  local idx = ((self.scriptVars and self.scriptVars[0x8004]) or 0) + 1
  local mon = self.party and self.party[idx]
  if not self:hatchEgg(mon) then return false end
  self:beginScriptWait()
  self.field = {
    kind = "egg_hatch",
    slot = idx,
    stage = "shake",
    left = Game3.EGG_HATCH_SHAKE_FRAMES,
    t = 0,
    name = mon.name,
  }
  self:playSong(Game3.MUS_EVOLUTION, true)
  return true
end

function Game3:stepEggHatch(dt)
  local f = self.field
  if not (f and f.kind == "egg_hatch") then return end
  if f.stage ~= "shake" then return end
  local frames = math.floor((dt or 0) * 60 + 0.0001)
  f.t = (f.t or 0) + frames
  f.left = (f.left or 0) - frames
  if f.left <= 0 then
    self:playFanfare(Game3.MUS_EVOLVED)
    self.field = {
      kind = "talk",
      text = ("%s hatched from the EGG!"):format(f.name or "POKeMON"),
      thenEggNick = true,
      slot = f.slot,
      name = f.name,
    }
  end
end

function Game3:openEggNickAsk()
  local f = self.field
  local name = (f and f.name) or "POKeMON"
  self.field = {
    kind = "egg_nick",
    text = ("Would you like to nickname the newly\nhatched %s?"):format(name),
    cursor = 0,
    slot = f and f.slot,
    name = name,
  }
  return true
end

function Game3:answerEggNick(yes)
  local f = self.field
  local slot = f and f.slot
  if yes and slot then
    self:setScriptVar(0x8004, slot - 1)
    self:openNickname()
    if self.field then self.field.fromHatch = true end
    return true
  end
  return self:finishEggHatchCinema()
end

function Game3:finishEggHatchCinema()
  self.field = nil
  self:playMapMusic()
  self:endScriptWait()
  return true
end

function Game3:tickEggCycles()
  local n = (self.eggCycleSteps or 0) + 1
  if n < Game3.EGG_CYCLE_STEPS then
    self.eggCycleSteps = n
    return
  end
  self.eggCycleSteps = 0
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and mon.isEgg then
      local left = (mon.hatchLeft or 1) - 1
      if left < 1 then
        -- field_control_avatar.c: IncrementGameStat then S_EggHatch
        -- ("Huh?" / special EggHatch / waitstate).
        self:incrementGameStat(Game3.GAME_STAT_HATCHED_EGGS)
        self:setScriptVar(0x8004, i - 1)
        self.field = {
          kind = "talk",
          text = "Huh?",
          thenEggHatch = true,
        }
        return
      else
        mon.hatchLeft = left
      end
    end
  end
end

function Game3:foundBlackGlasses()
  return (self.flags and self.flags[Game3.FLAG_HIDDEN_ITEM_BLACK_GLASSES]) and 1 or 0
end

function Game3:talkDaycareMan()
  if (self.daycarePending or 0) ~= 0 then
    self.field = {
      kind = "daycare_egg",
      cursor = 0,
      text = "Ah, it's you! Your POKeMON were having a good time, so we kept an EGG for you. Want it?",
    }
    return true
  end
  if self:daycareCount() >= 2 then
    self.field = { kind = "talk", text = self:daycareCompatText() }
    return true
  end
  self.field = {
    kind = "talk",
    text = "I'm the DAY CARE Man. See my wife if you'd like me to raise a POKeMON.",
  }
  return true
end

function Game3.contestKey(category)
  return Game3.CONTEST_KEYS[(category or 0) + 1] or "cool"
end

function Game3:contestCondition(mon, category)
  if not mon then return 0 end
  return tonumber(mon[Game3.contestKey(category)]) or 0
end

function Game3:contestRibbon(mon, category)
  if not (mon and mon.ribbons) then return 0 end
  return tonumber(mon.ribbons[Game3.contestKey(category)]) or 0
end

function Game3:canEnterContest(mon)
  if not mon or mon.isEgg then return false, "Eggs can't enter." end
  if type(mon.moves) ~= "table" or #mon.moves < 1 then
    return false, "It has no moves to appeal with."
  end
  return true
end

-- contest_2.c CanMonParticipateInContest: egg 3, fainted 4, then ribbon vs rank.
function Game3:canMonParticipateInContest(mon, category, rank)
  if not mon or mon.isEgg then return 3 end
  if (mon.hp or 0) == 0 then return 4 end
  category = category or 0
  rank = rank or 0
  if category < 0 or category > 4 then return 0 end
  local ribbon = self:contestRibbon(mon, category)
  if ribbon > rank then return 2 end
  if ribbon >= rank then return 1 end
  return 0
end

function Game3:syncContestMonsFromEngine(engine)
  local mons = {}
  if engine and engine.mons then
    for i = 0, 3 do
      mons[i + 1] = engine.mons[i]
    end
  end
  self.contestMons = mons
  self.contestPlayerMonIndex = (engine and engine.playerIndex)
    or Game3.CONTEST_PLAYER_MON_INDEX
  local points = {}
  local category = (engine and engine.category) or 0
  for i = 1, 4 do
    points[i] = mons[i] and Contest3.round1Points(mons[i], category) or 0
  end
  self.contestMonRound1Points = points
end

function Game3:initContestMons(category, rank)
  category = category or 0
  rank = rank or 0
  local mons = Contest3.prepareMons(
    self, self.contestMonIndex or 1, category, rank)
  if mons then
    self:syncContestMonsFromEngine({
      mons = mons, playerIndex = Contest3.PLAYER_INDEX, category = category,
    })
    return
  end
  self.contestMons = {}
  self.contestPlayerMonIndex = Game3.CONTEST_PLAYER_MON_INDEX
  self.contestMonRound1Points = { 0, 0, 0, 0 }
end

function Game3:setContestTrainerGfxIds(withPlayer)
  local mons = self.contestMons
  if type(mons) ~= "table" then
    self:initContestMons(
      (self.scriptVars and self.scriptVars[Game3.VAR_CONTEST_CATEGORY]) or 0,
      (self.scriptVars and self.scriptVars[Game3.VAR_CONTEST_RANK]) or 0)
    mons = self.contestMons
  end
  local n = withPlayer and 4 or 3
  for i = 1, n do
    local gfx = (mons[i] and mons[i].trainerGfxId) or 0
    self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + (i - 1), gfx)
  end
end

function Game3:contestMonAt(index)
  local mons = self.contestMons
  if type(mons) ~= "table" then return nil end
  return mons[(tonumber(index) or 0) + 1]
end

function Game3:contestWinnerIndex()
  local stand = self.contestFinalStandings
  if type(stand) == "table" then
    for i = 1, 4 do
      if (stand[i] or 0) == 0 then return i - 1 end
    end
  end
  if self.contest and self.contest.won then
    return self.contestPlayerMonIndex or Game3.CONTEST_PLAYER_MON_INDEX
  end
  return 0
end

function Game3:canEnterContestRank(mon, category, rank)
  rank = rank or 0
  if rank < 1 then return true end
  return self:contestRibbon(mon, category) >= rank
end

function Game3:contestRanksFor(mon, category)
  local list = { 0 }
  local have = self:contestRibbon(mon, category)
  for rank = 1, Game3.CONTEST_RANK_MASTER do
    if have >= rank then list[#list + 1] = rank end
  end
  return list
end

function Game3.contestCategoryForType(moveType)
  return Game3.CONTEST_TYPE_CATEGORY[moveType or 0] or Game3.CONTEST_CATEGORY_TOUGH
end

function Game3:contestAppealOf(move, category)
  if not move then return 0 end
  local cat = move.contestCategory
  if cat == nil then cat = Game3.contestCategoryForType(move.type) end
  local appeal = move.contestAppeal or Game3.CONTEST_DEFAULT_APPEAL
  if cat ~= category then appeal = math.floor(appeal / 2) end
  return appeal
end

function Game3:giveContestRibbon(mon, category, rank)
  if not mon then return false end
  mon.ribbons = mon.ribbons or {}
  local key = Game3.contestKey(category)
  local need = (rank or 0) + 1
  if (mon.ribbons[key] or 0) < need then mon.ribbons[key] = need end
  return true
end

function Game3:openContest()
  if #(self.party or {}) < 1 then
    self.field = { kind = "talk", text = "You don't have a POKeMON." }
    return true
  end
  self.field = { kind = "contest_cat", cursor = 0 }
  return true
end

function Game3:chooseContestMon()
  self:beginScriptWait()
  self.field = { kind = "contest_mon", cursor = 0, scripted = true }
  return true
end

function Game3:beginContest(monIndex, category, rank)
  local mon = self.party and self.party[monIndex]
  local ok, msg = self:canEnterContest(mon)
  if not ok then return false, msg end
  category = category or 0
  rank = rank or 0
  if not self:canEnterContestRank(mon, category, rank) then
    return false, "It hasn't won the previous rank yet."
  end
  self.contestMonIndex = monIndex
  local mons = nil
  if type(self.contestMons) == "table" and self.contestMons[1] then
    mons = {}
    for i = 0, 3 do mons[i] = self.contestMons[i + 1] end
    mons[3] = Contest3.createPlayerMon(self, monIndex) or mons[3]
  end
  local engine
  if mons and mons[0] and mons[3] then
    engine = Contest3.makeEngine(self, mons, monIndex, category, rank)
  else
    engine = Contest3.start(self, monIndex, category, rank)
  end
  if not engine then return false, "You can't enter." end
  self.contest = engine
  self:syncContestMonsFromEngine(engine)
  self:setScriptVar(Game3.VAR_CONTEST_CATEGORY, category)
  self:setScriptVar(Game3.VAR_CONTEST_RANK, rank)
  self:incrementGameStat(Game3.GAME_STAT_ENTERED_CONTEST)
  self.field = { kind = "contest_move", cursor = 0 }
  return true
end

function Game3:startContest()
  local idx = self.contestMonIndex
    or (((self.scriptVars and self.scriptVars[0x8004]) or 0) + 1)
  local category = (self.scriptVars and self.scriptVars[Game3.VAR_CONTEST_CATEGORY]) or 0
  local rank = (self.scriptVars and self.scriptVars[Game3.VAR_CONTEST_RANK]) or 0
  local ok, msg = self:beginContest(idx, category, rank)
  if not ok then
    self.field = { kind = "talk", text = msg or "You can't enter." }
    return false
  end
  self:beginScriptWait()
  if self.field then self.field.scripted = true end
  return true
end

function Game3:applyContestTurn(moveIndex)
  local c = self.contest
  if not c or not c.status then return false end
  if c.done then return false end
  Contest3.runRound(c, self, (moveIndex or 1) - 1)
  c.turn = c.appealNumber
  local player = c.playerIndex or 3
  c.player = (c.status[player] and c.status[player].pointTotal) or 0
  if c.done then
    self:finishContest()
  else
    c.phase = "select"
  end
  return true
end

function Game3:playContestMove(moveIndex)
  local c = self.contest
  if not c or not c.status or c.done then return false end
  Contest3.runRound(c, self, (moveIndex or 1) - 1)
  c.turn = c.appealNumber
  local player = c.playerIndex or 3
  c.player = (c.status[player] and c.status[player].pointTotal) or 0
  if c.texts and c.texts[1] then
    c.phase = "text"
    c.textAt = 1
  elseif c.done then
    self:finishContest()
  else
    c.phase = "select"
  end
  return true
end

function Game3:finishContest()
  local c = self.contest
  if not c then return end
  if c.status and not c.done then
    Contest3.calculateFinalScores(c, self)
  end
  local stand = c.finalStandings or {}
  local player = c.playerIndex or Game3.CONTEST_PLAYER_MON_INDEX
  local winner = 0
  for i = 0, 3 do
    if (stand[i] or 3) == 0 then
      winner = i
      break
    end
  end
  c.winner = winner
  c.won = (stand[player] or 3) == 0
  local conv = {}
  for i = 1, 4 do conv[i] = stand[i - 1] or 3 end
  self.contestFinalStandings = conv
  local totals = {}
  for i = 1, 4 do totals[i] = c.totalPoints and c.totalPoints[i - 1] or 0 end
  c.totals = totals
  if c.won then
    self:giveContestRibbon(self.party[c.monIndex], c.category, c.rank)
    self:incrementGameStat(Game3.GAME_STAT_WON_CONTEST)
  end
  c.phase = "done"
  self.field = {
    kind = "contest_results",
    scripted = self.field and self.field.scripted,
  }
end

function Game3:contestResultsText()
  local c = self.contest
  if not c then return "The CONTEST is over." end
  local cat = Game3.CONTEST_CAT_NAMES[(c.category or 0) + 1] or "COOL"
  local rank = Game3.CONTEST_RANK_NAMES[(c.rank or 0) + 1] or "NORMAL"
  local player = c.playerIndex or Game3.CONTEST_PLAYER_MON_INDEX
  local place = ((c.finalStandings and c.finalStandings[player]) or 3) + 1
  if c.won then
    return ("You won the %s %s CONTEST!"):format(rank, cat)
  end
  return ("You placed %d in the %s %s CONTEST."):format(place, rank, cat)
end

function Game3:showContestResults()
  self:beginScriptWait()
  self.field = {
    kind = "contest_results",
    scripted = true,
    text = self:contestResultsText(),
  }
  return true
end

function Game3:contestLobbyDest()
  local loc = self:varGet(Game3.VAR_CONTEST_LOCATION)
  return Game3.CONTEST_LOBBY_WARPS[loc] or Game3.CONTEST_LOBBY_WARPS[3]
end

function Game3:inContestHall()
  if self:varGet(Game3.VAR_LINK_CONTEST_ROOM_STATE) == 0 then
    return false
  end
  local map = self.map
  if not map then return false end
  local group, index = map.group, map.index
  if group == Game3.MAP_GROUP_INDOOR_DYNAMIC
      and index == Game3.MAP_NUM_LINK_CONTEST_ROOM1 then
    return true
  end
  return map.id == Game3.mapId(Game3.MAP_GROUP_INDOOR_DYNAMIC,
    Game3.MAP_NUM_LINK_CONTEST_ROOM1)
end

function Game3:warpBackFromContestHall()
  local dest = self:contestLobbyDest()
  if not dest then return false end
  self:setScriptVar(Game3.VAR_LINK_CONTEST_ROOM_STATE, 0)
  return self:scriptWarp(dest.group, dest.num, Game3.WARP_ID_NONE,
    dest.x, dest.y)
end

-- LinkContestRoom1 ON_FRAME hides the player and waitstates through
-- startcontest. A leftover move/wait field also eats START, so there
-- was no way out. START warps to the lobby 15FB64 would have used.
function Game3:tryAbortContestHall()
  if not self:inContestHall() then return false end
  self._scriptPause = nil
  self._scriptReturn = nil
  self._scriptSays = nil
  self._scriptLoaded = nil
  self._scriptDepth = nil
  self._pendingMapFrame = nil
  self.scriptWait = nil
  self.delayLeft = nil
  self.moveJobs = {}
  self.field = nil
  self.contest = nil
  self.invisible = nil
  return self:warpBackFromContestHall()
end

function Game3:showContestWinnerPainting(contestId)
  contestId = tonumber(contestId) or 0
  if contestId ~= 0 then
    self.contestPaintingId = contestId
  end
  self:beginScriptWait()
  self.field = {
    kind = "contest_winner",
    scripted = true,
    text = self:contestResultsText(),
  }
  return true
end

function Game3:pokeblockName(block)
  if type(block) ~= "table" then return "" end
  return Game3.POKEBLOCK_NAMES[block.color or 0] or "POKeBLOCK"
end

function Game3:ensurePokeblocks()
  if type(self.pokeblocks) ~= "table" then self.pokeblocks = {} end
  return self.pokeblocks
end

function Game3:getFirstFreePokeblockSlot()
  local blocks = self:ensurePokeblocks()
  for i = 1, Game3.POKEBLOCK_MAX do
    local b = blocks[i]
    if not b or (b.color or 0) == 0 then return i - 1 end
  end
  return -1
end

function Game3:givePokeblock(block)
  local slot = self:getFirstFreePokeblockSlot()
  if slot < 0 then return false end
  self.pokeblocks[slot + 1] = {
    color = block.color or 0,
    spicy = block.spicy or 0,
    dry = block.dry or 0,
    sweet = block.sweet or 0,
    bitter = block.bitter or 0,
    sour = block.sour or 0,
    feel = block.feel or 0,
  }
  return true
end

function Game3:berryFlavor(item)
  local berry = Game3.itemToBerryType(item)
  return Game3.BERRY_FLAVORS[berry] or { 10, 0, 0, 0, 0, 25 }
end

function Game3:pokeblockFromBerry(item, players)
  players = players or 1
  if players < 1 then players = 1 end
  local f = self:berryFlavor(item)
  local spicy, dry, sweet, bitter, sour = f[1], f[2], f[3], f[4], f[5]
  spicy = spicy - dry
  dry = dry - sweet
  sweet = sweet - bitter
  bitter = bitter - sour
  sour = sour - f[1]
  if spicy < 0 then spicy = 0 end
  if dry < 0 then dry = 0 end
  if sweet < 0 then sweet = 0 end
  if bitter < 0 then bitter = 0 end
  if sour < 0 then sour = 0 end
  local color = Game3.PBLOCK_CLR_RED
  local best, which = spicy, 1
  if dry > best then best, which = dry, 2 end
  if sweet > best then best, which = sweet, 3 end
  if bitter > best then best, which = bitter, 4 end
  if sour > best then best, which = sour, 5 end
  color = which
  local feel = math.floor((f[6] or 25) / players) - players
  if feel < 0 then feel = 0 end
  return {
    color = color, spicy = spicy, dry = dry, sweet = sweet,
    bitter = bitter, sour = sour, feel = feel,
  }
end

function Game3:doBerryBlending()
  local slots = self:bagSlotsIn(Game3.POCKET_BERRIES)
  if #slots < 1 then
    self.field = { kind = "talk", text = "You have no BERRIES." }
    return
  end
  self:beginScriptWait()
  self.field = {
    kind = "blender_berry",
    cursor = 0,
    slots = slots,
    scripted = true,
  }
end

function Game3:pickBlenderBerry(index)
  local f = self.field
  local slots = (f and f.slots) or self:bagSlotsIn(Game3.POCKET_BERRIES)
  local slot = slots[(tonumber(index) or 0) + 1]
  self.field = nil
  if not slot then
    self:endScriptWait()
    return
  end
  local item = slot.id
  self:takeItem(item, 1)
  local extra = (self.scriptVars and self.scriptVars[0x8004]) or 0
  local players = extra + 1
  local block = self:pokeblockFromBerry(item, players)
  self:givePokeblock(block)
  self:incrementGameStat(Game3.GAME_STAT_POKEBLOCKS)
  local rpm = 100
  self.berryBlenderRecords = self.berryBlenderRecords or { 0, 0, 0 }
  local recI = players
  if recI < 2 then recI = 2 end
  if recI > 4 then recI = 4 end
  local recSlot = recI - 1
  if rpm > (self.berryBlenderRecords[recSlot] or 0) then
    self.berryBlenderRecords[recSlot] = rpm
  end
  self:endScriptWait()
end

function Game3:showBerryBlenderRecordWindow()
  self.berryBlenderRecords = self.berryBlenderRecords or { 0, 0, 0 }
  local rec = self.berryBlenderRecords
  local function rpm(n)
    n = tonumber(n) or 0
    return ("%d.%02d RPM"):format(math.floor(n / 100), n % 100)
  end
  self:beginScriptWait()
  self.field = {
    kind = "talk",
    scripted = true,
    text = ("BERRY BLENDER max speed\n2P  %s\n3P  %s\n4P  %s"):format(
      rpm(rec[1]), rpm(rec[2]), rpm(rec[3])),
  }
end

function Game3:getPokeblockNameByMonNature()
  local mon = self:leadMon()
  local nature = Game3.natureIndex(mon and mon.personality)
  local flavor = Game3.NATURE_LIKED_FLAVOR[nature]
  if flavor == nil then
    return 0
  end
  self:setStringVar(1, Game3.POKEBLOCK_NAMES[flavor + 1] or "POKeBLOCK")
  return 1
end

function Game3:openPokeblockCaseOnFeeder()
  local blocks = self:ensurePokeblocks()
  local labels = {}
  local ids = {}
  for i = 1, Game3.POKEBLOCK_MAX do
    local b = blocks[i]
    if b and (b.color or 0) ~= 0 then
      labels[#labels + 1] = self:pokeblockName(b)
      ids[#ids + 1] = i
    end
  end
  labels[#labels + 1] = "CANCEL"
  self:beginScriptWait()
  self.field = {
    kind = "mauville_menu",
    labels = labels,
    cursor = 0,
    onPick = "pickPokeblockFeeder",
    feederIds = ids,
  }
end

function Game3:pickPokeblockFeeder(index, f)
  local ids = (f and f.feederIds) or {}
  if index >= #ids then
    self:setScriptVar(Gen3Script.VAR_RESULT, 0)
    return
  end
  local slot = ids[index + 1]
  local block = self.pokeblocks and self.pokeblocks[slot]
  self.safariFeeder = block
  self:setScriptVar(Gen3Script.VAR_RESULT, 1)
end

function Game3:safariZoneGetPokeblockNameInFeeder()
  local block = self.safariFeeder
  if type(block) ~= "table" or (block.color or 0) == 0 then
    return 0xFFFF
  end
  self:setStringVar(1, self:pokeblockName(block))
  return block.color or 0
end

function Game3:pokenavLines()
  local lines = {}
  for i = 1, #Game3.FLY_DESTINATIONS do
    local d = Game3.FLY_DESTINATIONS[i]
    if self.flags and self.flags[d.flag] then
      lines[#lines + 1] = d.name
    end
  end
  if #lines < 1 then
    lines[1] = "No towns recorded yet."
  end
  return lines
end

-- pokeruby sub_80FB758. 0 hides the name; 2/4 are Fly targets.
function Game3:regionMapKind(sec)
  sec = math.floor(tonumber(sec) or 0)
  if sec == Game3RegionMap.MAPSEC_NONE or sec < 0 then
    return Game3RegionMap.KIND_NONE
  end
  local flags = self.flags or {}
  if sec <= 15 then
    local dest = Game3.FLY_DESTINATIONS[sec + 1]
    if dest and flags[dest.flag] then return Game3RegionMap.KIND_FLY end
    return Game3RegionMap.KIND_TOWN
  end
  if sec == Game3RegionMap.MAPSEC_BATTLE_TOWER then
    if flags[Game3.FLAG_LANDMARK_BATTLE_TOWER] then
      return Game3RegionMap.KIND_SPECIAL
    end
    return Game3RegionMap.KIND_NONE
  end
  if sec == Game3RegionMap.MAPSEC_SOUTHERN_ISLAND then
    if flags[Game3.FLAG_LANDMARK_SOUTHERN_ISLAND] then
      return Game3RegionMap.KIND_LANDMARK
    end
    return Game3RegionMap.KIND_NONE
  end
  return Game3RegionMap.KIND_LANDMARK
end

function Game3:regionMapOpenState(scripted, flyMode)
  local sec = (self.map and self.map.regionMapSectionId) or 0
  local cx, cy = Game3.regionMapCursorForSection(sec)
  return {
    kind = flyMode and "fly" or "pokenav",
    cursor = 0,
    cursorX = cx,
    cursorY = cy,
    playerX = cx,
    playerY = cy,
    lines = self:pokenavLines(),
    list = flyMode and self:flyList() or nil,
    scripted = scripted,
    flyMode = flyMode and true or nil,
    zoomed = false,
    zooming = false,
    scrollX = 0,
    scrollY = 0,
    zoomPA = Game3RegionMap.ZOOM_PA_OUT,
    t = 0,
  }
end

function Game3:openPokeNav()
  self.field = self:regionMapOpenState(false)
  return true
end

function Game3:fieldShowRegionMap()
  self:beginScriptWait()
  self.field = self:regionMapOpenState(true)
end

function Game3:closeRegionMap()
  local f = self.field
  if f and f.scripted then
    self.field = nil
    self:endScriptWait()
  elseif f and (f.flyMode or f.kind == "fly") then
    self:closeField()
  else
    self:backToStart("POKeNAV")
  end
end

function Game3:beginRegionMapZoom(f)
  f.zooming = true
  f.zoomFrame = 0
  f.zoomFrom = f.zoomed and true or false
  if not f.zoomed then
    local tx, ty = Game3RegionMap.zoomScrollForCursor(
      f.cursorX or Game3RegionMap.CURSOR_X_MIN,
      f.cursorY or Game3RegionMap.CURSOR_Y_MIN)
    f.zoomFromSX, f.zoomFromSY = 0, 0
    f.zoomToSX, f.zoomToSY = tx, ty
    f.zoomFromPA = Game3RegionMap.ZOOM_PA_OUT
    f.zoomToPA = Game3RegionMap.ZOOM_PA_IN
    f.zoomCellX = f.cursorX
    f.zoomCellY = f.cursorY
  else
    f.zoomFromSX = f.scrollX or 0
    f.zoomFromSY = f.scrollY or 0
    f.zoomToSX, f.zoomToSY = 0, 0
    f.zoomFromPA = Game3RegionMap.ZOOM_PA_IN
    f.zoomToPA = Game3RegionMap.ZOOM_PA_OUT
    f.cursorX = f.zoomCellX or f.cursorX
    f.cursorY = f.zoomCellY or f.cursorY
  end
end

function Game3:stepRegionMapZoom(f)
  local n = Game3RegionMap.ZOOM_FRAMES
  f.zoomFrame = (f.zoomFrame or 0) + 1
  local t = f.zoomFrame / n
  if t > 1 then t = 1 end
  local fsx, fsy = f.zoomFromSX or 0, f.zoomFromSY or 0
  f.scrollX = fsx + (f.zoomToSX - fsx) * t
  f.scrollY = fsy + (f.zoomToSY - fsy) * t
  local fpa = f.zoomFromPA or 256
  f.zoomPA = fpa + ((f.zoomToPA or 128) - fpa) * t
  if f.zoomFrame < n then return end
  f.zooming = false
  f.zoomed = not f.zoomFrom
  f.scrollX = f.zoomToSX
  f.scrollY = f.zoomToSY
  f.zoomPA = f.zoomToPA
  if f.zoomed then
    f.zoomCellX = f.cursorX
    f.zoomCellY = f.cursorY
  else
    f.scrollX, f.scrollY = 0, 0
    f.zoomPA = Game3RegionMap.ZOOM_PA_OUT
  end
end

function Game3:flyDestForSection(sec, area)
  sec = math.floor(tonumber(sec) or 0)
  if sec == Game3RegionMap.MAPSEC_BATTLE_TOWER then
    return Game3.FLY_BATTLE_TOWER
  end
  if sec < 0 or sec > 15 then return nil end
  local dest = Game3.FLY_DESTINATIONS[sec + 1]
  if not dest then return nil end
  if sec == Game3RegionMap.MAPSEC_EVER_GRANDE
      and self.flags and self.flags[Game3.FLAG_SYS_POKEMON_LEAGUE_FLY]
      and (tonumber(area) or 0) == 0 then
    return {
      mapId = dest.mapId, name = dest.name, flag = dest.flag,
      mapsec = dest.mapsec, healId = Game3.HEAL_EVER_GRANDE_LEAGUE,
    }
  end
  return dest
end

function Game3:stepRegionMap(f)
  f.t = (f.t or 0) + 1
  if f.zooming then
    self:stepRegionMapZoom(f)
    return
  end
  local xmin = Game3RegionMap.CURSOR_X_MIN
  local ymin = Game3RegionMap.CURSOR_Y_MIN
  local xmax = xmin + Game3RegionMap.WIDTH - 1
  local ymax = ymin + Game3RegionMap.HEIGHT - 1
  local fly = f.flyMode or f.kind == "fly"
  if f.zoomed then
    local dx, dy = 0, 0
    if Input:isDown("up") then dy = -1
    elseif Input:isDown("down") then dy = 1 end
    if Input:isDown("left") then dx = -1
    elseif Input:isDown("right") then dx = 1 end
    if dx ~= 0 or dy ~= 0 then
      local sx = (f.scrollX or 0) + dx
      local sy = (f.scrollY or 0) + dy
      if sx < Game3RegionMap.SCROLL_X_MIN then sx = Game3RegionMap.SCROLL_X_MIN end
      if sx > Game3RegionMap.SCROLL_X_MAX then sx = Game3RegionMap.SCROLL_X_MAX end
      if sy < Game3RegionMap.SCROLL_Y_MIN then sy = Game3RegionMap.SCROLL_Y_MIN end
      if sy > Game3RegionMap.SCROLL_Y_MAX then sy = Game3RegionMap.SCROLL_Y_MAX end
      f.scrollX, f.scrollY = sx, sy
      f.zoomPan = (f.zoomPan or 0) + 1
      if f.zoomPan >= 8 then
        f.zoomPan = 0
        local cx, cy = Game3RegionMap.zoomCellFromScroll(sx, sy)
        f.cursorX, f.cursorY = cx, cy
        f.zoomCellX, f.zoomCellY = cx, cy
      end
    else
      f.zoomPan = 0
    end
  else
    if Input:wasPressed("down") then
      f.cursorY = math.min((f.cursorY or ymin) + 1, ymax)
    elseif Input:wasPressed("up") then
      f.cursorY = math.max((f.cursorY or ymin) - 1, ymin)
    elseif Input:wasPressed("left") then
      f.cursorX = math.max((f.cursorX or xmin) - 1, xmin)
    elseif Input:wasPressed("right") then
      f.cursorX = math.min((f.cursorX or xmin) + 1, xmax)
    end
  end
  if Input:wasPressed("a") then
    if fly then
      local cx = f.cursorX or xmin
      local cy = f.cursorY or ymin
      local sec = Game3.regionMapSectionAt(cx, cy)
      local kind = self:regionMapKind(sec)
      if kind == Game3RegionMap.KIND_FLY or kind == Game3RegionMap.KIND_SPECIAL then
        local dest = self:flyDestForSection(sec, Game3RegionMap.areaIndex(cx, cy))
        if dest then
          local _, msg = self:flyTo(dest)
          self.field = { kind = "talk", text = msg }
        end
      end
    elseif f.scripted then
      self:closeRegionMap()
    else
      self:beginRegionMapZoom(f)
    end
  elseif Input:wasPressed("b") or Input:wasPressed("start") then
    self:closeRegionMap()
  end
end

function Game3:pcAccessLabels()
  local labels = {}
  if self.flags and self.flags[Game3.FLAG_SYS_PC_LANETTE] then
    labels[1] = "LANETTE'S PC"
  else
    labels[1] = "SOMEONE'S PC"
  end
  labels[2] = "PLAYER'S PC"
  if self.flags and self.flags[Game3.FLAG_SYS_GAME_CLEAR] then
    labels[3] = "HALL OF FAME"
    labels[4] = "LOG OFF"
  else
    labels[3] = "LOG OFF"
  end
  return labels
end

function Game3:scriptMenuCreatePCMultichoice()
  self:beginScriptWait()
  self.field = {
    kind = "mauville_menu",
    labels = self:pcAccessLabels(),
    cursor = 0,
    onPick = "pickPcAccess",
    bPressed = Game3.MULTI_B_PRESSED,
  }
end

function Game3:pickPcAccess(index)
  self:setScriptVar(Gen3Script.VAR_RESULT, tonumber(index) or 0)
end

function Game3:openPlayerPc(bedroom)
  local labels = { "ITEM STORAGE", "MAILBOX" }
  if bedroom then labels[#labels + 1] = "DECORATION" end
  labels[#labels + 1] = "TURN OFF"
  self:beginScriptWait()
  self:fadeInFromBlack()
  self.field = {
    kind = "player_pc",
    labels = labels,
    cursor = 0,
    bedroom = bedroom and true or nil,
    scripted = true,
  }
end

function Game3:pickPlayerPc(index)
  local f = self.field
  local labels = (f and f.labels) or { "TURN OFF" }
  local n = #labels
  if index >= n - 1 then
    self.field = nil
    self:endScriptWait()
    return
  end
  if index == 0 then
    f.note = "No items are stored."
    return
  end
  if index == 1 then
    f.note = "There's no MAIL here."
    return
  end
  if f and f.bedroom and index == 2 then
    f.note = "Decorations go in a SECRET BASE."
  end
end

function Game3:showPokemonStorageSystem()
  self:beginScriptWait()
  self:openPc()
  if self.field then self.field.scripted = true end
end

function Game3:setScriptVar(id, value)
  self.scriptVars = self.scriptVars or {}
  self.scriptVars[id] = value
end

function Game3:setStringVar(slot, text)
  self.stringVars = self.stringVars or {}
  if text == nil then text = "" end
  -- LuaJIT string.gsub replacements must be strings. A numeric buffer
  -- (size records, stats) used to traceback mid-dialogue and freeze.
  self.stringVars[tonumber(slot) or 1] = tostring(text)
  return true
end

function Game3.nameKeys()
  local out = {}
  local letters = Game3.NAME_LETTERS
  for i = 1, #letters do out[i] = letters:sub(i, i) end
  out[#out + 1] = "DEL"
  out[#out + 1] = "END"
  return out
end

function Game3:bufferLeadMonSpecies(slot)
  local dest = (tonumber(slot) or 0) + 1
  local mon = self.party and self.party[1]
  local name = ""
  if mon then name = self:speciesName(mon.species) end
  return self:setStringVar(dest, name)
end

function Game3:bufferPartyMonNick(slot, partyIndex)
  local dest = (tonumber(slot) or 0) + 1
  local mon = self.party and self.party[(tonumber(partyIndex) or 0) + 1]
  local name = ""
  if mon then name = mon.name or self:speciesName(mon.species) or "" end
  return self:setStringVar(dest, name)
end

function Game3:moveName(id)
  id = tonumber(id) or 0
  local spec = self.data and self.data.moves and self.data.moves.byId
    and self.data.moves.byId[id]
  if spec and spec.name and spec.name ~= "" then return spec.name end
  local rows = Game3.PARTY_FIELD_MOVES
  for i = 1, #rows do
    if rows[i].id == id then return rows[i].name end
  end
  return ("MOVE %d"):format(id)
end

function Game3:bufferMoveName(slot, move)
  return self:setStringVar((tonumber(slot) or 0) + 1, self:moveName(move))
end

function Game3:openNickname(opts)
  opts = opts or {}
  local mon = opts.mon
  local idx = opts.slot
  if not idx then
    idx = ((self.scriptVars and self.scriptVars[Gen3Script.VAR_0x8004]) or 0) + 1
  end
  if not mon then
    mon = self.party and self.party[idx]
  end
  if not mon then return false end
  -- ChangePokemonNickname copies MON_DATA_NICKNAME to gStringVar3
  -- (old) and gStringVar2 (naming buffer).
  local nick = mon.name or ""
  self:setStringVar(3, nick)
  self:setStringVar(2, nick)
  self:beginScriptWait()
  self.field = {
    kind = "nickname",
    scripted = opts.scripted ~= false,
    slot = idx,
    mon = mon,
    cursor = 0,
    name = nick:sub(1, Game3.NICKNAME_LEN),
    keys = Game3.nameKeys(),
    fromCatch = opts.fromCatch or nil,
    fromHatch = opts.fromHatch or nil,
  }
  return true
end

function Game3:finishNickname()
  local f = self.field
  if f and f.nameBox then
    local name = (f.name or ""):sub(1, Game3.BOX_NAME_LEN)
    if name == "" then name = self:defaultBoxName(f.box or 1) end
    self:ensurePc()
    self.boxNames[f.box or 1] = name
    self.field = f.fromPc
    if self.field and self.field.kind == "pc" then self:pcRefreshMsg() end
    return true
  end
  local slot = (f and f.slot) or 1
  local mon = (f and f.mon) or (self.party and self.party[slot])
  local name = (f and f.name) or ""
  if mon and name ~= "" then
    mon.name = name:sub(1, Game3.NICKNAME_LEN)
  end
  local scripted = f and f.scripted
  local fromHatch = f and f.fromHatch
  self.field = nil
  if fromHatch then
    self:playMapMusic()
    return self:endScriptWait()
  end
  if scripted then return self:endScriptWait() end
  return true
end

function Game3:expandScriptText(text)
  if type(text) ~= "string" then return text end
  local vars = self.stringVars or {}
  local function lit(s)
    if s == nil then return "" end
    return tostring(s)
  end
  -- Function replacements so a name with "%" cannot traceback in gsub.
  text = text:gsub("{PLAYER}", function() return lit(self:playerName()) end)
  text = text:gsub("{RIVAL}", function() return lit(self:rivalName()) end)
  text = text:gsub("{KUN}", "")
  text = text:gsub("{STR_VAR_1}", function() return lit(vars[1]) end)
  text = text:gsub("{STR_VAR_2}", function() return lit(vars[2]) end)
  text = text:gsub("{STR_VAR_3}", function() return lit(vars[3]) end)
  text = text:gsub("{POKEBLOCK}", "POKeBLOCK")
  -- decodeText used to drop GBA \p (0xFB), so cached IR glued the next
  -- sentence on: "TRAINER!You" / "says.Do". \p is a page/line break.
  text = text:gsub("([.!?])(%u)", "%1\n%2")
  return text
end

function Game3:varGet(id)
  id = tonumber(id) or 0
  if id == Game3.VAR_FACING then
    local stored = Gen3Script.varGet(self.scriptVars, id)
    if stored ~= 0 then return stored end
    return Game3.dirId(self.facing)
  end
  return Gen3Script.varGet(self.scriptVars, id)
end

function Game3:runMapOps(ops, present)
  if type(ops) ~= "table" or #ops < 1 then return false end
  if present then return self:runNpcScript(ops) end
  Gen3Script.run(self, ops)
  return true
end

function Game3:runMapScript(key)
  local ms = self.map and self.map.mapScripts
  return self:runMapOps(ms and ms[key], false)
end

function Game3:runMapScriptTable(key, present)
  local ms = self.map and self.map.mapScripts
  local rows = ms and ms[key]
  if type(rows) ~= "table" then return false end
  for i = 1, #rows do
    local row = rows[i]
    if row and self:varGet(row.var) == self:varGet(row.value) then
      return self:runMapOps(row.script, present)
    end
  end
  return false
end

function Game3:tryMapFrameScript()
  if self.field then return false end
  return self:runMapScriptTable("onFrame", true)
end

-- field_weather_effects.c TranslateWeatherNum / SetSav1Weather / DoCurrentWeather.
function Game3:translateWeatherNum(weather)
  weather = tonumber(weather) or 0
  local stage = (self.weatherCycleStage or 0) % 4
  if weather == Game3.OW_WEATHER_ROUTE119_CYCLE then
    return Game3.WEATHER_CYCLE_119[stage + 1]
  end
  if weather == Game3.OW_WEATHER_ROUTE123_CYCLE then
    return Game3.WEATHER_CYCLE_123[stage + 1]
  end
  if weather >= Game3.OW_WEATHER_NONE
      and weather <= Game3.OW_WEATHER_BUBBLES then
    return weather
  end
  return Game3.OW_WEATHER_NONE
end

function Game3:updateRainCounter(newWeather, oldWeather)
  newWeather = tonumber(newWeather) or 0
  oldWeather = tonumber(oldWeather) or 0
  if newWeather ~= oldWeather
      and (newWeather == Game3.OW_WEATHER_RAIN_LIGHT
        or newWeather == Game3.OW_WEATHER_RAIN_MED) then
    self:incrementGameStat(Game3.GAME_STAT_GOT_RAINED_ON)
  end
end

function Game3:setSav1Weather(weather)
  local old = self.sav1Weather or 0
  local n = self:translateWeatherNum(weather)
  self.sav1Weather = n
  self:updateRainCounter(n, old)
  return n
end

-- field_specials.c SetRoute119Weather / SetRoute123Weather. Header is
-- WEATHER_SUNNY; the rain cycle only applies when lastUsedWarp is not
-- outdoor (leaving Weather Institute / a house). Do not beginScriptWait.
function Game3:setRoute119Weather()
  if not Game3.isOutdoorMapType(self:lastUsedWarpMapType()) then
    return self:setSav1Weather(Game3.OW_WEATHER_ROUTE119_CYCLE)
  end
  return self.sav1Weather or 0
end

function Game3:setRoute123Weather()
  if not Game3.isOutdoorMapType(self:lastUsedWarpMapType()) then
    return self:setSav1Weather(Game3.OW_WEATHER_ROUTE123_CYCLE)
  end
  return self.sav1Weather or 0
end

function Game3:setSav1WeatherFromCurrMapHeader()
  local w = self.map and self.map.weather or 0
  return self:setSav1Weather(w)
end

function Game3:resetWeather()
  return self:setSav1WeatherFromCurrMapHeader()
end

function Game3:doCurrentWeather()
  self.currWeather = self.sav1Weather or 0
  return self.currWeather
end

function Game3:getCurrentWeather()
  return self.currWeather or 0
end

function Game3:doCoordEventWeather(id)
  local w = Game3.COORD_EVENT_WEATHER[tonumber(id) or 0]
  if w == nil then return 0 end
  self:setSav1Weather(w)
  return self:doCurrentWeather()
end

function Game3.overworldWeatherStartText(ow)
  ow = tonumber(ow) or 0
  if ow == Game3.OW_WEATHER_SANDSTORM then
    return "A sandstorm is raging."
  end
  if ow == Game3.OW_WEATHER_DROUGHT then
    return "The sunlight is strong."
  end
  if ow == Game3.OW_WEATHER_RAIN_LIGHT
      or ow == Game3.OW_WEATHER_RAIN_MED
      or ow == Game3.OW_WEATHER_RAIN_HEAVY then
    return "It is raining."
  end
  return nil
end

function Game3:applyOverworldBattleWeather()
  local b = self.battle
  if not b then return false end
  local ow = self:getCurrentWeather()
  local kind
  if ow == Game3.OW_WEATHER_RAIN_LIGHT
      or ow == Game3.OW_WEATHER_RAIN_MED
      or ow == Game3.OW_WEATHER_RAIN_HEAVY then
    kind = Game3.WEATHER_RAIN
  elseif ow == Game3.OW_WEATHER_SANDSTORM then
    kind = Game3.WEATHER_SAND
  elseif ow == Game3.OW_WEATHER_DROUGHT then
    kind = Game3.WEATHER_SUN
  else
    return false
  end
  b.weather = kind
  b.weatherTurns = nil
  b.owWeatherLine = Game3.overworldWeatherStartText(ow)
  return true
end

function Game3:coordEventWouldRun(x, y)
  local events = self.map and self.map.coordEvents
  if type(events) ~= "table" then return false end
  x, y = tonumber(x) or self.playerX, tonumber(y) or self.playerY
  for i = 1, #events do
    local ev = events[i]
    if ev and ev.x == x and ev.y == y and ev.script
        and (ev.trigger or 0) ~= 0
        and (self:varGet(ev.trigger) % 256) == ((ev.index or 0) % 256) then
      return true
    end
  end
  return false
end

function Game3:tryCoordEvent(x, y)
  local events = self.map and self.map.coordEvents
  if type(events) ~= "table" then return false end
  x, y = tonumber(x) or self.playerX, tonumber(y) or self.playerY
  for i = 1, #events do
    local ev = events[i]
    if ev and ev.x == x and ev.y == y then
      if not ev.script then
        -- coord_weather_event: script NULL, trigger is COORD_EVENT_WEATHER_*.
        self:doCoordEventWeather(ev.trigger)
      elseif (ev.trigger or 0) == 0 then
        self:runMapOps(ev.script, false)
      elseif (self:varGet(ev.trigger) % 256) == ((ev.index or 0) % 256) then
        return self:runMapOps(ev.script, true)
      end
    end
  end
  return false
end

function Game3:markFlyVisited(map)
  local dest = Game3.flyDestFor(map or self.map)
  if not dest then return false end
  self.flags = self.flags or {}
  self.flags[dest.flag] = true
  return true
end

function Game3:flyList()
  local out = {}
  local pack = ((self.data or {}).maps or {}).maps or {}
  for i = 1, #Game3.FLY_DESTINATIONS do
    local d = Game3.FLY_DESTINATIONS[i]
    if self.flags and self.flags[d.flag] and pack[d.mapId] then
      out[#out + 1] = d
    end
  end
  local tower = Game3.FLY_BATTLE_TOWER
  if self.flags and self.flags[tower.flag] and pack[tower.mapId] then
    out[#out + 1] = tower
  end
  return out
end

function Game3:useFly()
  if not self:partyKnowsMove(Game3.MOVE_FLY) then
    return false, "No one in your party knows FLY."
  end
  if not self:hasBadge(6) then
    return false, "You need the FEATHER BADGE to use FLY."
  end
  if not Game3.canFlyFrom(self.map) then
    return false, "You can't use that here!"
  end
  local list = self:flyList()
  if #list < 1 then
    return false, "You can't use that here!"
  end
  self.field = self:regionMapOpenState(false, true)
  return true, "Where do you want to FLY?"
end

function Game3:flyHealId(dest)
  if type(dest) ~= "table" then return nil end
  if dest.mapsec == 0 and self:isFemale() then
    return Game3.HEAL_LITTLEROOT_TOWN_MAY
  end
  return dest.healId
end

function Game3:flyTo(dest)
  if type(dest) == "string" then
    dest = Game3.FLY_BY_ID[dest]
  elseif type(dest) == "number" then
    dest = Game3.FLY_DESTINATIONS[dest]
  end
  if type(dest) ~= "table" then
    return false, "You can't use that here!"
  end
  local pack = ((self.data or {}).maps or {}).maps or {}
  local map = pack[dest.mapId]
  local healId = self:flyHealId(dest)
  local loc = healId and Game3.HEAL_LOCATIONS[healId]
  if loc then
    local healMap = self:lookupMap(loc.group, loc.num)
    if healMap then map = healMap end
  end
  if not map then
    return false, "You can't use that here!"
  end
  local spawn = map.spawn or {}
  local x, y = spawn.x or 0, spawn.y or 0
  if loc and loc.x ~= nil and loc.y ~= nil
      and loc.x >= 0 and loc.y >= 0
      and loc.x < (map.width or 0) and loc.y < (map.height or 0) then
    x, y = loc.x, loc.y
  end
  self.surfing = nil
  self.climbing = nil
  self:enterMap(map, x, y, false)
  return true, ("Flew to %s!"):format(dest.name or dest.mapId)
end

function Game3:tryLearnLevelMoves(mon)
  local texts = {}
  local row = self:speciesRow(mon.species)
  local learn = row and row.learnset or {}
  for i = 1, #learn do
    local e = learn[i]
    if e and e.level == mon.level and e.move and not self:knowsMove(mon, e.move) then
      local slot = self:copyMove(e.move)
      mon.moves = mon.moves or {}
      if #mon.moves >= 4 then
        self:queueLearnMove(mon, e.move)
      else
        mon.moves[#mon.moves + 1] = slot
        texts[#texts + 1] = ("%s learned %s!"):format(mon.name, slot.name)
      end
    end
  end
  return texts
end

function Game3:queueLearnMove(mon, moveId)
  self.pendingLearn = self.pendingLearn or {}
  self.pendingLearn[#self.pendingLearn + 1] = { mon = mon, move = moveId }
end

function Game3:learnMoveName(moveId)
  local slot = self:copyMove(moveId)
  return (slot and slot.name) or "MOVE"
end

function Game3:startPendingLearn()
  if self.learnMove then return true end
  local q = self.pendingLearn
  if not (q and q[1]) then return false end
  local e = table.remove(q, 1)
  local mon = e.mon
  local moveName = self:learnMoveName(e.move)
  local name = (mon and mon.name) or "POKeMON"
  self.learnMove = { mon = mon, move = e.move, name = moveName }
  local texts = {
    ("%s is trying to learn %s."):format(name, moveName),
    ("But, %s can't learn more than four moves."):format(name),
    ("Delete a move to make room for %s?"):format(moveName),
  }
  if self.phase == "battle" and self.battle then
    local b = self.battle
    b.kind = "text"
    b.queue = texts
    b.qi = 1
    b.text = texts[1]
    b.printSrc = nil
    b.textPage = 0
    b.thenLearnAsk = true
  else
    self.field = {
      kind = "talk", text = texts[1], queue = texts, qi = 1, thenLearnAsk = true,
    }
  end
  return true
end

function Game3:openLearnYesNo()
  local lm = self.learnMove
  local text = ("Delete a move to make room for %s?"):format(
    (lm and lm.name) or "MOVE")
  if self.phase == "battle" and self.battle then
    local b = self.battle
    b.kind = "learn_yesno"
    b.text = text
    b.cursor = 0
    b.queue = nil
    b.thenLearnAsk = nil
    b.printSrc = nil
    b.textPage = 0
  else
    self.field = { kind = "learn_yesno", text = text, cursor = 0 }
  end
end

function Game3:openLearnStop()
  local lm = self.learnMove
  local text = ("Stop learning %s?"):format((lm and lm.name) or "MOVE")
  if self.phase == "battle" and self.battle then
    local b = self.battle
    b.kind = "learn_stop"
    b.text = text
    b.cursor = 0
    b.printSrc = nil
    b.textPage = 0
  else
    self.field = { kind = "learn_stop", text = text, cursor = 0 }
  end
end

function Game3:openLearnForget()
  local lm = self.learnMove
  local mon = lm and lm.mon
  if self.phase == "battle" and self.battle then
    local b = self.battle
    b.kind = "learn_forget"
    b.cursor = 0
    b.text = ("Which move should be forgotten?")
    b.printSrc = nil
    b.textPage = 0
  else
    self.field = {
      kind = "learn_forget", cursor = 0, mon = mon,
      text = "Which move should be forgotten?",
    }
  end
end

function Game3:showLearnMessage(text, thenKind)
  self:showLearnMessages({ text }, thenKind)
end

function Game3:showLearnMessages(texts, thenKind)
  if type(texts) ~= "table" or #texts < 1 then
    texts = { tostring(texts or "") }
  end
  if self.phase == "battle" and self.battle then
    local b = self.battle
    b.kind = "learn_msg"
    b.queue = texts
    b.qi = 1
    b.text = texts[1]
    b.thenLearn = thenKind
    b.printSrc = nil
    b.textPage = 0
  else
    self.field = {
      kind = "talk", text = texts[1], queue = texts, qi = 1, thenLearn = thenKind,
    }
  end
end

function Game3:afterLearnPrompt()
  if self.tutorWait then
    self:finishTutorTeach(true)
    return
  end
  self.learnMove = nil
  if self:startPendingLearn() then return end
  if self.phase == "battle" and self.battle then
    self:afterBattleMessages()
  else
    self:finishPostBattleScenes()
  end
end

function Game3:answerLearnYesNo(yes)
  if yes then
    self:openLearnForget()
  else
    self:openLearnStop()
  end
end

function Game3:answerLearnStop(yes)
  local lm = self.learnMove
  if yes then
    -- move_tutor_menu.c state 27: stop learning returns to the list,
    -- not 0x8004 = 0 (that is EXIT / B give-up).
    if self.tutorWait then
      self.learnMove = nil
      self:displayMoveTutorMenu()
      return
    end
    local mon = lm and lm.mon
    local name = (mon and mon.name) or "POKeMON"
    local moveName = (lm and lm.name) or "MOVE"
    self:showLearnMessage(
      ("%s did not learn %s."):format(name, moveName), "done")
  else
    self:openLearnYesNo()
  end
end

function Game3:chooseLearnForget(slot)
  local lm = self.learnMove
  local mon = lm and lm.mon
  local moves = mon and mon.moves or {}
  slot = tonumber(slot) or 0
  if slot < 1 or slot > #moves then
    self:openLearnStop()
    return false
  end
  local old = moves[slot]
  if Game3.isHmMove(old and old.id) then
    self:showLearnMessage("HM moves can't be forgotten now.", "forget")
    return false
  end
  local learned = self:copyMove(lm.move)
  local oldName = (old and old.name) or "MOVE"
  local name = mon.name or "POKeMON"
  moves[slot] = learned
  self:showLearnMessages({
    ("%s forgot %s."):format(name, oldName),
    ("%s learned %s!"):format(name, learned.name or lm.name),
  }, "done")
  return true
end

function Game3:finishLearnMessage()
  local thenKind = nil
  if self.phase == "battle" and self.battle then
    thenKind = self.battle.thenLearn
    self.battle.thenLearn = nil
  elseif self.field then
    thenKind = self.field.thenLearn
  end
  if thenKind == "forget" then
    self:openLearnForget()
  else
    self:afterLearnPrompt()
  end
end

function Game3:evolutionsFor(species)
  local row = self:speciesRow(species)
  if row and type(row.evolutions) == "table" and #row.evolutions > 0 then
    return row.evolutions
  end
  return Game3.FALLBACK_EVOS[species]
end

-- pokemon_3.c GetEvolutionTargetSpecies type 1. Everstone blocks
-- (type != 3). EVO_TRADE_ITEM zeros the hold item on a match.
function Game3:checkTradeEvolution(mon)
  if not mon or mon.isEgg then return nil end
  if self:holdEffectOf(mon) == Game3.HOLD_EFFECT_PREVENT_EVOLVE then
    return nil
  end
  local list = self:evolutionsFor(mon.species)
  if type(list) ~= "table" then return nil end
  local target
  local held = tonumber(mon.item) or 0
  for i = 1, #list do
    local e = list[i]
    if e and e.target then
      if e.method == Game3.EVO_TRADE then
        target = e.target
      elseif e.method == Game3.EVO_TRADE_ITEM and (e.param or 0) == held then
        mon.item = 0
        held = 0
        target = e.target
      end
    end
  end
  return target
end

function Game3:checkEvolution(mon)
  local list = self:evolutionsFor(mon.species)
  if type(list) ~= "table" then return nil end
  -- GetEvolutionTargetSpecies type 0: Everstone blocks level-up evo.
  if self:holdEffectOf(mon) == Game3.HOLD_EFFECT_PREVENT_EVOLVE then
    return nil
  end
  local level = mon.level or 1
  local upper = math.floor((mon.pid or 0) / 65536)
  for i = 1, #list do
    local e = list[i]
    local method, param, target = e.method, e.param or 0, e.target
    if not target then
    elseif method == Game3.EVO_LEVEL and level >= param then
      return target
    elseif method == Game3.EVO_LEVEL_ATK_GT_DEF and level >= param
        and (mon.atk or 0) > (mon.def or 0) then
      return target
    elseif method == Game3.EVO_LEVEL_ATK_EQ_DEF and level >= param
        and (mon.atk or 0) == (mon.def or 0) then
      return target
    elseif method == Game3.EVO_LEVEL_ATK_LT_DEF and level >= param
        and (mon.atk or 0) < (mon.def or 0) then
      return target
    elseif method == Game3.EVO_LEVEL_SILCOON and level >= param
        and (upper % 10) <= 4 then
      return target
    elseif method == Game3.EVO_LEVEL_CASCOON and level >= param
        and (upper % 10) > 4 then
      return target
    elseif method == Game3.EVO_LEVEL_NINJASK and level >= param then
      return target
    end
  end
end

-- pokemon_3.c EvolutionRenameMon: keep a nickname; species-name
-- nicknames become the new species name.
function Game3:evolutionRenameMon(mon, oldSpecies, newSpecies)
  if not mon then return end
  if (mon.name or "") == (self:speciesName(oldSpecies) or "") then
    mon.name = self:speciesName(newSpecies)
  end
end

function Game3:applyEvolution(mon, target)
  local oldName = mon.name
  local from = mon.species
  self:evolutionRenameMon(mon, from, target)
  mon.species = target
  local row = self:speciesRow(target) or {}
  if row.type1 then mon.type1 = row.type1 end
  if row.type2 or row.type1 then mon.type2 = row.type2 or row.type1 end
  if row.ability1 or row.ability2 then self:setAbility(mon) end
  if row.catchRate then mon.catchRate = row.catchRate end
  if row.expYield then mon.expYield = row.expYield end
  if row.growthRate then mon.growth = row.growthRate end
  self:recalcStats(mon)
  self:markCaught(target)
  self:incrementGameStat(Game3.GAME_STAT_EVOLVED_POKEMON)
  return oldName, mon.name
end

function Game3:tryEvolve(mon)
  local target = self:checkEvolution(mon)
  if not target then return {} end
  self.pendingEvo = self.pendingEvo or {}
  self.pendingEvo[#self.pendingEvo + 1] = {
    mon = mon,
    from = mon.species,
    fromName = mon.name,
    target = target,
  }
  return {}
end

function Game3:resolvePendingEvolve()
  local n = 0
  while self.pendingEvo and self.pendingEvo[1] and n < 8 do
    n = n + 1
    local e = table.remove(self.pendingEvo, 1)
    self:applyEvolution(e.mon, e.target)
    self:tryLearnLevelMoves(e.mon)
    self:tryEvolve(e.mon)
  end
end

function Game3:startPendingEvolve()
  local q = self.pendingEvo
  if not (q and q[1]) then return false end
  local e = table.remove(q, 1)
  self.evolve = {
    mon = e.mon,
    from = e.from,
    fromName = e.fromName,
    target = e.target,
    t = 0,
    stage = "announce",
  }
  local text = ("What? %s is evolving!"):format(e.fromName)
  if self.phase == "battle" and self.battle then
    self.battle.kind = "evolve"
    self.battle.text = text
    self.battle.printSrc = nil
    self.battle.textPage = 0
    self.battle.queue = nil
  else
    self.field = { kind = "evolve", text = text }
  end
  return true
end

-- pokeruby TryEvolvePokemon then CB2_ReturnToFieldContinueScript.
-- A gym-leader win that levels the starter into its first evo must
-- still gotobeatenscript (Stone Badge) after the animation.
function Game3:finishPostBattleScenes()
  if self:startPendingLearn() then return true end
  if self:startPendingEvolve() then return true end
  if self.tradeEvoWait then
    self:closeTradeEvolution()
    return true
  end
  if self.scriptWait then
    self:runOnResumeFromBattle()
    self:endScriptWait()
    return true
  end
  if self.itemUseThenBag then
    self.itemUseThenBag = nil
    self:openBag()
    return true
  end
  self:closeField()
  return false
end

function Game3:finishEvolveStage()
  local evo = self.evolve
  if not evo then return end
  local fromTrade = evo.fromTrade
  local learned = self:tryLearnLevelMoves(evo.mon)
  self.evolve = nil
  if #learned > 0 then
    if self.phase == "battle" and self.battle then
      self.battle.kind = "text"
      self.battle.queue = learned
      self.battle.qi = 1
      self.battle.text = learned[1]
      self.battle.printSrc = nil
    else
      self.field = {
        kind = "talk", text = learned[1], queue = learned, qi = 1,
        thenLearn = "done",
      }
    end
    return
  end
  if fromTrade then
    if self:startPendingLearn() then return end
    self:closeTradeEvolution()
    return
  end
  if self.phase == "battle" and self.battle then
    if self:startPendingLearn() then return end
    if self:startPendingEvolve() then return end
    self.battle.kind = "text"
    self.battle.queue = nil
    self:advanceBattleText()
  else
    self:finishPostBattleScenes()
  end
end

function Game3:stepEvolve(dt)
  local evo = self.evolve
  if not evo then return false end
  dt = dt or 0
  local box = (self.phase == "battle" and self.battle) or self.field
  if evo.stage == "announce" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      if box and self:printerBusy(box) then
        self:printerFinish(box)
        return true
      end
      evo.stage = "anim"
      evo.t = 0
    end
    return true
  end
  if evo.stage == "anim" then
    evo.t = (evo.t or 0) + dt
    if evo.t >= Game3.EVOLVE_ANIM then
      self:applyEvolution(evo.mon, evo.target)
      evo.stage = "done"
      if evo.fromTrade then
        self:playFanfare(Game3.MUS_EVOLVED)
      end
      if box then
        box.text = ("%s evolved into %s!"):format(
          evo.fromName, self:speciesName(evo.target))
        box.printSrc = nil
        box.textPage = 0
      end
    end
    return true
  end
  if evo.stage == "done" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      if box and self:printerBusy(box) then
        self:printerFinish(box)
        return true
      end
      self:finishEvolveStage()
    end
  end
  return true
end

function Game3:evolveDraw()
  local evo = self.evolve
  if not (evo and evo.stage == "anim") then
    return 1, false, evo and evo.mon and evo.mon.species
  end
  local t = evo.t or 0
  local half = Game3.EVOLVE_ANIM / 2
  local flash = math.floor(t * 16) % 2 == 1
  if t < half then
    return 1 - (t / half) * 0.85, flash, evo.from
  end
  return 0.15 + ((t - half) / half) * 0.85, flash, evo.target
end

function Game3:partyIndexOf(mon)
  if not mon then return nil end
  local party = self.party or {}
  for i = 1, #party do
    if party[i] == mon then return i end
  end
end

function Game3:markSentIn(mon)
  local i = self:partyIndexOf(mon)
  local b = self.battle
  if not (i and b) then return end
  b.sentIn = b.sentIn or {}
  b.sentIn[i] = true
end

function Game3:holdsExpShare(mon)
  local effect = self:holdEffectOf(mon)
  return effect == Game3.HOLD_EFFECT_EXP_SHARE
end

-- pokeruby IsOtherTrainer: a different OT id is always traded; the
-- same id still trades if the OT name disagrees. Missing otId is the
-- pre-Phase-114 save (caught / starter) and counts as own.
function Game3:isOtherTrainer(otId, otName)
  if otId == nil then return false end
  if otId ~= self:ensureTrainerId() then return true end
  if type(otName) ~= "string" or otName == "" then return false end
  return otName ~= self:playerName()
end

function Game3:isTradedMon(mon)
  return mon ~= nil and self:isOtherTrainer(mon.otId, mon.otName)
end

function Game3:giveMonExp(mon, amount, trainer)
  if not mon then return {} end
  amount = math.floor(tonumber(amount) or 0)
  if trainer then amount = math.floor(amount * 3 / 2) end
  local boosted = self:isTradedMon(mon)
  if boosted then amount = math.floor(amount * 3 / 2) end
  if amount < 1 then return {} end
  local verb = boosted and "gained a boosted" or "gained"
  local texts = { ("%s %s %d EXP. Points!"):format(mon.name, verb, amount) }
  local growth = mon.growth or Game3.GROWTH_MEDIUM_SLOW
  mon.exp = (mon.exp or Game3.expAtLevel(growth, mon.level)) + amount
  while (mon.level or 1) < 100 do
    local need = Game3.expAtLevel(growth, (mon.level or 1) + 1)
    if (mon.exp or 0) < need then break end
    mon.level = (mon.level or 1) + 1
    self:recalcStats(mon)
    self:adjustFriendship(mon, Game3.FRIENDSHIP_EVENT_GROW_LEVEL)
    texts[#texts + 1] = ("%s grew to LV. %d!"):format(mon.name, mon.level)
    local learned = self:tryLearnLevelMoves(mon)
    for i = 1, #learned do texts[#texts + 1] = learned[i] end
  end
  local evolved = self:tryEvolve(mon)
  if not (self.phase == "battle" and self.battle) then
    self:resolvePendingEvolve()
  end
  for i = 1, #evolved do texts[#texts + 1] = evolved[i] end
  return texts
end

function Game3:awardExp(winner, fainted, trainer)
  local yield = fainted and fainted.expYield
  if not yield then
    local row = fainted and self:speciesRow(fainted.species)
    yield = row and row.expYield or 0
  end
  local calculated = math.max(1, math.floor((yield or 0)
    * ((fainted and fainted.level) or 1) / 7))
  local party = self.party or {}
  local winnerIdx = self:partyIndexOf(winner)
  if not winnerIdx then
    self:gainEVs(winner, fainted)
    return self:giveMonExp(winner, calculated, trainer)
  end
  local sent = self.battle and self.battle.sentIn
  local hasSent = false
  if type(sent) == "table" then
    for i = 1, #party do
      if sent[i] then hasSent = true break end
    end
  end
  if not hasSent then sent = { [winnerIdx] = true } end
  local viaSent, viaShare = 0, 0
  for i = 1, #party do
    local mon = party[i]
    if self:canBattle(mon) then
      if sent[i] then viaSent = viaSent + 1 end
      if self:holdsExpShare(mon) then viaShare = viaShare + 1 end
    end
  end
  if viaSent < 1 then viaSent = 1 end
  local partShare, shareShare
  if viaShare > 0 then
    partShare = math.max(1, math.floor(calculated / 2 / viaSent))
    shareShare = math.max(1, math.floor(calculated / 2 / viaShare))
  else
    partShare = math.max(1, math.floor(calculated / viaSent))
    shareShare = 0
  end
  local texts = {}
  for i = 1, #party do
    local mon = party[i]
    if self:canBattle(mon) then
      local amount = 0
      if sent[i] then amount = partShare end
      if self:holdsExpShare(mon) then amount = amount + shareShare end
      if amount > 0 then
        self:gainEVs(mon, fainted)
        local lines = self:giveMonExp(mon, amount, trainer)
        for j = 1, #lines do texts[#texts + 1] = lines[j] end
      end
    end
  end
  return texts
end

function Game3:switchTo(index)
  local b = self.battle
  local mon = self.party and self.party[index]
  if not mon then return false, "No POKeMON." end
  -- battle_party_menu.c Task_BattlePartyMenuShift: HP, already out,
  -- then IS_EGG → gOtherText_EGGCantBattle. Field SWITCH of an egg
  -- into slot 1 is legal; battle send-out is not.
  if (mon.hp or 0) <= 0 then return false, "It's out of HP!" end
  if b and (mon == b.player or mon == b.player2) then
    return false, "Already in battle!"
  end
  if mon.isEgg then return false, "An EGG can't battle!" end
  local slot = (b and b.switchSlot) or "player"
  if slot ~= "player" and slot ~= "player2" then slot = "player" end
  local outgoing = b and b[slot]
  local extra = {}
  if outgoing then
    if self:hasAbility(outgoing, Game3.ABILITY_NATURAL_CURE) then
      outgoing.status = nil
      outgoing.sleepTurns = nil
    end
    outgoing.confuseTurns = nil
    outgoing.flinch = nil
    outgoing.flashFire = nil
    outgoing.charging = nil
    outgoing.invuln = nil
    outgoing.bideTurns = nil
    outgoing.bideTaken = nil
    outgoing.bideFrom = nil
    outgoing.protected = nil
    outgoing.protectStreak = nil
    outgoing.endured = nil
    outgoing.mudSport = nil
    outgoing.waterSport = nil
    outgoing.rage = nil
    outgoing.leechSeed = nil
    outgoing.leechSeedSlot = nil
    outgoing.leechSeedFrom = nil
    outgoing.foresight = nil
    outgoing.rooted = nil
    outgoing.perishSong = nil
    outgoing.uproarTurns = nil
    outgoing.uproarMove = nil
    self:restoreSpeciesTypes(outgoing)
  end
  if b then
    b[slot] = mon
    b.switchSlot = nil
    self:markSentIn(mon)
  end
  mon.stages = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
  mon.focusEnergy = nil
  mon.confuseTurns = nil
  mon.flinch = nil
  mon.flashFire = nil
  mon.charging = nil
  mon.invuln = nil
  mon.bideTurns = nil
  mon.bideTaken = nil
  mon.bideFrom = nil
  mon.protected = nil
  mon.protectStreak = nil
  mon.endured = nil
  mon.mudSport = nil
  mon.waterSport = nil
  mon.rage = nil
  mon.leechSeed = nil
  mon.leechSeedSlot = nil
  mon.leechSeedFrom = nil
  mon.foresight = nil
  mon.rooted = nil
  mon.perishSong = nil
  mon.uproarTurns = nil
  mon.uproarMove = nil
  if type(mon.moves) ~= "table" or #mon.moves < 1 then
    mon.moves = self:movesFor(mon.species, mon.level)
  end
  local foe = b and (Game3.aliveMon(b.enemy) and b.enemy or b.enemy2)
  if b and foe then
    extra = self:activateEnter(mon, foe)
  end
  return true, ("Go! %s!"):format(mon.name), extra
end

function Game3.isqrt(n)
  n = math.floor(n or 0)
  if n <= 0 then return 0 end
  local x = n
  local y = math.floor((n + 1) / 2)
  while y < x do
    x = y
    y = math.floor((x + math.floor(n / x)) / 2)
  end
  return x
end

-- pokeemerald: a = (3*max - 2*hp) * catchRate * ballBonus / (3*max)
function Game3.catchValue(hp, maxHp, catchRate, ballBonus)
  maxHp = math.max(1, maxHp or 1)
  hp = math.max(0, math.min(hp or 0, maxHp))
  local a = math.floor(
    (3 * maxHp - 2 * hp) * (catchRate or 45) * (ballBonus or 1) / (3 * maxHp))
  if a < 1 then a = 1 end
  return a
end

-- Four 16-bit rolls must each be < this threshold.
function Game3.shakeThreshold(a)
  if a >= 255 then return 65535 end
  if a < 1 then a = 1 end
  local inner = Game3.isqrt(math.floor(16711680 / a))
  local outer = Game3.isqrt(inner)
  if outer < 1 then outer = 1 end
  return math.floor(1048560 / outer)
end

function Game3.catchFailText(shakes)
  if shakes <= 0 then return "Oh no! The POKeMON broke free!" end
  if shakes == 1 then return "Aww! It appeared to be caught!" end
  if shakes == 2 then return "Aargh! Almost had it!" end
  return "Shoot! It was so close too!"
end

function Game3:cloneMon(mon)
  local copy = {}
  for k, v in pairs(mon or {}) do
    if k ~= "moves" and k ~= "stages" and k ~= "ivs" then copy[k] = v end
  end
  copy.ivs = Game3.copyIvs(mon and mon.ivs)
  copy.stages = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
  copy.moves = {}
  local moves = mon and mon.moves or {}
  for i = 1, #moves do
    local src = moves[i]
    local slot = {}
    if type(src) == "table" then
      for k, v in pairs(src) do slot[k] = v end
    end
    copy.moves[i] = slot
  end
  return copy
end

function Game3:markSeen(species)
  species = tonumber(species)
  if not species or species < 1 then return end
  self.seen = self.seen or {}
  self.seen[species] = true
end

function Game3:hasSeen(species)
  species = tonumber(species)
  return species and ((self.seen and self.seen[species] == true)
    or self:hasCaught(species))
end

function Game3:markCaught(species)
  species = tonumber(species)
  if not species or species < 1 then return end
  self.caught = self.caught or {}
  self.caught[species] = true
  self:markSeen(species)
end

function Game3:hasCaught(species)
  species = tonumber(species)
  return species and self.caught and self.caught[species] == true
end

function Game3:harvestCaught()
  local function take(mon)
    if mon and not mon.isEgg then self:markCaught(mon.species) end
  end
  for i = 1, #(self.party or {}) do take(self.party[i]) end
  self:ensurePc()
  for b = 1, Game3.BOX_COUNT do
    local box = self.pc[b] or {}
    for i = 1, Game3.BOX_SIZE do take(box[i]) end
  end
end

function Game3:snapshotCaught()
  local list = {}
  for id, yes in pairs(self.caught or {}) do
    if yes then list[#list + 1] = id end
  end
  table.sort(list)
  return list
end

function Game3:snapshotSeen()
  local list = {}
  for id, yes in pairs(self.seen or {}) do
    if yes then list[#list + 1] = id end
  end
  table.sort(list)
  return list
end

function Game3:hasPokedex()
  return self.flags and self.flags[Game3.FLAG_SYS_POKEDEX_GET] == true
end

function Game3:hasPokenav()
  return self.flags and self.flags[Game3.FLAG_SYS_POKENAV_GET] == true
end

function Game3:hoennDexOf(species)
  local row = self:speciesRow(species)
  return row and tonumber(row.hoennDex)
end

function Game3:nationalDexOf(species)
  local row = self:speciesRow(species)
  return row and tonumber(row.nationalDex)
end

function Game3:dexListNumber(species)
  if self:hasNationalDex() then
    return self:nationalDexOf(species) or species
  end
  return self:hoennDexOf(species) or species
end

-- sub_8091458 UNITS_IMPERIAL: dm → feet/inches.
function Game3.dexHeightText(height)
  height = tonumber(height) or 0
  local inches = math.floor((height * 10000) / 254)
  if inches % 10 >= 5 then inches = inches + 10 end
  local feet = math.floor(inches / 120)
  inches = math.floor((inches - feet * 120) / 10)
  return ("%d'%02d\""):format(feet, inches)
end

-- sub_8091564 UNITS_IMPERIAL: hectograms → lbs with one tenth.
function Game3.dexWeightText(weight)
  weight = tonumber(weight) or 0
  local lbs = math.floor((weight * 100000) / 4536)
  if lbs % 10 >= 5 then lbs = lbs + 10 end
  local whole = math.floor(lbs / 100)
  local tenth = math.floor((lbs % 100) / 10)
  return ("%d.%d lbs."):format(whole, tenth)
end

function Game3.addedToDexText(name)
  return ("%s's data was\nadded to the POKeDEX."):format(name or "POKeMON")
end

function Game3:dexCategoryText(species, owned)
  if not owned then return "????? POKeMON" end
  local row = self:speciesRow(species)
  local cat = row and row.category
  if type(cat) ~= "string" or cat == "" then return "????? POKeMON" end
  return cat .. " POKeMON"
end

function Game3:dexFlavorText(species, page, owned)
  if not owned then return "" end
  local row = self:speciesRow(species)
  if not row then return "" end
  if (page or 0) >= 1 then return row.dexPage2 or "" end
  return row.dexPage1 or ""
end

function Game3:hasHoennDexTable()
  local by = self.data and self.data.pokemon and self.data.pokemon.byIndex
  if type(by) ~= "table" then return false end
  for _, row in pairs(by) do
    if row and tonumber(row.hoennDex) then return true end
  end
  return false
end

function Game3:inCurrentDex(species)
  species = tonumber(species)
  if not species or species < 1 then return false end
  if self:hasNationalDex() then
    local n = self:nationalDexOf(species)
    if n ~= nil then return n >= 1 and n <= Game3.NATIONAL_DEX_COUNT end
    return true
  end
  local n = self:hoennDexOf(species)
  if n then return n >= 1 and n <= Game3.HOENN_DEX_COUNT end
  if self:hasHoennDexTable() then return false end
  return true
end

function Game3:hasNationalDex()
  return self.flags and self.flags[Game3.FLAG_SYS_NATIONAL_DEX] == true
end

function Game3:enableNationalDex()
  if self:hasNationalDex() then return false end
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_NATIONAL_DEX] = true
  self.scriptVars = self.scriptVars or {}
  self.scriptVars[Game3.VAR_NATIONAL_DEX] = Game3.NATIONAL_DEX_ENABLED
  return true
end

function Game3:completedHoennPokedex()
  local caught = 0
  local mapped = self:hasHoennDexTable()
  for id, yes in pairs(self.caught or {}) do
    if yes then
      if mapped then
        local n = self:hoennDexOf(id)
        if n and n >= 1 and n <= Game3.HOENN_DEX_COMPLETE then
          caught = caught + 1
        end
      else
        caught = caught + 1
      end
    end
  end
  return caught >= Game3.HOENN_DEX_COMPLETE
end

function Game3:giveNationalDex()
  if not self:hasPokedex() then return false end
  if self:hasNationalDex() then return false end
  if not self:completedHoennPokedex() then return false end
  self:enableNationalDex()
  self.field = {
    kind = "talk",
    text = "PROF. BIRCH: Your POKeDEX was upgraded to the National mode!",
  }
  return true
end

function Game3:dexCounts()
  local seen, caught = 0, 0
  local counted = {}
  for id, yes in pairs(self.seen or {}) do
    if yes and self:inCurrentDex(id) and not counted[id] then
      counted[id] = true
      seen = seen + 1
    end
  end
  for id, yes in pairs(self.caught or {}) do
    if yes and self:inCurrentDex(id) then
      if not counted[id] then counted[id] = true; seen = seen + 1 end
      caught = caught + 1
    end
  end
  return seen, caught
end

function Game3:dexEntries()
  local ids = {}
  local have = {}
  for id, yes in pairs(self.seen or {}) do
    if yes and self:inCurrentDex(id) then have[id] = true end
  end
  for id, yes in pairs(self.caught or {}) do
    if yes and self:inCurrentDex(id) then have[id] = true end
  end
  for id, _ in pairs(have) do ids[#ids + 1] = id end
  local national = self:hasNationalDex()
  table.sort(ids, function(a, b)
    local ka, kb
    if national then
      ka = self:nationalDexOf(a) or a
      kb = self:nationalDexOf(b) or b
    else
      ka = self:hoennDexOf(a) or a
      kb = self:hoennDexOf(b) or b
    end
    if ka ~= kb then return ka < kb end
    return a < b
  end)
  local list = {}
  for i = 1, #ids do
    local id = ids[i]
    list[i] = {
      id = id,
      name = self:speciesName(id),
      caught = self:hasCaught(id),
    }
  end
  return list
end

function Game3:pokedexRating(caught)
  caught = caught or 0
  if caught >= 200 then return "You've become a genuine PROFESSOR!" end
  if caught >= 50 then return "Keep going! You're getting somewhere." end
  return "You've still got lots to do. Look for POKeMON in grassy areas!"
end

function Game3:givePokedex()
  if self:hasPokedex() then return false end
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_POKEDEX_GET] = true
  self.flags[Game3.FLAG_HIDE_RIVAL_BIRCH_LAB] = nil
  self:harvestCaught()
  local objects = self.map and self.map.objects
  if type(objects) == "table" and #objects > 0 then
    self:resetNpcs(self.map)
  end
  self.field = {
    kind = "talk",
    text = "PROF. BIRCH: Here's a POKeDEX! Record data on all the POKeMON you see!",
  }
  return true
end

function Game3:openDex()
  self.field = { kind = "dex", cursor = 0, list = self:dexEntries() }
  return true
end

function Game3:openDexEntry(species, opts)
  opts = opts or {}
  species = tonumber(species)
  if not species then return false end
  local owned = opts.owned
  if owned == nil then owned = self:hasCaught(species) end
  if opts.fromCatch then
    local b = self.battle
    if not b then return false end
    b.kind = "dex_entry"
    b.dexSpecies = species
    b.dexPage = 0
    b.dexFromCatch = true
    b.owned = true
    b.text = nil
    b.queue = nil
    self:playMonCry(species)
    return true
  end
  local f = self.field or {}
  self.field = {
    kind = "dex_entry",
    species = species,
    page = 0,
    screen = Game3.DEX_SCREEN_INFO,
    bar = Game3.DEX_SCREEN_INFO,
    owned = owned and true or false,
    list = opts.list or f.list,
    listCursor = opts.listCursor or f.cursor or 0,
  }
  return true
end

function Game3:closeDexEntry()
  local f = self.field
  if f and f.kind == "dex_entry" then
    self.field = {
      kind = "dex",
      cursor = f.listCursor or 0,
      list = f.list or self:dexEntries(),
    }
    return true
  end
  local b = self.battle
  if b and b.kind == "dex_entry" then
    b.dexSpecies = nil
    b.dexPage = nil
    b.dexFromCatch = nil
    self:openCaughtNickAsk()
    return true
  end
  return false
end

function Game3.giveCaughtNickText(name)
  return Game3.TEXT_GIVE_CAUGHT_NICK:format(name or "POKeMON")
end

-- atkF3_trygivecaughtmonnick. Wally's tutorial skips it.
function Game3:openCaughtNickAsk()
  local b = self.battle
  if not (b and b.caught) then return self:finishBattle() end
  if b.wallyTutorial or not b.askCaughtNick then
    return self:finishBattle()
  end
  b.askCaughtNick = nil
  local mon = b.caughtMon
  local name = (mon and mon.name) or "POKeMON"
  b.kind = "catch_nick"
  b.cursor = 0
  b.text = Game3.giveCaughtNickText(name)
  b.queue = nil
  b.printSrc = nil
  b.textPage = 0
  return true
end

function Game3:answerCaughtNick(yes)
  local b = self.battle
  local mon = b and b.caughtMon
  if yes and mon then
    self:finishBattle()
    self:openNickname({ mon = mon, fromCatch = true })
    return true
  end
  return self:finishBattle()
end

function Game3.dexAffineScale(pa)
  pa = tonumber(pa) or Game3.DEX_AFFINE_ONE
  if pa < 1 then pa = Game3.DEX_AFFINE_ONE end
  return Game3.DEX_AFFINE_ONE / pa
end

function Game3:stepDexList(f)
  if Input:wasPressed("b") or Input:wasPressed("start") then
    self.field = { kind = "menu", cursor = 0 }
    return
  end
  local list = f.list or {}
  local n = #list
  if n < 1 then n = 1 end
  if Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
  elseif Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
  elseif Input:wasPressed("a") then
    local row = list[(f.cursor or 0) + 1]
    if row then
      self:openDexEntry(row.id, {
        list = list,
        listCursor = f.cursor or 0,
        owned = row.caught,
      })
    end
  end
end

function Game3:stepDexEntry(state)
  if not state then return end
  local fromCatch = state.dexFromCatch or state.fromCatch
  local owned = state.owned
  if owned == nil then
    owned = self:hasCaught(state.dexSpecies or state.species)
  end
  if fromCatch then
    if Input:wasPressed("b") then
      self:closeDexEntry()
      return
    end
    if not Input:wasPressed("a") then return end
    local page = state.dexPage or state.page or 0
    if page < 1 then
      state.dexPage = 1
      self:playSe(Game3.SE_PIN)
      return
    end
    self:closeDexEntry()
    return
  end
  local screen = state.screen or Game3.DEX_SCREEN_INFO
  if screen ~= Game3.DEX_SCREEN_INFO then
    if Input:wasPressed("b") then
      state.screen = Game3.DEX_SCREEN_INFO
      state.bar = Game3.DEX_SCREEN_INFO
      self:playSe(Game3.SE_PC_OFF)
      return
    end
    if Input:wasPressed("left") then
      if screen == Game3.DEX_SCREEN_CRY then
        state.screen = Game3.DEX_SCREEN_AREA
        state.bar = Game3.DEX_SCREEN_AREA
        self:playSe(Game3.SE_DEX_PAGE)
      elseif screen == Game3.DEX_SCREEN_SIZE then
        state.screen = Game3.DEX_SCREEN_CRY
        state.bar = Game3.DEX_SCREEN_CRY
        self:playSe(Game3.SE_DEX_PAGE)
      elseif screen == Game3.DEX_SCREEN_AREA then
        state.screen = Game3.DEX_SCREEN_INFO
        state.bar = Game3.DEX_SCREEN_INFO
        self:playSe(Game3.SE_DEX_PAGE)
      end
      return
    end
    if Input:wasPressed("right") then
      if screen == Game3.DEX_SCREEN_AREA then
        state.screen = Game3.DEX_SCREEN_CRY
        state.bar = Game3.DEX_SCREEN_CRY
        self:playSe(Game3.SE_DEX_PAGE)
      elseif screen == Game3.DEX_SCREEN_CRY then
        if owned then
          state.screen = Game3.DEX_SCREEN_SIZE
          state.bar = Game3.DEX_SCREEN_SIZE
          self:playSe(Game3.SE_DEX_PAGE)
        else
          self:playSe(Game3.SE_FAILURE)
        end
      end
      return
    end
    if screen == Game3.DEX_SCREEN_CRY and Input:wasPressed("a") then
      self:playMonCry(state.species)
      return
    end
    return
  end
  if Input:wasPressed("b") then
    self:closeDexEntry()
    return
  end
  if Input:wasPressed("left") then
    local bar = state.bar or Game3.DEX_SCREEN_INFO
    if bar > Game3.DEX_SCREEN_INFO then
      state.bar = bar - 1
      self:playSe(Game3.SE_DEX_PAGE)
    end
    return
  end
  if Input:wasPressed("right") then
    local bar = state.bar or Game3.DEX_SCREEN_INFO
    if bar < Game3.DEX_SCREEN_SIZE then
      state.bar = bar + 1
      self:playSe(Game3.SE_DEX_PAGE)
    end
    return
  end
  if not Input:wasPressed("a") then return end
  local bar = state.bar or Game3.DEX_SCREEN_INFO
  if bar == Game3.DEX_SCREEN_INFO then
    if owned then
      local page = state.page or 0
      state.page = 1 - page
      self:playSe(Game3.SE_PIN)
    end
    return
  end
  if bar == Game3.DEX_SCREEN_SIZE and not owned then
    self:playSe(Game3.SE_FAILURE)
    return
  end
  if bar == Game3.DEX_SCREEN_CRY then
    self:playMonCry(state.species)
  end
  state.screen = bar
  self:playSe(Game3.SE_PIN)
end

function Game3:startMenuItems()
  if self:inSafariMode() then
    return {
      "RETIRE", "POKeDEX", "POKeMON", "BAG",
      self:playerName(), "OPTION", "EXIT",
    }
  end
  local items = {}
  if self:hasPokedex() then items[#items + 1] = "POKeDEX" end
  items[#items + 1] = "POKeMON"
  items[#items + 1] = "BAG"
  if self:hasPokenav() then items[#items + 1] = "POKeNAV" end
  items[#items + 1] = self:playerName()
  items[#items + 1] = "SAVE"
  items[#items + 1] = "OPTION"
  items[#items + 1] = "EXIT"
  return items
end

function Game3:startMenuIndex(name)
  local labels = self:startMenuItems()
  for i = 1, #labels do
    if labels[i] == name then return i - 1 end
  end
  return 0
end

function Game3:backToStart(name)
  self.field = { kind = "menu", cursor = self:startMenuIndex(name) }
  return true
end

function Game3:openBag()
  local pocket = self.lastBagPocket
  if type(pocket) ~= "number"
      or pocket < Game3.POCKET_ITEMS or pocket > Game3.POCKET_KEY then
    pocket = self:firstFilledPocket()
  end
  self.lastBagPocket = pocket
  self.field = { kind = "bag", pocket = pocket, cursor = 0 }
  return true
end

-- PlayerHandleOpenBag → sub_80A6DCC RETURN_TO_BATTLE: same pack, pockets,
-- and CLOSE BAG as the field bag.
function Game3:openBattleBag()
  local b = self.battle
  if not b then return false end
  local pocket = b.bagPocket or self.lastBagPocket
  if type(pocket) ~= "number"
      or pocket < Game3.POCKET_ITEMS or pocket > Game3.POCKET_KEY then
    pocket = self:firstFilledPocket()
  end
  b.kind = "bag"
  b.bagPocket = pocket
  b.bagCursor = 0
  self.lastBagPocket = pocket
  return true
end

function Game3:openParty()
  self.field = { kind = "party", cursor = 0 }
  return true
end

function Game3.isTmHm(id)
  id = tonumber(id) or 0
  return id >= Game3.ITEM_TM01 and id <= Game3.ITEM_HM_DIVE
end

function Game3.tmhmIndex(id)
  if not Game3.isTmHm(id) then return nil end
  return id - Game3.ITEM_TM01
end

function Game3:tmhmMove(item)
  local tm = Game3.tmhmIndex(item)
  if not tm then return nil end
  local list = self.data and self.data.moves and self.data.moves.tmhmMoves
  if type(list) ~= "table" then list = Game3.TMHM_MOVES end
  return list[tm + 1]
end

-- item_menu.c prints gMoveNames[ItemIdToBattleMoveId] next to the TM/HM.
function Game3:tmhmMoveName(item)
  local moveId = self:tmhmMove(item)
  if not moveId then return nil end
  return self:moveName(moveId)
end

function Game3:canLearnTMHM(mon, item)
  if not mon or mon.isEgg then return false end
  local tm = Game3.tmhmIndex(item)
  if not tm then return false end
  local row = self:speciesRow(mon.species)
  local bits = row and row.tmhm
  if type(bits) ~= "table" then return false end
  local word = tm < 32 and (bits[1] or 0) or (bits[2] or 0)
  local bit = tm < 32 and tm or (tm - 32)
  return math.floor(word / (2 ^ bit)) % 2 == 1
end

-- pokemon_menu.c sub_808AE8C: DrawMonDescriptorStatus over the HP bar.
-- Egg / !CanMonLearnTMHM is 0x9A NOT ABLE, pokemon_has_move is 0xA8
-- LEARNED, otherwise 0x8C ABLE.
function Game3:tmhmPartyLabel(mon, item)
  if not mon then return nil end
  local moveId = self:tmhmMove(item)
  if not moveId then return nil end
  if not self:canLearnTMHM(mon, item) then return "NOT ABLE" end
  if self:knowsMove(mon, moveId) then return "LEARNED" end
  return "ABLE"
end

function Game3:openPartyTeach(item, from)
  if not from then
    from = "field"
    if self.field and (self.field.kind == "bag" or self.field.from == "bag") then
      from = "bag"
    end
  end
  self.field = { kind = "party_teach", cursor = 0, item = item, from = from }
  return true
end

-- pokemon_menu.c sub_808B020 ITEM_USE_SINGLE_MON, prompt OtherText_UseWhat.
function Game3:openPartyUse(item)
  local from = "field"
  if self.field and self.field.kind == "bag" then from = "bag" end
  self.field = {
    kind = "party_use",
    cursor = 0,
    item = item,
    from = from,
    prompt = "Use on which POKeMON?",
  }
  return true
end

function Game3:leavePartyItemUse()
  local f = self.field
  -- SELECT-registered use has no bag underneath; B closes to the field.
  -- Bag USE (and party_teach with no from) fades back to the pack.
  if f and f.from == "field" then
    self:closeField()
    return true
  end
  return self:openBag()
end

function Game3:chooseUseMon(index)
  local f = self.field
  local item = f and f.item
  local from = f and f.from
  local mon = (self.party or {})[index]
  if not mon then return false end
  -- sub_808B0C0: IS_EGG → SE_FAILURE and stay on the picker.
  if mon.isEgg then return false end
  return self:presentItemUseResult(mon, item, from, index)
end

function Game3:presentItemUseResult(mon, item, from, index, moveIndex)
  local ok, msg, extra = self:useItemOnMon(mon, item, moveIndex)
  if extra == "pick_move" then
    local prompt = Game3.PP_UP[item] and "Boost PP of which move?"
      or "Restore which move?"
    self.field = {
      kind = "party_pp",
      cursor = 0,
      monIndex = index,
      item = item,
      from = from,
      prompt = prompt,
    }
    return true
  end
  local thenPending = (self.pendingLearn and self.pendingLearn[1] ~= nil)
      or (self.pendingEvo and self.pendingEvo[1] ~= nil)
  if from == "bag" and (thenPending or (ok and Game3.EVO_STONE[item])) then
    self.itemUseThenBag = true
  else
    self.itemUseThenBag = nil
  end
  -- DoEvolutionStoneItemEffect: no success text, BeginEvolutionScene.
  if ok and Game3.EVO_STONE[item] then
    if self:startPendingEvolve() then
      if self.field then
        self.field.thenBag = from == "bag" or nil
      end
      return true
    end
  end
  local candy = self.candyGrowth
  self.candyGrowth = nil
  if ok then self:playSe(Game3.SE_USE_ITEM) end
  self.field = {
    kind = "talk",
    text = msg or "It won't have any effect.",
    thenBag = from == "bag" or nil,
    thenPending = thenPending or nil,
    thenCandy = candy,
  }
  return true
end

function Game3:teachTMHM(index, item, forgetSlot)
  local mon = (self.party or {})[index]
  if not mon then return false, "There's no one here." end
  local moveId = self:tmhmMove(item)
  if not moveId then return false, "It won't have any effect." end
  local slot = self:copyMove(moveId)
  local name = (slot and slot.name) or "MOVE"
  if self:knowsMove(mon, moveId) then
    return false, ("%s already knows %s."):format(mon.name or "POKeMON", name)
  end
  if not self:canLearnTMHM(mon, item) then
    return false, ("%s can't learn %s."):format(mon.name or "POKeMON", name)
  end
  local moves = mon.moves or {}
  mon.moves = moves
  if forgetSlot then
    forgetSlot = tonumber(forgetSlot) or 0
    if forgetSlot < 1 or forgetSlot > #moves then
      return false, "Which move should be forgotten?"
    end
    moves[forgetSlot] = slot
  elseif #moves >= 4 then
    return false, ("%s wants to learn %s."):format(
      mon.name or "POKeMON", name), true
  else
    moves[#moves + 1] = slot
  end
  if item < Game3.ITEM_HM_CUT then self:takeItem(item, 1) end
  return true, ("%s learned %s!"):format(mon.name or "POKeMON", name)
end

function Game3:chooseTeachMon(index)
  local item = self.field and self.field.item
  local ok, msg, needForget = self:teachTMHM(index, item)
  if needForget then
    self.field = {
      kind = "party_forget", cursor = 0, monIndex = index, item = item,
    }
    return true
  end
  self.field = { kind = "talk", text = msg }
  return ok
end

function Game3:openPartyAction(index)
  local mon = (self.party or {})[index]
  if not mon then return false end
  self.field = {
    kind = "party_action",
    cursor = 0,
    monIndex = index,
    actions = self:partyActions(mon),
  }
  return true
end

function Game3:openPartySummary(index, mon)
  mon = mon or (self.party or {})[index]
  if not mon then return false end
  local fromPc = self.field and self.field.kind == "pc" and self.field or nil
  self.field = {
    kind = "party_summary",
    cursor = 0,
    monIndex = index or 1,
    page = 0,
    mon = mon,
    fromPc = fromPc,
  }
  return true
end

function Game3:ensureTrainerId()
  if type(self.trainerId) == "number" and self.trainerId >= 0 then
    return self.trainerId
  end
  local lo = self:rand(65536) - 1
  local hi = self:rand(65536) - 1
  if lo < 0 then lo = 0 end
  if hi < 0 then hi = 0 end
  self.trainerId = hi * 65536 + lo
  return self.trainerId
end

function Game3:trainerIdString()
  return ("%05d"):format(self:ensureTrainerId() % 65536)
end

function Game3:moneyString(n)
  n = math.floor(tonumber(n) or self.money or 0)
  if n < 0 then n = 0 end
  if n > 999999 then n = 999999 end
  local s = tostring(n)
  local grouped = s:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
  return "$" .. grouped
end

-- pokeruby OpenMoneyWindow: 8x8 tiles, 14x4 frame. Museum / Seashore
-- House use (0, 0). hidemoneybox closes it; updatemoneybox reprints.
function Game3:showMoneyBox(x, y)
  self.moneyBox = { x = tonumber(x) or 0, y = tonumber(y) or 0 }
end

function Game3:hideMoneyBox()
  self.moneyBox = nil
end

function Game3:updateMoneyBox()
  if self.moneyBox then return true end
end

function Game3:drawMoneyBox()
  local box = self.moneyBox
  if not box then return end
  local f = self.field
  if f then
    local kind = f.kind
    if kind == "menu" or kind == "bag" or kind == "option"
        or kind == "trainer_card" or kind == "save_ask"
        or kind == "party" or kind == "party_switch"
        or kind == "party_teach" or kind == "party_use"
        or kind == "party_action"
        or kind == "party_item" or kind == "party_summary"
        or kind == "party_forget" or kind == "party_pp"
        or kind == "learn_forget"
        or kind == "learn_yesno" or kind == "learn_stop"
        or kind == "fishing" then
      return
    end
  end
  local tile = 8
  local x = (box.x or 0) * tile
  local y = (box.y or 0) * tile
  self:drawWindow(x, y, 14 * tile, 4 * tile)
  love.graphics.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(self:moneyString(), x + 16, y + 8)
end

function Game3:drawCoinsBox()
  local box = self.coinsBox
  if not box then return end
  local tile = 8
  local x = (box.x or 0) * tile
  local y = (box.y or 0) * tile
  self:drawWindow(x, y, 10 * tile, 4 * tile)
  love.graphics.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(("COINS %d"):format(self:getCoins()), x + 8, y + 8)
end

-- Ruby's cries are cart samples in gCryTable, so they go through Mp2kAudio
-- like everything else. The Gen 1/2 Sound.playCry path is only a fallback
-- for a cache imported before the cry tables were extracted.
function Game3:playMonCry(species, _mode)
  species = tonumber(species) or 0
  local engine = Mp2kSynth.newCryEngine(self.data, species)
  if engine then
    self.monCrySrc = Mp2kAudio.playVoice("cry", engine)
    if self.monCrySrc then return end
  end
  local ok, Sound = pcall(require, "src.core.Sound")
  if not ok or type(Sound) ~= "table" or not Sound.playCry then
    self.monCrySrc = nil
    return
  end
  self.monCrySrc = Sound.playCry(self.data or {}, self:speciesName(species))
end

function Game3:cryPlaying()
  if Mp2kAudio.voicePlaying("cry") then return true end
  local src = self.monCrySrc
  if not src then return false end
  local playing = false
  if type(src.isPlaying) == "function" then
    playing = src:isPlaying() and true or false
  end
  if not playing then self.monCrySrc = nil end
  return playing
end

function Game3:waitMonCry()
  if not self:cryPlaying() then return end
  self.waitingCry = true
  self:beginScriptWait()
end

function Game3:saveMapName()
  local map = self.map
  if type(map) ~= "table" then return "?????" end
  local name = map.name or map.id or "?????"
  return tostring(name)
end

function Game3:cardStars()
  local n = 0
  if self:hasPokedex() then n = n + 1 end
  if self:completedHoennPokedex() then n = n + 1 end
  return n
end

function Game3:openTrainerCard()
  self:ensureTrainerId()
  self.field = { kind = "trainer_card" }
  return true
end

function Game3:openSaveAsk()
  self.field = {
    kind = "save_ask",
    cursor = 0,
    text = "Would you like to SAVE the game?",
  }
  return true
end

function Game3:confirmSave()
  local ok, msg = self:writeSave()
  if ok then
    self.field = {
      kind = "talk",
      text = (self:playerName() .. " saved the game."),
    }
  else
    self.field = { kind = "talk", text = msg or "Save failed." }
  end
  return ok
end

function Game3:inGameTradeRow(id)
  return Game3.INGAME_TRADES[tonumber(id) or 0]
end

function Game3:getInGameTradeSpeciesInfo()
  local row = self:inGameTradeRow(self:varGet(0x8004))
  if not row then
    self:setScriptVar(Gen3Script.VAR_RESULT, 0)
    return 0
  end
  self:setStringVar(1, self:speciesName(row.playerSpecies))
  self:setStringVar(2, self:speciesName(row.species))
  self:setScriptVar(Gen3Script.VAR_RESULT, row.playerSpecies)
  return row.playerSpecies
end

function Game3:selectMonForNpcTrade()
  self:beginScriptWait()
  self.field = { kind = "npc_trade", cursor = 0, scripted = true }
  return true
end

function Game3:getTradeSpecies()
  local idx = (self:varGet(0x8005) or 0) + 1
  local mon = self.party and self.party[idx]
  local species = 0
  if mon and not mon.isEgg then species = tonumber(mon.species) or 0 end
  self:setScriptVar(Gen3Script.VAR_RESULT, species)
  return species
end

function Game3:createInGameTradePokemon()
  local trade = self:inGameTradeRow(self:varGet(0x8004))
  local idx = (self:varGet(0x8005) or 0) + 1
  local given = self.party and self.party[idx]
  if not trade or not given then return false end
  local mon = self:makeMon(trade.species, given.level or 5)
  mon.name = trade.name
  mon.pid = trade.pid or mon.pid
  mon.otId = trade.otId
  mon.otName = trade.otName
  mon.otGender = trade.otGender
  mon.item = trade.item
  mon.cool = trade.cool
  mon.beauty = trade.beauty
  mon.cute = trade.cute
  mon.smart = trade.smart
  mon.tough = trade.tough
  mon.sheen = trade.sheen
  mon.metLocation = 0xFE
  if trade.ivs then
    mon.ivs = {
      hp = trade.ivs.hp, atk = trade.ivs.atk, def = trade.ivs.def,
      spe = trade.ivs.spe, spa = trade.ivs.spa, spd = trade.ivs.spd,
    }
  end
  self:setAbility(mon)
  if trade.secondAbility then
    local row = self:speciesRow(mon.species)
    if row and (row.ability2 or 0) ~= 0 then mon.ability = row.ability2 end
  end
  self:recalcStats(mon)
  mon.hp = mon.maxHp
  -- ROM CreateInGameTradePokemon writes gEnemyParty[0]. The party swap
  -- is DoInGameTradeScene / sub_804BA94.
  self.inGameTradeIncoming = mon
  self.inGameTradeSentName = given.name or self:speciesName(given.species)
  return true
end

function Game3:finishInGameTrade()
  local idx = (self:varGet(0x8005) or 0) + 1
  local mon = self.inGameTradeIncoming
  if not mon or not self.party or not self.party[idx] then return false end
  self.party[idx] = mon
  self.inGameTradeIncoming = nil
  self:markCaught(mon.species)
  return true
end

function Game3:doInGameTradeScene()
  local trade = self:inGameTradeRow(self:varGet(0x8004))
  local idx = (self:varGet(0x8005) or 0) + 1
  local given = self.party and self.party[idx]
  local sent = self.inGameTradeSentName
  if not sent then
    sent = (given and given.name) or "POKeMON"
  end
  local ot = (trade and trade.otName) or "TRAINER"
  local incoming = self.inGameTradeIncoming
  local got = (incoming and incoming.name)
    or (trade and trade.name) or "POKeMON"
  self:beginScriptWait()
  self.field = {
    kind = "trade_scene",
    t = 0,
    text = ("%s will be sent to %s."):format(sent, ot),
    queue = {
      ("%s will be sent to %s."):format(sent, ot),
      ("Bye-bye, %s!"):format(sent),
      ("%s sent over %s."):format(ot, got),
      ("Take good care of %s!"):format(got),
    },
    qi = 1,
    swapped = false,
    sentSpecies = given and given.species,
    gotSpecies = incoming and incoming.species
      or (trade and trade.species),
  }
  self:playSong(Game3.MUS_EVOLUTION, true)
  return true
end

function Game3:stepTradeScene(dt)
  local f = self.field
  if not (f and f.kind == "trade_scene") then return end
  local frames = math.floor((dt or 0) * 60 + 0.0001)
  if frames < 1 then frames = 0 end
  local pose = Game3.tradeScenePose(f.t or 0)
  if not pose.waitA then
    f.t = (f.t or 0) + frames
    pose = Game3.tradeScenePose(f.t)
  end
  local queue = f.queue or {}
  local line = pose.line or 1
  if queue[line] and f.qi ~= line then
    f.qi = line
    f.text = queue[line]
    f.textPage = 0
    f.printSrc = nil
    if line == 3 and not f.fanfare then
      self:playFanfare(Game3.MUS_EVOLVED)
      f.fanfare = true
    end
  end
  if pose.waitA and (Input:wasPressed("a") or Input:wasPressed("b")) then
    if not f.swapped then
      self:finishInGameTrade()
      f.swapped = true
    end
    self:afterInGameTradeSwap()
  end
end

-- trade.c case 72: GetEvolutionTargetSpecies type 1, then
-- TradeEvolutionScene. Cannot B-cancel (TASK_BIT_CAN_STOP is off).
function Game3:startTradeEvolution(mon, target)
  if not (mon and target) then return false end
  self.tradeEvoWait = true
  self.evolve = {
    mon = mon,
    from = mon.species,
    fromName = mon.name,
    target = target,
    t = 0,
    stage = "announce",
    cannotStop = true,
    fromTrade = true,
  }
  self.field = {
    kind = "evolve",
    text = ("What? %s is evolving!"):format(mon.name),
    fromTrade = true,
  }
  self:playSong(Game3.MUS_EVOLUTION, true)
  return true
end

function Game3:closeTradeEvolution()
  self.tradeEvoWait = nil
  self.evolve = nil
  self.field = nil
  self:playMapMusic()
  self:endScriptWait()
end

function Game3:afterInGameTradeSwap()
  local idx = (self:varGet(0x8005) or 0) + 1
  local mon = self.party and self.party[idx]
  local target = self:checkTradeEvolution(mon)
  if target and self:startTradeEvolution(mon, target) then
    return true
  end
  self.field = nil
  self:playMapMusic()
  self:endScriptWait()
  return false
end

-- pokeruby GetLeadMonIndex: first party slot that is not SPECIES_NONE
-- or SPECIES_EGG (SPECIES2).
function Game3:partyMonSpecies2(mon)
  if not mon then return 0 end
  if mon.isEgg then return Game3.SPECIES_EGG end
  return tonumber(mon.species) or 0
end

function Game3:leadMonIndex()
  local party = self.party or {}
  for i = 1, #party do
    local sp = self:partyMonSpecies2(party[i])
    if sp ~= 0 and sp ~= Game3.SPECIES_EGG then return i end
  end
  return 1
end

function Game3:leadMon()
  return self.party and self.party[self:leadMonIndex()]
end

function Game3:selectedPartyMon()
  local idx = ((self.scriptVars and self.scriptVars[0x8004]) or 0) + 1
  return self.party and self.party[idx]
end

function Game3:monEvCount(mon)
  if not mon then return 0 end
  local n = 0
  for i = 1, #Game3.EV_KEYS do
    n = n + (mon[Game3.EV_KEYS[i]] or 0)
  end
  return n
end

-- pokeruby pokemon_3.c MonGainEVs: each exp-getter gets the full
-- defeated-species evYield. Pokerus (byte != 0) is 2x; Macho Brace is
-- another 2x. Per-stat 255 and party total 510.
function Game3:gainEVs(mon, fainted)
  if not mon or mon.isEgg then return end
  local row = fainted and self:speciesRow(fainted.species) or {}
  local multiplier = 1
  if (mon.pokerus or 0) ~= 0 then multiplier = 2 end
  local hold = self:holdEffectOf(mon)
  if hold == Game3.HOLD_EFFECT_MACHO_BRACE then
    multiplier = multiplier * 2
  end
  local total = self:monEvCount(mon)
  for i = 1, #Game3.EV_KEYS do
    if total >= Game3.MAX_TOTAL_EVS then break end
    local key = Game3.EV_KEYS[i]
    local yieldKey = Game3.EV_YIELD_KEYS[i]
    local yield = tonumber(row[yieldKey])
    if not yield and fainted then
      yield = tonumber(fainted[yieldKey])
    end
    local evIncrease = (yield or 0) * multiplier
    if total + evIncrease > Game3.MAX_TOTAL_EVS then
      evIncrease = Game3.MAX_TOTAL_EVS - total
    end
    local current = mon[key] or 0
    if current + evIncrease > 255 then
      evIncrease = 255 - current
    end
    if evIncrease > 0 then
      mon[key] = current + evIncrease
      total = total + evIncrease
    end
  end
end

function Game3:incrementGameStat(id)
  id = tonumber(id) or 0
  self.gameStats = self.gameStats or {}
  local n = (self.gameStats[id] or 0) + 1
  if n > 0xFFFFFF then n = 0xFFFFFF end
  self.gameStats[id] = n
end

-- pokemon_item_effect.c ITEM5_FRIENDSHIP_LOW/MID/HIGH. Negative herbal
-- deltas skip Soothe Bell / Luxury Ball / met-location bonuses.
function Game3:applyItemFriendship(mon, itemId)
  if not mon or mon.isEgg then return false end
  local deltas = Game3.ITEM_FRIENDSHIP[tonumber(itemId)]
  if not deltas then return false end
  local friendship = tonumber(mon.friendship) or Game3.BASE_FRIENDSHIP
  local d = deltas[1] or 0
  if friendship >= 200 then
    d = deltas[3] or d
  elseif friendship >= 100 then
    d = deltas[2] or d
  end
  if d > 0 then
    local hold = self:holdEffectOf(mon)
    if hold == Game3.HOLD_EFFECT_HAPPINESS_UP then
      d = math.floor(150 * d / 100)
    end
  end
  friendship = friendship + d
  if friendship < 0 then friendship = 0 end
  if friendship > Game3.MAX_FRIENDSHIP then friendship = Game3.MAX_FRIENDSHIP end
  mon.friendship = friendship
  return true
end

function Game3:adjustFriendship(mon, event)
  if not mon or mon.isEgg then return false end
  event = tonumber(event) or 0
  local deltas = Game3.FRIENDSHIP_DELTAS[event]
  if not deltas then return false end
  if event == Game3.FRIENDSHIP_EVENT_WALKING
      and (self:gbaRandom() % 2) ~= 0 then
    return false
  end
  if event == Game3.FRIENDSHIP_EVENT_LEAGUE_BATTLE
      and not self:isLeagueTrainer(self.battle and self.battle.npc) then
    return false
  end
  local friendship = tonumber(mon.friendship) or Game3.BASE_FRIENDSHIP
  local level = 0
  if friendship > 99 then level = level + 1 end
  if friendship > 199 then level = level + 1 end
  local delta = deltas[level + 1] or 0
  if delta > 0 then
    local hold = self:holdEffectOf(mon)
    if hold == Game3.HOLD_EFFECT_HAPPINESS_UP then
      delta = math.floor(150 * delta / 100)
    end
  end
  friendship = friendship + delta
  if friendship < 0 then friendship = 0 end
  if friendship > Game3.MAX_FRIENDSHIP then friendship = Game3.MAX_FRIENDSHIP end
  mon.friendship = friendship
  return true
end

function Game3:isLeagueTrainer(npc)
  local class = npc and tonumber(npc.trainerClass)
  if not class then
    local tr = npc and self:trainerRow(npc.trainerId)
    class = tr and tonumber(tr.class)
  end
  return class == Game3.TRAINER_CLASS_LEADER
    or class == Game3.TRAINER_CLASS_ELITE_FOUR
    or class == Game3.TRAINER_CLASS_CHAMPION
end

function Game3:applyLeagueFriendship(npc)
  if not self:isLeagueTrainer(npc) then return end
  local party = self.party or {}
  for i = 1, #party do
    self:adjustFriendship(party[i], Game3.FRIENDSHIP_EVENT_LEAGUE_BATTLE)
  end
end

function Game3:maybeFaintFriendship(fainted, foe)
  if not fainted then return end
  if (fainted.hp or 0) > 0 then
    fainted._faintFriend = nil
    return
  end
  if not self:isPlayerBattler(fainted) then return end
  if fainted._faintFriend then return end
  fainted._faintFriend = true
  local r = self.battleResults
  if r and (r.playerFaintCounter or 0) < 255 then
    r.playerFaintCounter = (r.playerFaintCounter or 0) + 1
  end
  local foeLevel = (foe and foe.level) or 0
  local myLevel = fainted.level or 1
  if foeLevel <= myLevel then return end
  local event = Game3.FRIENDSHIP_EVENT_FAINT_SMALL
  if foeLevel - myLevel > 29 then
    event = Game3.FRIENDSHIP_EVENT_FAINT_LARGE
  end
  self:adjustFriendship(fainted, event)
end

function Game3:tickHappinessSteps()
  local n = self:varGet(Game3.VAR_HAPPINESS_STEP_COUNTER) + 1
  n = n % 128
  self:setScriptVar(Game3.VAR_HAPPINESS_STEP_COUNTER, n)
  if n ~= 0 then return end
  local party = self.party or {}
  for i = 1, #party do
    self:adjustFriendship(party[i], Game3.FRIENDSHIP_EVENT_WALKING)
  end
end

function Game3:leadMonFriendshipScore()
  local mon = self:leadMon()
  local n = (mon and tonumber(mon.friendship)) or 0
  if n == Game3.MAX_FRIENDSHIP then return 6 end
  if n >= 200 then return 5 end
  if n >= 150 then return 4 end
  if n >= 100 then return 3 end
  if n >= 50 then return 2 end
  if n >= 1 then return 1 end
  return 0
end

function Game3:swapRegisteredBike()
  local id = tonumber(self.registeredItem) or 0
  if id == Game3.ITEM_MACH_BIKE then
    self.registeredItem = Game3.ITEM_ACRO_BIKE
  elseif id == Game3.ITEM_ACRO_BIKE then
    self.registeredItem = Game3.ITEM_MACH_BIKE
  end
  return self.registeredItem or 0
end

function Game3:leadMonContestOk(key)
  local mon = self:leadMon()
  return ((mon and mon[key]) or 0) >= Game3.CONTEST_LEAD_STAT
end

function Game3:copyNicknameToStringVar1()
  local mon = self:selectedPartyMon()
  local nick = (mon and mon.name) or ""
  if #nick > Game3.NICKNAME_LEN then nick = nick:sub(1, Game3.NICKNAME_LEN) end
  self:setStringVar(1, nick)
end

function Game3:nameRaterNicknameChanged()
  local mon = self:selectedPartyMon()
  local old = (self.stringVars and self.stringVars[3]) or ""
  local now = (mon and mon.name) or ""
  if old == now then return 0 end
  return 1
end

function Game3:checkMonOtIdEqualsPlayer()
  local mon = self:selectedPartyMon()
  local ot = mon and mon.otId
  if ot == nil then return 0 end
  if ot == self:ensureTrainerId() then return 0 end
  return 1
end

function Game3:monOtNameMatchesPlayer()
  local mon = self:selectedPartyMon()
  local otName = (mon and mon.otName) or ""
  self:setStringVar(1, otName)
  if otName == "" then return 0 end
  if otName == self:playerName() then return 0 end
  return 1
end

function Game3:playerAvatarBike()
  if self.bike == "acro" then return 1 end
  if self.bike == "mach" then return 2 end
  return 0
end

function Game3:tryAdvanceCyclingRoadCollisions()
  if not self.bikeCyclingChallenge then return end
  local n = self.bikeCollisions or 0
  if n < Game3.CYCLING_ROAD_MAX_COLLISIONS then
    self.bikeCollisions = n + 1
  end
end

function Game3:beginCyclingRoadChallenge()
  self.bikeCyclingChallenge = true
  self.bikeCollisions = 0
  self.bikeCyclingTimer = self.vblankCounter or 0
end

function Game3:cyclingRoadCollisionString(n)
  n = tonumber(n) or 0
  if n > 99 then return Game3.TEXT_99_TIMES end
  return tostring(n) .. Game3.TEXT_TIMES
end

function Game3:cyclingRoadTimeString(numFrames)
  numFrames = tonumber(numFrames) or 0
  if numFrames >= 3600 then return Game3.TEXT_1_MINUTE end
  local sec = math.floor(numFrames / 60)
  local frac = math.floor(((numFrames % 60) * 100) / 60)
  return ("%2d.%02d"):format(sec, frac) .. Game3.TEXT_SECONDS
end

function Game3:determineCyclingRoadResults(numFrames, collisions)
  numFrames = tonumber(numFrames) or 0
  collisions = tonumber(collisions) or 0
  local result = 0
  if collisions == 0 then
    result = 5
  elseif collisions < 4 then
    result = 4
  elseif collisions < 10 then
    result = 3
  elseif collisions < 20 then
    result = 2
  elseif collisions < 100 then
    result = 1
  end
  local sec = math.floor(numFrames / 60)
  if sec <= 10 then
    result = result + 5
  elseif sec <= 15 then
    result = result + 4
  elseif sec <= 20 then
    result = result + 3
  elseif sec <= 40 then
    result = result + 2
  elseif sec < 60 then
    result = result + 1
  end
  self:setStringVar(1, self:cyclingRoadCollisionString(collisions))
  self:setStringVar(2, self:cyclingRoadTimeString(numFrames))
  self:setScriptVar(Gen3Script.VAR_RESULT, result)
  return result
end

function Game3:recordCyclingRoadResults(numFrames, collisions)
  numFrames = tonumber(numFrames) or 0
  collisions = tonumber(collisions) or 0
  local low = self:varGet(Game3.VAR_CYCLING_ROAD_RECORD_TIME_L)
  local high = self:varGet(Game3.VAR_CYCLING_ROAD_RECORD_TIME_H)
  local framesRecord = low + high * 65536
  if framesRecord > numFrames or framesRecord == 0 then
    self:setScriptVar(Game3.VAR_CYCLING_ROAD_RECORD_TIME_L, numFrames % 65536)
    self:setScriptVar(Game3.VAR_CYCLING_ROAD_RECORD_TIME_H,
      math.floor(numFrames / 65536))
    self:setScriptVar(Game3.VAR_CYCLING_ROAD_RECORD_COLLISIONS, collisions)
  end
end

function Game3:finishCyclingRoadChallenge()
  local numFrames = (self.vblankCounter or 0) - (self.bikeCyclingTimer or 0)
  if numFrames < 0 then numFrames = 0 end
  local collisions = self.bikeCollisions or 0
  local result = self:determineCyclingRoadResults(numFrames, collisions)
  self:recordCyclingRoadResults(numFrames, collisions)
  return result
end

function Game3:getRecordedCyclingRoadResults()
  local low = self:varGet(Game3.VAR_CYCLING_ROAD_RECORD_TIME_L)
  local high = self:varGet(Game3.VAR_CYCLING_ROAD_RECORD_TIME_H)
  local framesRecord = low + high * 65536
  if framesRecord == 0 then return 0 end
  self:determineCyclingRoadResults(framesRecord,
    self:varGet(Game3.VAR_CYCLING_ROAD_RECORD_COLLISIONS))
  return 1
end

function Game3:updateCyclingRoadState()
  local last = self.lastUsedWarp
  if last
      and last.mapGroup == Game3.MAP_ROUTE110_CYCLING_NORTH_GROUP
      and last.mapNum == Game3.MAP_ROUTE110_CYCLING_NORTH_NUM then
    return
  end
  local state = self:varGet(Game3.VAR_CYCLING_CHALLENGE_STATE)
  if state == 2 or state == 3 then
    self:setScriptVar(Game3.VAR_CYCLING_CHALLENGE_STATE, 0)
  end
end

